INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'objectives','trueFalse · 1','1','{"section":"trueFalse","number":1,"text":"Measurement is essentially a comparison process.","answer":true}'::jsonb,1,true),
