(10,'objectives','trueFalse · 4','8','{"section":"trueFalse","number":4,"text":"Reflection is the phenomenon where light incident on a surface is sent back.","answer":true}'::jsonb,4,true),
(10,'objectives','trueFalse · 5','8','{"section":"trueFalse","number":5,"text":"A ray of light is represented by a simple straight line without an arrow-head.","answer":false}'::jsonb,5,true),
(10,'objectives','trueFalse · 6','8','{"section":"trueFalse","number":6,"text":"Light rays that move away from each other are called convergent rays.","answer":false}'::jsonb,6,true),
