(10,'objectives','trueFalse · 12','8','{"section":"trueFalse","number":12,"text":"Reflected rays appear to diverge from a virtual image in a plane mirror.","answer":true}'::jsonb,12,true),
(10,'objectives','trueFalse · 13','8','{"section":"trueFalse","number":13,"text":"Plane mirrors eliminate parallax errors in the reading of instrument scales.","answer":true}'::jsonb,13,true),
(10,'objectives','trueFalse · 14','8','{"section":"trueFalse","number":14,"text":"A periscope uses plane mirrors to see objects when the view is obstructed.","answer":true}'::jsonb,14,true),
