(10,'objectives','fillBlank · 18','10','{"section":"fillBlank","number":18,"text":"The end of the steel bar where the strokes finish always has the _______ polarity to the stroking magnet.","answer":["opposite"]}'::jsonb,38,true),
(10,'objectives','fillBlank · 19','10','{"section":"fillBlank","number":19,"text":"The most effective way to make powerful magnets is by using the magnetic effect of an _______. electric","answer":["current"]}'::jsonb,39,true),
(10,'objectives','fillBlank · 20','10','{"section":"fillBlank","number":20,"text":"A _______ is a coil of wire used in the electrical method of magnetisation.","answer":["solenoid"]}'::jsonb,40,true),
