(10,'objectives','fillBlank · 24','10','{"section":"fillBlank","number":24,"text":"Iron can be successfully magnetised even by a _______ magnetic field.","answer":["weak"]}'::jsonb,44,true),
(10,'objectives','fillBlank · 25','10','{"section":"fillBlank","number":25,"text":"Steel is used in the making of _______ magnets for items like bar magnets.","answer":["permanent"]}'::jsonb,45,true),
