(10,'objectives','multipleChoice · 4','10','{"section":"multipleChoice","number":4,"text":"Permanent magnets are often made from which alloy?","options":["brass","alcomax","bronze"],"correct":1}'::jsonb,49,true),
(10,'objectives','multipleChoice · 5','10','{"section":"multipleChoice","number":5,"text":"Which material is considered non-magnetic in physics?","options":["iron","steel","wood"],"correct":2}'::jsonb,50,true),
(10,'objectives','multipleChoice · 6','10','{"section":"multipleChoice","number":6,"text":"Magnetite is identified as what type of magnet?","options":["artificial","natural","temporary"],"correct":1}'::jsonb,51,true),
(10,'objectives','multipleChoice · 7','10','{"section":"multipleChoice","number":7,"text":"If a magnetized steel bar is cut into three pieces, how many magnets are formed?","options":["one","zero","three"],"correct":2}'::jsonb,52,true),
(10,'objectives','multipleChoice · 8','10','{"section":"multipleChoice","number":8,"text":"According to the theory of magnetism, a magnet is composed of many ____.","options":["tiny magnets","electric charges","magnetic fluids"],"correct":0}'::jsonb,53,true),
(10,'objectives','multipleChoice · 9','10','{"section":"multipleChoice","number":9,"text":"Every piece of a subdivided magnet will always have _______.","options":["only an n-pole","only an s-pole","both n and s poles"],"correct":2}'::jsonb,54,true),
(10,'objectives','multipleChoice · 10','10','{"section":"multipleChoice","number":10,"text":"A suspended bar magnet that is free to turn will align itself _______.","options":["east and west","north and south","vertically"],"correct":1}'::jsonb,55,true),
