(10,'objectives','trueFalse · 1','11','{"section":"trueFalse","number":1,"text":"Classical physics was established before the arrival of the theories of relativity and quantum mechanics.","answer":true}'::jsonb,1,true),
(10,'objectives','trueFalse · 2','11','{"section":"trueFalse","number":2,"text":"The main foundations of modern physics were laid in the first three decades of the nineteenth century.","answer":false}'::jsonb,2,true),
(10,'objectives','trueFalse · 3','11','{"section":"trueFalse","number":3,"text":"Thermionic emission is the process of emitting free electrons from a metal surface using heat energy.","answer":true}'::jsonb,3,true),
(10,'objectives','trueFalse · 4','11','{"section":"trueFalse","number":4,"text":"A vacuum diode is a vacuum tube consisting of exactly two electrodes.","answer":true}'::jsonb,4,true),
(10,'objectives','trueFalse · 5','11','{"section":"trueFalse","number":5,"text":"In a vacuum diode, the anode is the specific electrode responsible for emitting free electrons.","answer":false}'::jsonb,5,true),
(10,'objectives','trueFalse · 6','11','{"section":"trueFalse","number":6,"text":"The anode in a vacuum diode is also commonly referred to as the plate.","answer":true}'::jsonb,6,true),
(10,'objectives','trueFalse · 7','11','{"section":"trueFalse","number":7,"text":"A vacuum diode containing only two electrodes can be used as an amplifier.","answer":false}'::jsonb,7,true),
(10,'objectives','trueFalse · 8','11','{"section":"trueFalse","number":8,"text":"Electrons in a vacuum diode move from the plate to the filament during operation.","answer":false}'::jsonb,8,true),
(10,'objectives','trueFalse · 9','11','{"section":"trueFalse","number":9,"text":"By the end of the 19th century, scientists believed particles and radiation were the only physical entities in nature.","answer":true}'::jsonb,9,true),
(10,'objectives','trueFalse · 10','11','{"section":"trueFalse","number":10,"text":"The results of the photoelectric effect experiment were successfully explained by the laws of classical physics.","answer":false}'::jsonb,10,true),
(10,'objectives','trueFalse · 11','11','{"section":"trueFalse","number":11,"text":"The sun and stars are celestial objects that emit radiation in a manner similar to a blackbody.","answer":true}'::jsonb,11,true),
(10,'objectives','trueFalse · 12','11','{"section":"trueFalse","number":12,"text":"Wien''s law states that the wavelength of maximum intensity is inversely proportional to the absolute temperature.","answer":true}'::jsonb,12,true),
(10,'objectives','trueFalse · 13','11','{"section":"trueFalse","number":13,"text":"According to blackbody principles, higher temperatures shift the maximum intensity to longer wavelengths.","answer":false}'::jsonb,13,true),
(10,'objectives','trueFalse · 14','11','{"section":"trueFalse","number":14,"text":"Most alpha particles in Rutherford’s experiment were deflected backward through very large angles.","answer":false}'::jsonb,14,true),
(10,'objectives','trueFalse · 15','11','{"section":"trueFalse","number":15,"text":"Bohr’s model states that only certain orbits are allowed for an electron moving around a nucleus.","answer":true}'::jsonb,15,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'objectives','trueFalse · 16','11','{"section":"trueFalse","number":16,"text":"The mass number A of an element represents the total number of protons only.","answer":false}'::jsonb,16,true),
