(10,'objectives','trueFalse · 18','11','{"section":"trueFalse","number":18,"text":"Celestial objects are defined as any natural bodies located outside of the Earth’s atmosphere.","answer":true}'::jsonb,18,true),
(10,'objectives','trueFalse · 19','11','{"section":"trueFalse","number":19,"text":"An Astronomical Unit (AU) is the distance light travels in a vacuum in one year.","answer":false}'::jsonb,19,true),
(10,'objectives','trueFalse · 20','11','{"section":"trueFalse","number":20,"text":"A light year is the distance light travels in a vacuum during the period of one year.","answer":true}'::jsonb,20,true),
