(10,'objectives','fillBlank · 4','11','{"section":"fillBlank","number":4,"text":"A vacuum diode consists of exactly _______ electrodes.","answer":["two"]}'::jsonb,24,true),
(10,'objectives','fillBlank · 5','11','{"section":"fillBlank","number":5,"text":"In a vacuum diode, the specific electrode that emits free electrons is the _______.","answer":["cathode"]}'::jsonb,25,true),
