(10,'objectives','fillBlank · 7','11','{"section":"fillBlank","number":7,"text":"In modern electronics, most vacuum tubes have been replaced by _______.","answer":["transistors"]}'::jsonb,27,true),
(10,'objectives','fillBlank · 8','11','{"section":"fillBlank","number":8,"text":"A perfect radiator that absorbs and emits all radiation incident on it is a ____.","answer":["blackbody"]}'::jsonb,28,true),
(10,'objectives','fillBlank · 9','11','{"section":"fillBlank","number":9,"text":"The energy emitted from a unit area of a blackbody surface in one second is _______.","answer":["intensity"]}'::jsonb,29,true),
(10,'objectives','fillBlank · 10','11','{"section":"fillBlank","number":10,"text":"Max Planck proposed that radiation resulted from a large number of identical _______.","answer":["oscillators"]}'::jsonb,30,true),
