(10,'objectives','fillBlank · 12','11','{"section":"fillBlank","number":12,"text":"Photons with a long wavelength are characterized by having _______ energy.","answer":["low"]}'::jsonb,32,true),
(10,'objectives','fillBlank · 13','11','{"section":"fillBlank","number":13,"text":"The _______ model of the atom is famously referred to as the plum pudding model.","answer":["Thomson"]}'::jsonb,33,true),
