(10,'definitions','Measurement တိုင်းတာမှု','1','{"title":"Measurement တိုင်းတာမှု","paragraphs":[[{"text":" Measurement essentially is a comparison process."}],[{"text":" တိုင်းတာမှုဆိုသည်မှာ အခြေခံအားဖြင့် နှိုင်းယှဉ်ခြင်းပင်ဖြစ်သည်။ (ဝတ္ထုတစ်ခုရဲ့အလျားကို ပေတံထက် ဘယ်နဆရှည်လဲဆိုတာ သိရအောင် ပေတံနှင့် နှိုင်းယှဉ်လိုက်ရတာ)"}]]}'::jsonb,0,true),
(10,'definitions','Standard စံ','1','{"title":"Standard စံ","paragraphs":[[{"text":" Standard is something or a reference used as a measure for length, mass and time."}],[{"text":" အလျား၊ ဒြပ်ထုနှင့် ကြာချိန်တို့ကိုတိုင်းတာရာတွင် ကိုးကားရန်အသုံးပြုသောပစ္စည်းကို စံ ဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Unit ယူနစ်','1','{"title":"Unit ယူနစ်","paragraphs":[[{"text":" Unit is a quantity or an amount used as a standard of measurement."}],[{"text":" ယူနစ်ဆိုသည်မှာ တိုင်းတာရာတွင် စံ အဖြစ်အသုံးပြုသော ပမာဏတစ်ခုဖြစ်သည်။ (ပေတံနှင့် တိုင်းရင် “ပေ” ဟာ ယူနစ်ပေါ့)"}]]}'::jsonb,2,true),
(10,'definitions','Physical quantity ရူပဗေဒဆိုင်ရာ အတိုင်းအတာ','1','{"title":"Physical quantity ရူပဗေဒဆိုင်ရာ အတိုင်းအတာ","paragraphs":[[{"text":" A physical quantity is the quantity that can be measured, and consists of a numerical magnitude and a unit."}],[{"text":" Q = N u,  Q = physical quantity, N = a dimensionless number, u = unit."}],[{"text":" တိုင်းတာနိုင်သော ပမာဏကို ရူပဗေဒဆိုင်ရာအတိုင်းအတာဟုခေါ်သည်။ ကိန်းဂဏာန်းဆိုင်ရာပမာဏတစ်ခုနှင့် ယူနစ်တစ်ခုပါဝင်သည်။ (အလျား = ၅၀ ပေ)"}]]}'::jsonb,3,true),
(10,'definitions','Basic unit အခြေခံယူနစ်','1','{"title":"Basic unit အခြေခံယူနစ်","paragraphs":[[{"text":" A basic unit is a unit of basic type physical quantities such as length, mass, time, temperature, electric current, amount of substance, luminous intensity."}],[{"text":" အခြေခံယူနစ်ဆိုသည်မှာ အလျား၊ ဒြပ်ထု၊ ကြာချိန်၊ အပူချိန်၊ လျှပ်စစ်စီးကြောင်း၊ ပစ္စည်းပမာဏ၊ အလင်းပြင်း အားစသည့် ရူပဗေဒဆိုင်ရာအခြေခံတိုင်းတာမှုမျာ၏ ယူနစ်ဖြစ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Derived unit ဆင့်ပွားယူနစ်','1','{"title":"Derived unit ဆင့်ပွားယူနစ်","paragraphs":[[{"text":" A derived unit is a unit of measurement formed by combining the basic (or base) units of a system."}],[{"text":" စနစ်တစ်ခု၏ အခြေခံယူနစ်များကို ပေါင်းစပ်ခြင်းဖြင့် ဖြစ်ပေါ်လာသောအတိုင်းအတာယူနစ်ကို ဆင့်ပွားယူနစ် ဟု ခေါ်သည်။ (အခြေခံယူနစ်များကို မြှောက်ခြင်းဖြင့်ဖြစ်စေ/ စားခြင်းဖြင့်ဖြစ်စေ ဆင့်ပွားယူနစ်ရသည်)"}],[{"text":"There are three system of units"}],[{"text":"The British system ဗြိတိသျှသုံး အတိုင်းအတာစနစ်"}],[{"text":"The metric system ဆယ်လီစနစ်ကို အခြေခံသော မက်ထရစ်စနစ်"}],[{"text":"The SI system နိုင်ငံတကာသုံးယူနစ်"}]]}'::jsonb,5,true),
(10,'definitions','The British system','1','{"title":"The British system","paragraphs":[[{"text":" The British system is based on foot (ft), pound (lb) and second (s), and is therefore also called the FPS system."}],[{"text":" အလျားကို ပေ၊ အလေးချိန်ကို ပေါင်၊ ကြာချိန်ကို စက္ကန့်နှင့်တိုင်းတာသည့်စနစ်ကို ဗြိတိသျှစနစ်ဟုခေါ်သည်။"}],[{"text":"The Metric system consists of (i) the CGS system and (ii) the MKS system."}]]}'::jsonb,6,true),
(10,'definitions','The CGS system','1','{"title":"The CGS system","paragraphs":[[{"text":" The CGS system is based on centimetre (cm), gram (g) and second (s)."}],[{"text":" CGS စနစ်တွင် အလျားကို စင်တီမီတာ၊ ဒြပ်ထုကို ဂရမ်၊ ကြာချိန်ကို စက္ကန့်နှင့်တိုင်းတာသည်။"}]]}'::jsonb,7,true),
(10,'definitions','The MKS system','1','{"title":"The MKS system","paragraphs":[[{"text":" The MKS system is based on metre (m), kilogram (kg) and second (s)."}],[{"text":" MKS စနစ်တွင် အလျားကို မီတာ၊ ဒြပ်ထုကို ကီလိုဂရမ်၊ ကြာချိန်ကို စက္ကန့်နှင့်တိုင်းတာသည်။"}]]}'::jsonb,8,true),
(10,'definitions','The SI unit','1','{"title":"The SI unit","paragraphs":[[{"text":" The SI unit is just the modified form of the MKS system of units."}],[{"text":" SI unit သည် MKS စနစ်ကိုပြင်ဆင်မွမ်းမံထားသည့် ယူနစ်ဖြစ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Mass ဒြပ်ထု','1','{"title":"Mass ဒြပ်ထု","paragraphs":[[{"text":" The mass of an object is a measure of the amount of matter in it."}],[{"text":" ပစ္စည်းတစ်ခုတွင်ပါဝင်သောဒြပ်သားပမာဏကို ထိုပစ္စည်း၏ ဒြပ်ထုဟုခေါ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,10,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','Scalar quantities','2','{"title":"Scalar quantities","paragraphs":[[{"text":" The quantities, that have only magnitude, are called scalar quantities."}],[{"text":" ပမာဏတစ်မျိုးတည်းသာဖော်ပြနိုင်သောတိုင်းတာမှုများကို စကေလာအတိုင်းအတာများဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Vector quantities','2','{"title":"Vector quantities","paragraphs":[[{"text":" The quantities, that have both magnitude and direction, are called vector quantities."}],[{"text":" ပမာဏသာမက ဦးတည်ချက်ပါဖော်ပြနိုင်သောတိုင်းတာမှုများကို ဗက်တာအတိုင်းအတာများဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Resultant vector','2','{"title":"Resultant vector","paragraphs":[[{"text":" The vector sum of two or more vectors is called resultant vector."}],[{"text":" ဗက်တာများပေါင်းခြင်းဖြင့်ရလာသည့် ဗက်တာအသစ်ကို resultant ဗက်တာဟုခေါ်သည်။"}]]}'::jsonb,2,true),
(10,'definitions','Resolution of a vector ဗက်တာအစိတ်အပိုင်းခွဲခြင်း','2','{"title":"Resolution of a vector ဗက်တာအစိတ်အပိုင်းခွဲခြင်း","paragraphs":[[{"text":" The process of sub-dividing a vector into two or more vectors is called resolution of a vector."}],[{"text":" ဗက်တာတစ်ခုကို ၂ ခု (သို့) ပိုများသောဗက်တာများအဖြစ်ခွဲထုတ်ခြင်းကို ဗက်တာခွဲခြင်းဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Vector components   ဗက်တာအခွဲများ (ဗက်တာအစိတ်အပိုင်းများ)','2','{"title":"Vector components   ဗက်တာအခွဲများ (ဗက်တာအစိတ်အပိုင်းများ)","paragraphs":[[{"text":"y - axisx - axis"},{"math":true,"tex":"\\vec{A}_{y}","plain":"A⃗y"},{"text":" "},{"math":true,"tex":"\\vec{A}_{x}","plain":"A⃗x"},{"text":" "},{"math":true,"tex":"\\vec{A}","plain":"A⃗"},{"text":" "},{"math":true,"tex":"\\theta ","plain":"θ"},{"text":" The new vectors obtained from the resolution of a vector are called vector components of the original vector."}],[{"text":"  "},{"math":true,"tex":"\\vec{A}","plain":"A⃗"},{"text":" = original vector"}],[{"text":"  "},{"math":true,"tex":"\\vec{A}_{x}","plain":"A⃗x"},{"text":" = component of A along x-axis,"}],[{"text":"   x component (or) horizontal component"}],[{"text":"   "},{"math":true,"tex":"\\vec{A}_{y}","plain":"A⃗y"},{"text":" = component of A along y-axis,"}],[{"text":"   y component (or) vertical component"}],[{"text":" ဗက်တာခွဲခြင်းဖြင့်ရလာသည့် ဗက်တာအသစ်များကို ဗက်တာအခွဲများဟုခေါ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Distance (or) distance travelled အကွာအဝေး','2','{"title":"Distance (or) distance travelled အကွာအဝေး","paragraphs":[[{"text":" The distance or distance travelled by the body is the length of the path along which the body moves."}],[{"text":" ဝတ္ထုတစ်ခုရွေ့လျားခဲ့သည့်လမ်းကြောင်းတစ်လျောက် အလျားကို အကွာအဝေးဟုခေါ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Displacement အရွေ့(ဝတ္ထုနေရာရွေ့ခြင်း)','2','{"title":"Displacement အရွေ့(ဝတ္ထုနေရာရွေ့ခြင်း)","paragraphs":[[{"text":" The displacement is the distance travelled along a particular direction. It is always directed from the starting point to the end point."}],[{"text":" စမှတ်မှ ဆုံးမှတ်သို့ ဦးတည်ချက်တစ်ခုတည်းယူကာ တိုင်းတာသည့်အကွာအဝေးကို ဝတ္ထု၏အရွေ့ဟုခေါ်သည်။"}]]}'::jsonb,6,true),
(10,'definitions','Average speed   ပျမ်းမျှအမြန်နှုန်း','2','{"title":"Average speed   ပျမ်းမျှအမြန်နှုန်း","paragraphs":[[{"text":" The average speed is the ratio of the total distance to the time taken."}],[{"text":" vav =  "},{"math":true,"tex":"\\frac{s}{t}","plain":"(s)/(t)"},{"text":"  (or) "},{"math":true,"tex":"\\bar{v}","plain":"v̅"},{"text":" =  "},{"math":true,"tex":"\\frac{s}{t}","plain":"(s)/(t)"}],[{"text":" average speed ဆိုတာ သွားခဲ့သောခရီးအကွာအဝေးစုစုပေါင်းနှင့် သွားရန်ကြာသောအချိန်တို့၏အချိုးဖြစ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','Average velocity   ပျမ်းမျှအလျင်','2','{"title":"Average velocity   ပျမ်းမျှအလျင်","paragraphs":[[{"text":" The average velocity is the ratio of the total displacement to the time taken."}],[{"text":" "},{"math":true,"tex":"\\vec{v}_{av}","plain":"v⃗av"},{"text":" =  "},{"math":true,"tex":"\\frac{\\vec{s}}{t}","plain":"(s⃗)/(t)"},{"text":"  (or) "},{"math":true,"tex":"\\bar{\\vec{v}}","plain":"v⃗̅"},{"text":" =  "},{"math":true,"tex":"\\frac{\\vec{s}}{t}","plain":"(s⃗)/(t)"}],[{"text":" average velocity ဆိုတာ သွားခဲ့သောအရွေ့စုစုပေါင်းနှင့် သွားရန်ကြာသောအချိန်တို့၏အချိုးဖြစ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Instantaneous speed ရုတ်ချည်းအမြန်နှုန်း','2','{"title":"Instantaneous speed ရုတ်ချည်းအမြန်နှုန်း","paragraphs":[[{"text":" The instantaneous speed is defined as the time rate of change of distance."}],[{"text":" Instantaneous speed, v = "},{"math":true,"tex":"\\lim∆t →0 \\frac{\\Delta  s }{\\Delta  t }","plain":"lim∆t →0  (Δ s )/(Δ t )"},{"text":" = "},{"math":true,"tex":"\\frac{ds}{dt}","plain":"(ds)/(dt)"}],[{"text":" Instantaneous speed ဆိုသည်မှာ အချိန်နှင့်အလိုက် အကွာအဝေးပြောင်းလဲသောနှုန်းဖြစ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Instantaneous velocity ရုတ်ချည်းအလျင်','2','{"title":"Instantaneous velocity ရုတ်ချည်းအလျင်","paragraphs":[[{"text":" The instantaneous velocity is defined as the time rate of change of displacement."}],[{"text":" Instantaneous velocity, "},{"math":true,"tex":"\\vec{v}","plain":"v⃗"},{"text":" = "},{"math":true,"tex":"\\lim∆t →0 \\frac{\\Delta  \\vec{s} }{\\Delta  t }","plain":"lim∆t →0  (Δ s⃗ )/(Δ t )"},{"text":" = "},{"math":true,"tex":"\\frac{d\\vec{s}}{dt}","plain":"(ds⃗)/(dt)"}],[{"text":" Instantaneous velocity ဆိုသည်မှာ အချိန်နှင့်အလိုက် အရွေ့ပြောင်းလဲသောနှုန်းဖြစ်သည်။"}]]}'::jsonb,10,true),
(10,'definitions','Average acceleration ပျမ်းမျှအရှိန်','2','{"title":"Average acceleration ပျမ်းမျှအရှိန်","paragraphs":[[{"text":" The average acceleration is the ratio of the change in velocity to the time taken. "}],[{"text":" "},{"math":true,"tex":"\\vec{a}_{av}","plain":"a⃗av"},{"text":" = "},{"math":true,"tex":"\\frac{\\vec{v} -\\vec{ v}_{0} }{t}","plain":"(v⃗ - v⃗₀ )/(t)"}],[{"text":" average acceleration ဆိုတာ velocity ပြောင်းလဲခြင်းနှင့် ပြောင်းလဲရန်ကြာချိန်တို့၏အချိုးဖြစ်သည်။"}]]}'::jsonb,11,true),
(10,'definitions','Instantaneous acceleration ရုတ်ချည်း အရှိန်','2','{"title":"Instantaneous acceleration ရုတ်ချည်း အရှိန်","paragraphs":[[{"text":" The instantaneous acceleration is the time rate of change of velocity."}],[{"text":" Instantaneous acceleration, "},{"math":true,"tex":"\\vec{a}","plain":"a⃗"},{"text":" = "},{"math":true,"tex":"\\lim∆t →0 \\frac{\\Delta  \\vec{v} }{\\Delta  t }","plain":"lim∆t →0  (Δ v⃗ )/(Δ t )"},{"text":" = "},{"math":true,"tex":"\\frac{d\\vec{v}}{dt}","plain":"(dv⃗)/(dt)"}],[{"text":" Instantaneous acceleration ဆိုသည်မှာ အချိန်နှင့်အလိုက် velocity ပြောင်းလဲသောနှုန်းဖြစ်သည်။"}]]}'::jsonb,12,true),
(10,'definitions','Uniform motion','2','{"title":"Uniform motion","paragraphs":[[{"text":" Motion with constant velocity is known as uniform motion."}],[{"text":" ကိန်းသေအလျင်နှင့် ရွေ့လျားမှုကို တသမတ်ရွေ့လျားမှု(uniform motion) ဟုခေါ်သည်။"}]]}'::jsonb,13,true),
(10,'definitions','Non-uniform motion','2','{"title":"Non-uniform motion","paragraphs":[[{"text":" Motion with changing velocity is called non-uniform motion or accelerated motion."}],[{"text":" ပြောင်းလဲနေသောအလျင်နှင့် ရွေ့လျားမှုကို အရှိန်နှင့်ရွေ့လျားမှုဟုခေါ်သည်။"}]]}'::jsonb,14,true),
(10,'definitions','Linear motion','2','{"title":"Linear motion","paragraphs":[[{"text":" Motion along a straight line is called linear motion."}],[{"text":" မျဉ်းဖြောင့်အတိုင်း ရွေ့လျားခြင်းကို linear motion ဟုခေါ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,15,true),
(10,'definitions','Newton’s First Law of Motion (Law of Inertia)','3','{"title":"Newton’s First Law of Motion (Law of Inertia)","paragraphs":[[{"text":" When no net external force acts upon it, a particle at rest will remain at rest and a particle in motion at a constant velocity will continue to move with the same constant velocity."}],[{"text":" In mathematical form, if  "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"net  0 then "},{"math":true,"tex":"\\vec{a}","plain":"a⃗"},{"text":" = 0, "},{"math":true,"tex":"\\vec{v}","plain":"v⃗"},{"text":" = constant (or) zero."}],[{"text":" "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"net  net external force, "},{"math":true,"tex":"\\vec{a}","plain":"a⃗"},{"text":" = acceleration, "},{"math":true,"tex":"\\vec{v}","plain":"v⃗"},{"text":" = velocity"}],[{"text":" ဝတ္ထုတစ်ခုပေါ် သက်ရောက်အသားတင်အားမရှိပါက ရပ်နေသောဝတ္ထုက ရပ်မြဲရပ်နေမယ်။ ကိန်းသေအလျင်နှင့် ရွေ့နေသောဝတ္ထုက ဦးတည်ချက်မပြောင်းလဲဘဲ ကိန်းသေအလျင်နှင့်ပင်ဆက်ရွေ့နေမယ်။"}]]}'::jsonb,0,true),
(10,'definitions','Inertia','3','{"title":"Inertia","paragraphs":[[{"text":" The inertia of a body is its reluctance to start moving, and its reluctance to stop once it has begun moving."}],[{"text":" ဝတ္တုတစ်ခုစတင်ရွေ့လျားရန် တုန့်ဆိုင်းမှုနှင့် ရွေ့နေဆဲဝတ္ထု ရပ်တန့်ရန်တုန့်ဆိုင်းမှုကို ၎င်းဝတ္ထု၏ နေမြဲနေလို သောဆန္ဒ(အင်နားရှား) လို့ခေါ်တယ်။"}]]}'::jsonb,1,true),
(10,'definitions','Newton’s Second Law of Motion (Law of Force and Acceleration)','3','{"title":"Newton’s Second Law of Motion (Law of Force and Acceleration)","paragraphs":[[{"text":" The net external force acting upon a particle is equal to the product of the mass and the acceleration of the particle. "}],[{"text":" In mathematical form, "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"net  m "},{"math":true,"tex":"\\vec{a}","plain":"a⃗"}],[{"text":" "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"net  net external force, "},{"math":true,"tex":"\\vec{a}","plain":"a⃗"},{"text":" = acceleration, m = mass"}],[{"text":" ဝတ္ထုရဲ့ဒြပ်ထုနှင့် အရှိန်တို့မြှောက်လဒ်က ဝတ္တုတစ်ခုပေါ်သက်‌ရောက်လိုက်သောအသားတင်အားနှင့်ညီတယ်။"}]]}'::jsonb,2,true),
(10,'definitions','Newton’s Third Law of Motion (Law of Action and Reaction)','3','{"title":"Newton’s Third Law of Motion (Law of Action and Reaction)","paragraphs":[[{"text":" Whenever two particles interact, the force exerted by the second on the first is equal in magnitude and opposite in direction to the force exerted by the first on the second."}],[{"text":" In mathematical form, "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"second on first = - "},{"math":true,"tex":"\\vec{F}","plain":"F⃗"},{"text":"first on second"}],[{"text":" အမှုန် ၂ ခု အပြန်အလှန်သက်‌ရောက်သောအခါ ဒုတိယဝတ္ထုက ပထမဝတ္ထုပေါ်သက်‌ရောက်လိုက်သောအားက ပထမဝတ္ထုက ဒုတိယဝတ္ထုပေါ် တန်ပြန်သက်ရောက်သောအားနှင့် ပမာဏညီကာ ဦးတည်ချက်ဆန့်ကျင်တယ်။"}],[{"text":" သက်‌ရောက်အားနှင့် တန်ပြန်သက်ရောက်အား ပမာဏတူကာ ဦိးတည်ချက်ဆန့်ကျင်တယ်။"}]]}'::jsonb,3,true),
(10,'definitions','Force','3','{"title":"Force","paragraphs":[[{"text":" A force is a push or pull that changes the motion of a body."}],[{"text":" အားသည် ဝတ္ထုတစ်ခု၏ရွေ့လျားမှုအခြေနေကိုပြောင်းလဲစေ‌သော တွန်းခြင်း/ဆွဲခြင်းသက်ရောက်မှုဖြစ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','1 newton (1 N) (In SI system)  (1 N = 1 kg m s-2)','3','{"title":"1 newton (1 N) (In SI system)  (1 N = 1 kg m s-2)","paragraphs":[[{"text":" A force that is acting on 1 kg mass to give it an acceleration of 1 m s-2 is called l newton"}],[{"text":" ဒြပ်ထု 1 kg ကို အရှိန် 1 m s-2 နှင့် ရွေ့လျားစေတဲ့ အားကို 1 N (နယူတန်) အားလို့သတ်မှတ်တယ်။"}]]}'::jsonb,5,true),
(10,'definitions','1 dyne (In CGS system)  (1 dyne = 1 g cm s-2)','3','{"title":"1 dyne (In CGS system)  (1 dyne = 1 g cm s-2)","paragraphs":[[{"text":" A force that is acting on 1 g mass to give it an acceleration of 1 cm s-2 is called l dyne."}],[{"text":" ဒြပ်ထု 1 g ကို အရှိန် 1 cm s-2 နှင့် ရွေ့လျားစေသော အားတဲ့ 1 dyne ဟုလို့သတ်မှတ်တယ်။"}]]}'::jsonb,6,true),
(10,'definitions','1 pound (1 lb) (In FPS system) (1 lb = 1 sl ft s-2)','3','{"title":"1 pound (1 lb) (In FPS system) (1 lb = 1 sl ft s-2)","paragraphs":[[{"text":" A force that is acting on 1 slug mass to give it an acceleration of 1 ft s-2 is called l pound"}],[{"text":" ဒြပ်ထု 1 slug ကို အရှိန် 1 ft s-2 နှင့် ရွေ့လျားစေတဲ့ အားကို 1 pound (၁ ပေါင်) အားလို့သတ်မှတ်တယ်။"}]]}'::jsonb,7,true),
(10,'definitions','Newton’s Gravitational Law နယူတန်၏ ဒြပ်ဆွဲအားနိယာမ (1687)','3','{"title":"Newton’s Gravitational Law နယူတန်၏ ဒြပ်ဆွဲအားနိယာမ (1687)","paragraphs":[[{"text":" Everybody attracts every other body in the universe. The gravitational force between the two bodies is directly proportional to the product of the masses and inversely proportional to the square of the distance between them."}],[{"text":"  F "},{"math":true,"tex":"\\propto   \\frac{m_{1} m_{2}}{r^{2}}","plain":"∝  (m₁ m₂)/(r²)"},{"text":"                            F = G "},{"math":true,"tex":"\\frac{m_{1} m_{2}}{r^{2}}","plain":"(m₁ m₂)/(r²)"}],[{"text":" F = the gravitational force,  G = gravitational constant"}],[{"text":" m1, m2 = masses of the two bodies,  r = distance between the two bodies.  "}],[{"text":" စကြဝဠာအတွင်း အရာဝတ္ထုတိုင်းသည် အချင်းချင်းဆွဲငင်ကြသည်။ ဝတ္ထု ၂ ခုကြား ဒြပ်ဆွဲအားသည် ၎င်းဝတ္ထုတို့ ၏ ဒြပ်ထုမြှောက်ခြင်းနှင့် တိုက်ရိုက်အချိုးကျကာ ၎င်းတို့ကြားအကွာအဝေး ၂ ထပ်နှင့် ပြောင်းပြန်အချိုးကျသည်။"}],[{"text":"Fundamental forces (field force/ non-contact force) အခြေခံအားများ/စက်ကွင်းအားများ "}],[{"text":"There are only four fundamental forces in nature, and they are all field forces."}],[{"text":" (1) Nuclear force [short-range force,  strongest force]"}],[{"text":" (2) Electromagnetic force [long-range force,  second strongest force]"}],[{"text":" (3) Weak force [short-range force,  second weakest force]"}],[{"text":" (4) Gravitational force [long-range force,  weakest force]"}]]}'::jsonb,8,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','Elastic force ရုန်းပြန်အား','3','{"title":"Elastic force ရုန်းပြန်အား","paragraphs":[[{"text":" When a spring is stretched or a plastic ruler is bent, the force that causes the spring and the ruler to retain their original forms is called elastic force. "}],[{"text":" စပရင် ကို ဆွဲဆန့်ပြီးပြန်လွှတ်လိုက်သောအခါ (သို့) ပလတ်စတစ်ပေတံ ကို ကွေးပြီးပြန်လွှတ်လိုက်သောအခါ စပရင်၊ ပလတ်စတစ်ပေတံတို့ကို မူလပုံစံပြန်ဖြစ်စေသောအားကို ရုန်းပြန်အားဟုခေါ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Frictional force ပွတ်မှုအား','3','{"title":"Frictional force ပွတ်မှုအား","paragraphs":[[{"text":" The force that acts to resist the motion of the body is frictional force. "}],[{"text":" ဝတ္ထုရွေ့လျားခြင်းကို ခုခံဟန့်တားသောအားကို ပွတ်မှုအားဟုခေါ်သည်။"}]]}'::jsonb,10,true),
(10,'definitions','Acceleration due to gravity ဒြပ်ဆွဲရှိန်','3','{"title":"Acceleration due to gravity ဒြပ်ဆွဲရှိန်","paragraphs":[[{"text":" The acceleration due to the gravitational force is called acceleration due to gravity."}],[{"text":" ဒြပ်ဆွဲအားကြောင့် ပစ္စည်းရွေ့လျားသောအခါ ဖြစ်ပေါ်လာသည့်အရှိန်ကို ဒြပ်ဆွဲရှိန်ဟုခေါ်သည်။"}]]}'::jsonb,11,true),
(10,'definitions','Weight အလေးချိန်','3','{"title":"Weight အလေးချိန်","paragraphs":[[{"text":" The attracting force of the earth acting on a body is defined as the weight of the body."}],[{"text":" ဝတ္ထုတစ်ခုပေါ် ကမ္ဘာမြေမှသက်ရောက်သောဆွဲအားကို ထိုဝတ္ထု၏အလေးချိန်ဟုသတ်မှတ်သည်။"}]]}'::jsonb,12,true),
(10,'definitions','Mass ဒြပ်ထု','3','{"title":"Mass ဒြပ်ထု","paragraphs":[[{"text":" Mass is the quantity of matter in a body. Mass is also a measure of inertia. "}],[{"text":" ဝတ္ထုတစ်ခုတွင်ပါဝင်သော ဒြပ်သားပမာဏကို ဒြပ်ထုဟုခေါ်သည်။"}]]}'::jsonb,13,true),
(10,'definitions','Momentum အဟုန်','3','{"title":"Momentum အဟုန်","paragraphs":[[{"text":" The momentum of a body is defined as the product of the mass of the body and its velocity.                               "}],[{"text":" "},{"math":true,"tex":"\\vec{p}","plain":"p⃗"},{"text":" = m "},{"math":true,"tex":"\\vec{v}","plain":"v⃗"},{"text":"  "},{"math":true,"tex":"\\vec{p}","plain":"p⃗"},{"text":" = momentum, m = mass, "},{"math":true,"tex":"\\vec{v}","plain":"v⃗"},{"text":" = velocity of the body"}],[{"text":" ဝတ္ထုတစ်ခု၏ဒြပ်ထုနှင့် ၎င်း၏ရွေ့လျားအလျင်တို့မြှောက်လဒ်ကို ထိုဝတ္ထု၏အဟုန်ဟုသတ်မှတ်သည်။"}]]}'::jsonb,14,true),
(10,'definitions','Law of conservation of Momentum အဟုန်တည်မြဲခြင်းနိယာမ','3','{"title":"Law of conservation of Momentum အဟုန်တည်မြဲခြင်းနိယာမ","paragraphs":[[{"text":" If there is no net external force acting on an isolated system, the total momentum of the system is constant. "}],[{"text":" သီးခြားအဖွဲ့အစည်းတစ်ခုပေါ် အသားတင်ပြင်ပသက်ရောက်အားမရှိပါက ထိုအဖွဲ့အစည်း၏စုစုပေါင်းအဟုန်မှာ ကိန်းသေဖြစ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,15,true),
(10,'definitions','Pressure ဖိအား','4','{"title":"Pressure ဖိအား","paragraphs":[[{"text":" Pressure is defined as the force exerted normally on unit area."}],[{"text":" p = "},{"math":true,"tex":"\\frac{F}{A}","plain":"(F)/(A)"},{"text":"  where, p = pressure,  F = force, A = area"}],[{"text":" ၁ ယူနစ်ဧရိယာပေါ်သို့ ထောင့်မတ်ကျသက်ရောက်သောအားကို ဖိအားဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Density သိပ်သည်းခြင်း/ သိပ်သည်းမှု','4','{"title":"Density သိပ်သည်းခြင်း/ သိပ်သည်းမှု","paragraphs":[[{"text":" Density is the ratio of mass to volume of a substance."}],[{"text":" "},{"math":true,"tex":"\\rho ","plain":"ρ"},{"text":" = "},{"math":true,"tex":"\\frac{m}{V}","plain":"(m)/(V)"},{"text":"  "},{"math":true,"tex":"\\rho ","plain":"ρ"},{"text":" = density, m = mass,  V = volume"}],[{"text":" ဝတ္ထုတစ်ခု၏ ဒြပ်ထုနှင့် ထုထည်အချိုးကို သိပ်သည်းခြင်းဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Relative density (RD) သိပ်သည်းဆ','4','{"title":"Relative density (RD) သိပ်သည်းဆ","paragraphs":[[{"text":" Relative density is the ratio of density of substance to density of water at 4"},{"math":true,"tex":"℃","plain":"℃"},{"text":"."}],[{"text":" Relative density (RD) = "},{"math":true,"tex":"\\frac{density of substance}{density of water at 4 ℃}","plain":"(density of substance)/(density of water at 4 ℃)"}],[{"text":" ဝတ္ထုတစ်ခု၏ သိပ်သည်းဆဟုသည် ထိုဝတ္ထု၏သိပ်သည်းခြင်းနှင့် အပူချိန် 4"},{"math":true,"tex":"℃","plain":"℃"},{"text":" ရှိရေ သိပ်သည်းခြင်းတို့၏အချိုး ဖြစ်သည်။ တနည်းအားဖြင့် ဝတ္ထုက ရေထက်သိပ်သည်းခြင်း ဘယ်နဆများသည်ဆိုသည့် ဖော်ပြချက်ပင်။"}]]}'::jsonb,2,true),
(10,'definitions','Archimedes’ Principle Part I','4','{"title":"Archimedes’ Principle Part I","paragraphs":[[{"text":" When an object is partially (or) totally immersed in a liquid, the object displaces liquid volume that is equal to the volume of the immersed portion. "}],[{"text":" အရည်တစ်မျိုးမျိုးထဲတွင် ဝတ္ထုတစ်ခုက တစိတ်တပိုင်းဖြစ်စေ/ တစ်ခုလုံးဖြစ်စေနစ်မြုပ်သွားသောအခါ ဝတ္ထု၏ နစ်မြုပ်ထုထည်နှင့်ညီမျှသောရေထုထည်ကို ဖယ်ထုတ်လိုက်သည်။ (နစ်မြုပ်ဝတ္ထုထုထည်အတိုင်းရေထုထည်ကို လျှံကျစေသည် Vimmersed portion = Vliquid displaced)"}]]}'::jsonb,3,true),
(10,'definitions','Archimedes’ Principle Part II','4','{"title":"Archimedes’ Principle Part II","paragraphs":[[{"text":" When bodies are partially (or) totally immersed in a liquid there is loss in weight. The loss in weight of the object is equal to the weight of the liquid displaced."}],[{"text":" The upward thrust acting on a body which is immersed partially or totally in a liquid is equal to the weight of the liquid displaced by the body. "}],[{"text":" upward thrust = upward thrust = weight of liquid displaced "}],[{"text":" အရည်တစ်မျိုးမျိုးထဲတွင် ဝတ္ထုများ တစိတ်တပိုင်းဖြစ်စေ/ တစ်ခုလုံးဖြစ်စေနစ်မြုပ်သွားသောအခါ အလေးချိန် လျော့သွားသည်။ ဝတ္ထု၏လျော့သွားသောအလေးချိန်သည် လျှံကျလာသောရေ၏အလေးချိန်နှင့်ညီသည်။ (သို့)"}],[{"text":" ဝတ္ထုကြောင့်လျှံကျရေအလေးချိန်သည် ရေထဲရှိဝတ္ထုပေါ်သက်ရောက်သောရေပင့်အားနှင့်ညီသည်။"}]]}'::jsonb,4,true),
(10,'definitions','Work အလုပ်','5','{"title":"Work အလုပ်","paragraphs":[[{"text":" Work is defined as the product of force and distance moved in the direction of the force."}],[{"text":" W = F s,  W = work done, F = force acting on the particle, s = distance"}],[{"text":" သက်ရောက်အားနှင့် အားသက်ရောက်ရာလမ်းကြောင်းအတိုင်းရွေ့သည့်အကွာအဝေးတို့၏မြှောက်လဒ်ကို အလုပ် ဟုသတ်မှတ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','1 joule','5','{"title":"1 joule","paragraphs":[[{"text":" 1 joule of work is done when a force of 1 newton moves an object through a distance of 1 metre in the direction of the force. "}],[{"text":" သက်ရောက်အား 1 N ကြောင့် ဝတ္ထုကို 1 m ရွေ့လျားစေလျှင် ပြီးမြောက်သောအလုပ်ကို 1 J ဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','1 erg','5','{"title":"1 erg","paragraphs":[[{"text":" 1 erg of work is done when a force of 1 dyne moves an object through a distance of                   1 centimetre (cm) in the direction of the force. (1 J = 107 erg)"}],[{"text":" သက်ရောက်အား 1 dyne ကြောင့် ဝတ္ထုကို 1 cm ရွေ့လျားစေလျှင်ပြီးမြောက်သောအလုပ်ကို 1 erg ဟုခေါ်သည်"}]]}'::jsonb,2,true),
(10,'definitions','1 ft-lb','5','{"title":"1 ft-lb","paragraphs":[[{"text":" 1 foot-pound of work is done when a force of 1 pound (lb) moves an object through a distance of 1 foot (ft) in the direction of the force. "}],[{"text":" သက်ရောက်အား 1 lb ကြောင့် ဝတ္ထုကို 1 ft ရွေ့လျားစေလျှင် ပြီးမြောက်သောအလုပ်ကို 1 ft-lb ဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Energy','5','{"title":"Energy","paragraphs":[[{"text":" Energy is defined as the capacity to do work. "}],[{"text":" အလုပ် - လုပ်နိုင်သောစွမ်းရည်ကို စွမ်းအင်ဟုခေါ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Kinetic Energy (KE) ရွေ့လျားမှုကြောင့်ဖြစ်သောစွမ်းအင် (အရွေ့စွမ်းအင်)','5','{"title":"Kinetic Energy (KE) ရွေ့လျားမှုကြောင့်ဖြစ်သောစွမ်းအင် (အရွေ့စွမ်းအင်)","paragraphs":[[{"text":" Energy acquired by a body due to its motion is called kinetic energy."}],[{"text":" ဝတ္ထုရွေ့လျားခြင်းကြောင့် ဝတ္ထုကရရှိလာသည့်စွမ်းအင်ကို အရွေ့စွမ်းအင်ဟုခေါ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Potential Energy (PE) တည်ရှိမှု/ တည်နေရာကြောင့်ဖြစ်သောစွမ်းအင် (အတည်စွမ်းအင်)','5','{"title":"Potential Energy (PE) တည်ရှိမှု/ တည်နေရာကြောင့်ဖြစ်သောစွမ်းအင် (အတည်စွမ်းအင်)","paragraphs":[[{"text":" The energy stored in a body due to its position or configuration is called the potential energy."}],[{"text":" တည်နေရာကြောင့်ဖြစ်စေ/ ပုံစံကြောင့်ဖြစ်စေ ဝတ္ထုအတွင်းသိုလှောင်လိုက်သောစွမ်းအင်ကို အတည်စွမ်းအင်ဟု ခေါ်သည်။"}]]}'::jsonb,6,true),
(10,'definitions','Gravitational potential energy (PE)','5','{"title":"Gravitational potential energy (PE)","paragraphs":[[{"text":" Gravitational potential energy is the energy which a body possesses because of its position relative to the ground."}],[{"text":" မြေပြင်မှနှိုင်းယှဉ်ပါက အမြင့်တစ်နေရာတွင်ရှိနေသောဝတ္ထုက ပိုင်ဆိုင်သည့်စွမ်းအင်ကို gravitational potential energy ဟုခေါ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','Elastic potential energy (PE)','5','{"title":"Elastic potential energy (PE)","paragraphs":[[{"text":" The potential energy due to configuration is called elastic potential energy."}],[{"text":" မူလပုံစံမှ ပုံပြောင်းသွားခြင်းကြောင့် ဝတ္ထုကပိုင်ဆိုင်သည့်စွမ်းအင်ကို elastic potential energy ဟုခေါ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Law of conservation of energy','5','{"title":"Law of conservation of energy","paragraphs":[[{"text":" The total energy of an isolated system is constant.  "}],[{"text":" Energy cannot be created (or) destroyed in any process. The total energy of the universe is constant. "}],[{"text":" သီးခြားအဖွဲ့စည်းတစ်ခု၏ စွမ်းအင်စုစုပေါင်းမှာ ကိန်းသေဖြစ်သည်။ စွမ်းအင်ကို မည်သည့်နည်းလမ်းနှင့်မဆို ဖန်တီး၍လည်းမရ ဖျက်စီး၍လည်းမရ။ စကြဝဠာအတွင်းစွမ်းအင်စုစုပေါင်းမှာ ကိန်းသေဖြစ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,9,true),
(10,'definitions','Temperature အပူချိန်','6','{"title":"Temperature အပူချိန်","paragraphs":[[{"text":" Temperature is the quantity that determines how cold (or) how hot the object is. "}],[{"text":" အရာဝတ္ထုတစ်ခုမည်မျှပူသည် အေးသည်ဟူသည့် အဆင့်သတ်မှတ်တိုင်းတာချက်ကို အပူချိန်ဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Heat အပူစွမ်းအင်','6','{"title":"Heat အပူစွမ်းအင်","paragraphs":[[{"text":" The energy exchanged between an object and its surrounding due to different temperatures is defined as heat. "}],[{"text":" အပူချိန်မတူညီခြင်းကြောင့် ဝတ္ထုတစ်ခုနှင့် ၎င်း၏ပတ်ဝန်းကျင်တို့ကြားဖလှယ်လိုက်သောစွမ်းအင်ကို အပူစွမ်းအင် ဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Thermometer အပူချိန်တိုင်းကိရိယာ','6','{"title":"Thermometer အပူချိန်တိုင်းကိရိယာ","paragraphs":[[{"text":" Thermometer is an instrument used to measure the temperature accurately."}],[{"text":" အပူချိန်တိတိကျသိနိုင်ရန် တိုင်းတာရာတွင်သုံးသောပစ္စည်းကို သာမိုမီတာဟုခေါ်သည်။"}]]}'::jsonb,2,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','Internal energy','6','{"title":"Internal energy","paragraphs":[[{"text":" The sum of the potential energy and the kinetic energy, of molecules in matter is the internal energy of that matter."}],[{"text":" ဒြပ်ထုတစ်ခုအတွင်းမော်လီကျူးများ၏ စုစုပေါင်းအတည်စွမ်းအင်နှင့် အရွေ့စွမ်းအင်တို့ကို ဒြပ်ထုအတွင်းပိုင်း စွမ်း အင်ဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Thermal expansion အပူကြောင့်ဝတ္ထုများပွခြင်း','6','{"title":"Thermal expansion အပူကြောင့်ဝတ္ထုများပွခြင်း","paragraphs":[[{"text":" In general, if the temperature of a substance increases, so does its volume. This phenomenon is known as thermal expansion. "}],[{"text":" ယေဘုယျအားဖြင့် အရာဝတ္ထုတစ်ခု၏အပူချိန်မြင့်တက်လာပါက ထုထည်လည်းများ(ပွ)လာသည်။"}],[{"text":"6.  Coefficient of Linear Expansion ("},{"math":true,"tex":"\\alpha ","plain":"α"},{"text":" - အလျားဆန့်ကိန်း)"}],[{"text":" The coefficient of linear expansion is the change in length per unit length for one degree change in temperature. "}],[{"text":" "},{"math":true,"tex":"\\alpha = \\frac{\\Delta l}{l} \\times  \\frac{1}{\\Delta T}","plain":"α= (Δl)/(l) × (1)/(ΔT)"}],[{"text":" အပူချိန် ၁ ဒီဂရီပြောင်းလဲပါက မူလအလျား ၁ ယူနစ်မှ ပြောင်းလဲသွားသည့်အလျားပမာဏကို အလျားဆန့်ကိန်း ဟုခေါ်သည်။"}],[{"text":"7.  Coefficient of area Expansion ("},{"math":true,"tex":"β","plain":"β"},{"text":" – ဧရိယာပြန့်ကိန်း)"}],[{"text":" The coefficient of area expansion of a substance is the change in area per unit area for one degree change in temperature. "}],[{"text":" "},{"math":true,"tex":"β= \\frac{\\Delta A}{A} \\times  \\frac{1}{\\Delta T}","plain":"β= (ΔA)/(A) × (1)/(ΔT)"}],[{"text":" အပူချိန် ၁ ဒီဂရီပြောင်းလဲပါက မူလဧရိယာ ၁ ယူနစ်မှ ပြောင်းလဲသွားသည့်ဧရိယာပမာဏကို ဧရိယာပြန့်ကိန်း ဟုခေါ်သည်။"}],[{"text":"8.  Coefficient of volume Expansion ("},{"math":true,"tex":"γ","plain":"γ"},{"text":" – ထုထည်ပွကိန်း)"}],[{"text":" The coefficient of volume expansion of a substance is the change in volume per unit volume for one degree change in temperature."}],[{"text":" "},{"math":true,"tex":"γ= \\frac{\\Delta V}{V} \\times  \\frac{1}{\\Delta T}","plain":"γ= (ΔV)/(V) × (1)/(ΔT)"},{"text":" "}],[{"text":" အပူချိန် ၁ ဒီဂရီပြောင်းလဲပါက မူလထုထည် ၁ ယူနစ်မှ ပြောင်းလဲသွားသည့်ထုထည်ပမာဏကို ထုထည်ပွကိန်း ဟုခေါ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,4,true),
(10,'definitions','Wave motion လှိုင်း‌ရွေ့လျားမှု','7','{"title":"Wave motion လှိုင်း‌ရွေ့လျားမှု","paragraphs":[[{"text":" Wave motion is a method of transferring energy by successive disturbances through the medium. This movement of energy takes place without transferring matter."}],[{"text":" လှိုင်းရွေ့လျားမှုသည် ကြားခံနယ်အတွင်း ဒြပ်သားများဆက်တိုင်နှောင်ယှက်မှုဖြင့် စွမ်းအင်ကိုလွှဲပြောင်းသည့် နည်းလမ်းဖြစ်သည်။ စွမ်းအင်ကိုသာလွှဲပြောင်းသည် ဒြပ်သားများနေရာမရွေ့ပေ။"}]]}'::jsonb,0,true),
(10,'definitions','Transverse Wave ကန့်လန့်လွှဲလှိုင်း','7','{"title":"Transverse Wave ကန့်လန့်လွှဲလှိုင်း","paragraphs":[[{"text":" If the displacements of particles of the medium are perpendicular to the direction of the wave, such a wave is called a transverse wave. "}],[{"text":" ကြားခံနယ်အမှုန်များ၏ (တုန်ခါမှု)ရွေ့လျားမှုသည် လှိုင်းရွေ့လျားရာဦးတည်ဘက်နှင့် ထောင့်မတ်ကျနေလျှင် ထို လှိုင်းကို ကန့်လန့်လွှဲလှိုင်းဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Longitudinal Wave အလျားလိုက်လှိုင်း','7','{"title":"Longitudinal Wave အလျားလိုက်လှိုင်း","paragraphs":[[{"text":" If the displacements of particles of the medium are parallel to the direction of the wave, such a wave is called a longitudinal wave. "}],[{"text":" ကြားခံနယ်အမှုန်များ၏(တုန်ခါမှု)ရွေ့လျားမှုသည်လှိုင်းရွေ့လျားရာဦးတည်ဘက်နှင့်အပြိုင်(ရှေ့တိုး၊နောက်ဆုတ်) ဖြစ်နေလျှင် ထိုလှိုင်းကို အလျားလိုက်လှိုင်းဟုခေါ်သည်။"}]]}'::jsonb,2,true),
(10,'definitions','Wave crest လှိုင်းထိပ်','7','{"title":"Wave crest လှိုင်းထိပ်","paragraphs":[[{"text":" The highest point which shows the upward maximum displacement of vibrating particle from its rest position (or) equilibrium line is called wave crest. "}],[{"text":" လှိုင်းတစ်လှိုင်းတွင်ရေပြင်ညီမျဉ်းမှ အမြင့်ဆုံးရွေ့လျားမှုရှိသည့် တုန်ခါအမှုန်၏အမှတ်ကို လှိုင်းထိပ်ဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Wave trough လှိုင်းခွက်','7','{"title":"Wave trough လှိုင်းခွက်","paragraphs":[[{"text":"  The lowest point which shows the downward maximum displacement of vibrating particle from its rest position (or) equilibrium line is called wave trough. "}],[{"text":" လှိုင်းတစ်လှိုင်းတွင်ရေပြင်ညီမျဉ်းမှ အနိမ့်ဆုံးရွေ့လျားမှုရှိသည့်တုန်ခါအမှုန်၏အမှတ်ကို လှိုင်းခွက်ဟုခေါ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Wavelength () လှိုင်းအလျား','7','{"title":"Wavelength () လှိုင်းအလျား","paragraphs":[[{"text":"  The distance between any two consecutive wave crests (or) any two consecutive wave troughs is called the wavelength. "}],[{"text":" ကပ်လျက်ရှိသော လှိုင်းထိပ်(သို့မဟုတ်) လှိုင်းခွက် ၂ ခု ကြားအကွာအဝေးကို လှိုင်းအလျားဟုခေါ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Frequency (f ) ကြိမ်နှုန်း','7','{"title":"Frequency (f ) ကြိမ်နှုန်း","paragraphs":[[{"text":" The number of complete waves passing a point per second is called the frequency of the waves."}],[{"text":" တစ်စက္ကန့်အတွင်း အမှတ်တစ်ခု၌ဖြတ်သွားသော လှိုင်းအလျား(သို့မဟုတ်) လှိုင်းလုံးအရေအတွက်ကို ကြိမ်နှုန်းဟု ခေါ်သည်။ [OR]"}],[{"text":" The number of oscillations of a vibrating source in one second is also called the frequency of the waves. "}],[{"text":" တစ်စက္ကန့်အတွင်း တုန်ခါသည့်အကြိမ်အရေအတွက်ကို ကြိမ်နှုန်းဟုခေါ်သည်။"}]]}'::jsonb,6,true),
(10,'definitions','Period (T) လွှဲချိန်','7','{"title":"Period (T) လွှဲချိန်","paragraphs":[[{"text":"  The time taken by the wave to travel the distance between any two consecutive wave crests."}],[{"text":" ကပ်လျက်လှိုင်းထိပ် ၂ ခု ကြားအကွာအဝေး (လှိုင်းအလျားတစ်ကြိမ်စာ) ဖြတ်သွားရန်ကြာသောအချိန်ကို လွှဲချိန် ဟုခေါ်သည်။ [OR]"}],[{"text":" The time required for one complete vibration is called the period of a wave. "}],[{"text":" (ထက်၊အောက်/ ဘယ်၊ညာ) တုန်ခါမှုအပြည့်တစ်ကြိမ်ဖြစ်ပေါ်ရန် လိုသောကြာချိန်ကိုလွှဲချိန်ဟု ခေါ်သည်။ "}]]}'::jsonb,7,true),
(10,'definitions','Amplitude (A) လွှဲကျယ်','7','{"title":"Amplitude (A) လွှဲကျယ်","paragraphs":[[{"text":" The amplitude of a wave is the maximum value of displacement of vibrating particle. "}],[{"text":" လှိုင်းတစ်လှိုင်းတွင် ရေပြင်ညီမျဉ်းမှ အဝေးဆုံးအရွေ့ (လှိုင်းထိပ်၏အမြင့် (သို့) လှိုင်းခွက်၏အနက်)ကို လှိုင်း၏ လွှဲကျယ်ဟုခေါ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Velocity of Wave (v) လှိုင်း၏အလျင်','7','{"title":"Velocity of Wave (v) လှိုင်း၏အလျင်","paragraphs":[[{"text":" The velocity of wave is the speed with which a wave crest travels. "}],[{"text":" လှိုင်းအလျင်ဆိုသည်မှာ အချိန်တစ်စက္ကန့်အတွင်းလှိုင်းထိပ်ရွေ့လျားသော အကွာအဝေးဖြစ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Ripple tank လှိုင်းဂယက်ကန်','7','{"title":"Ripple tank လှိုင်းဂယက်ကန်","paragraphs":[[{"text":" The ripple tank is a convenient piece of apparatus for demonstrating the properties of waves."}],[{"text":" ripple tank သည် လှိုင်း၏ဂုဏ်သတ္တိများကိုသရုပ်ဖော်ပြရန် သင့်တော်ကောင်းမွန်သောပစ္စည်းဖြစ်သည်။"}]]}'::jsonb,10,true),
(10,'definitions','Wavefront လှိုင်းမျက်နှာစာ','7','{"title":"Wavefront လှိုင်းမျက်နှာစာ","paragraphs":[[{"text":" The surface that joins all the points of the same phase is called wavefront. "}],[{"text":" လှိုင်းပေါ်ရှိ အသွင်တူမှတ်များဆက်ထားသည့် မျက်နှာပြင်ကို လှိုင်းမျက်နှာစာ(wavefront)ဟုခေါ်သည်။"}]]}'::jsonb,11,true),
(10,'definitions','Reflection of waves လှိုင်းပြန်ခြင်း','7','{"title":"Reflection of waves လှိုင်းပြန်ခြင်း","paragraphs":[[{"text":"  When a series of waves strike an obstacle, they are turned back. This turning back of waves is called reflection of waves. "}],[{"text":" အတားအဆီးကိုထိရိုက်သောလှိုင်းများ ဦးတည်ချက်နောက်ပြန်လာသည့်ဖြစ်စဉ်ကို လှိုင်းပြန်ခြင်းဟုခေါ်သည်။"}]]}'::jsonb,12,true),
(10,'definitions','Refraction of waves လှိုင်းယိုင်ခြင်း','7','{"title":"Refraction of waves လှိုင်းယိုင်ခြင်း","paragraphs":[[{"text":" When waves are incident to the boundary with an angle, the direction of the waves changes. Such a change in direction is called refraction. "}],[{"text":" သိပ်သည်းမှုမတူသည့် ကြားခံနယ် ၂ ခု၏ နယ်စပ်ကို ထောင့်တစ်ခုစောင်း၍လှိုင်းများထိရိုက်ဖြတ်သန်းသောအခါ လှိုင်းဦးတည်ချက်ပြောင်းသွားရသည့်ဖြစ်စဉ်ကို လှိုင်းယိုင်ခြင်းဟုခေါ်သည်။"}]]}'::jsonb,13,true),
(10,'definitions','Diffraction of waves လှိုင်းပြန့်ခြင်း/ လှိုင်းကွေ့ခြင်း','7','{"title":"Diffraction of waves လှိုင်းပြန့်ခြင်း/ လှိုင်းကွေ့ခြင်း","paragraphs":[[{"text":"  Diffraction is the spreading of waves from the straight-on direction through a gap (or) moves around an obstacle. "}],[{"text":" အတားဆီးတစ်ခု၏ဘေး(သို့မဟုတ်) အပေါက်ကျဉ်းတစ်ခုကိုဖြတ်သန်းသောလှိုင်းသည် မျဉ်းဖြောင့်ဦးတည်ချက်မှ ဘေးသို့ပြန့်သွားရသည့်ဖြစ်စဉ်ကို လှိုင်းပြန့်ခြင်း(သို့မဟုတ်) လှိုင်းကွေ့ခြင်းဟုခေါ်သည်။"}]]}'::jsonb,14,true),
(10,'definitions','Sound အသံစွမ်းအင်','7','{"title":"Sound အသံစွမ်းအင်","paragraphs":[[{"text":" Sound is a form of energy that is transferred from one place to another in a certain medium. "}],[{"text":" အသံသည် ကြားခံနယ်တစ်မျိုးမျိုးထဲတွင် တစ်နေရာမှ တစ်နေရာသို့ကူးပြောင်းသွားနိုင်သည့် စွမ်းအင်အသွင် တစ် မျိုးဖြစ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,15,true),
(10,'definitions','Optic အလင်းပညာ','8','{"title":"Optic အလင်းပညာ","paragraphs":[[{"text":" The study of nature and propagation of light is known as optics."}],[{"text":" အလင်း၏သဘာဝနှင့် ပျံ့နှံ့ပုံတို့ကိုလေ့လာသောပညာရပ်ကို optic ဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Geometrical Optic','8','{"title":"Geometrical Optic","paragraphs":[[{"text":" The geometrical optics is based upon the fact that light travels in a straight line."}],[{"text":" အလင်းသည် ဖြောင့်တန်းစွာသွားသည်ဟူသည့် အချက်ပေါ်အခြေခံသောအလင်းပညာ = Geometrical optic"}]]}'::jsonb,1,true),
(10,'definitions','Physical Optic','8','{"title":"Physical Optic","paragraphs":[[{"text":" The physical optics is based upon the fact that light propagates by means of wave-motion."}],[{"text":" အလင်းသည်လှိုင်းအသွင်ဖြင့်ပြန့်နှံ့သည်ဟူသည့် အချက်ပေါ်အခြေခံသောအလင်းပညာ = physical optic"}]]}'::jsonb,2,true),
(10,'definitions','Light အလင်း','8','{"title":"Light အလင်း","paragraphs":[[{"text":" Light is a form of energy which stimulates our sense of vision."}],[{"text":" အလင်းသည် ကျွန်ုပ်တို့အမြင်အာရုံကိုနှိုးဆွပေးသော စွမ်းအင်အသွင်တစ်မျိုးဖြစ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Luminous sources ကိုယ်ပိုင်အလင်းလွှတ်အလင်းပင်ရင်းများ','8','{"title":"Luminous sources ကိုယ်ပိုင်အလင်းလွှတ်အလင်းပင်ရင်းများ","paragraphs":[[{"text":" Some objects such as the sun, the stars, the fluorescent lamps and the candles flames make their own light. These sources of light are called luminous sources. "}],[{"text":" နေ၊ ကြယ်၊ မီးသီးနှင့် ဖယောင်းတိုင်မီးတောက်ကဲ့သို့သောအချို့အရာဝတ္ထုများသည် ကိုယ်ပိုင်အလင်းထုတ်လွှတ် နိုင်ကြသည်။ ထိုကဲ့သို့အလင်းလွှတ်ပင်ရင်းများကို ကိုယ်ပိုင်အလင်းလွှတ်ပင်ရင်းများဟုခေါ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Non-luminous objects ကိုယ်ပိုင်အလင်းမလွှတ်သော ဝတ္ထုများ','8','{"title":"Non-luminous objects ကိုယ်ပိုင်အလင်းမလွှတ်သော ဝတ္ထုများ","paragraphs":[[{"text":" Most objects do not emit their own light but reflect light from luminous sources. They are non-luminous objects.  Eg. Human beings, tress, books"}],[{"text":" အရာဝတ္ထုအများစုသည် ကိုယ်ပိုင်အလင်းထုတ်လွှတ်နိုင်စွမ်းမရှိသော်လည်း အလင်းပင်ရင်းမှလာသည့်အလင်းများ ကို အလင်းပြန်စေနိုင်သည်။ ထိုပစ္စည်းများကို ကိုယ်ပိုင်အလင်းမလွှတ်သော ဝတ္ထုများဟုခေါ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Reflection of light','8','{"title":"Reflection of light","paragraphs":[[{"text":" When light is incident on the surface of an object, some of the light is sent back and this phenomenon is called reflection of light. "}],[{"text":" အရာဝတ္ထု၏မျက်နှာပြင်ပေါ်သို့အလင်းထိရိုက်သောအခါ အချို့သောအလင်းများအား ယင်းမျက်နှာပြင်မှ ဦးတည် ရာပြောင်း၍ပြန်ထွက်လာခြင်းကို အလင်းပြန်ခြင်းဟုခေါ်သည်။"}]]}'::jsonb,6,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','A ray of light အလင်းတန်း','8','{"title":"A ray of light အလင်းတန်း","paragraphs":[[{"text":"  A ray of light is a path along which the light travels. "}],[{"text":" အလင်းသွားရာလမ်းကြောင်းကို အလင်းတန်းဟုခေါ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','A beam of light အလင်းတန်းစု','8','{"title":"A beam of light အလင်းတန်းစု","paragraphs":[[{"text":" A beam of light is a collection of rays of light."}],[{"text":" အလင်းတန်းများအစုဝေးကို အလင်းတန်းစုဟုခေါ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Parallel beam of light ပြိုင်လင်းတန်းစု','8','{"title":"Parallel beam of light ပြိုင်လင်းတန်းစု","paragraphs":[[{"text":" If the rays of light are parallel to one another, the beam of light is called parallel beam."}],[{"text":" အလင်းတန်းများတစ်ခုနှင့်တစ်ခုပြိုင်နေကြလျှင် ထိုအလင်းတန်းစုကို ပြိုင်လင်းတန်းစုဟုခေါ်သည်။"}],[{"text":" Eg. A beam of light received from a distant source,"}],[{"text":"  Searchlights used in trains and lighthouses, emit parallel beam of light."}],[{"text":" ဥပမာ- အဝေးတစ်နေရာမှလာသောအလင်းများ၊ ရထားများ မီးပြတိုက်များတွင်သုံးသည့် မီးများ "}]]}'::jsonb,9,true),
(10,'definitions','Convergent beam of light စုဆုံအလင်းတန်းစု','8','{"title":"Convergent beam of light စုဆုံအလင်းတန်းစု","paragraphs":[[{"text":" If the rays of light converge to a point, the beam of light is called a convergent beam."}],[{"text":" အလင်းတန်းများအမှတ်တစ်ခု၌စုဆုံသွားကြလျှင် ထိုအလင်းတန်းစုကို စုဆုံအလင်းတန်းစုဟုခေါ်သည်။"}],[{"text":" Parallel beam of light become a convergent beam after passing through a convex lens (or) concave mirror."}],[{"text":" ပြိုင်လင်းတန်းများသည် မှန်ဘီလူးခုံး/ ကြေးမုံခွက်ကိုဖြတ်ပြီး စုဆုံအလင်းတန်းစုများဖြစ်ပေါ်လာသည်။"}]]}'::jsonb,10,true),
(10,'definitions','Divergent beam of light ခွဲဖြာအလင်းတန်းစု','8','{"title":"Divergent beam of light ခွဲဖြာအလင်းတန်းစု","paragraphs":[[{"text":" If the rays of light diverge from a point, the beam of light is called a divergent beam."}],[{"text":" အလင်းတန်းများသည်အမှတ်တစ်ခုမှခွဲဖြာလာခဲ့ပါက ထိုအလင်းတန်းစုကို ခွဲဖြာအလင်းတန်းစုဟုခေါ်သည်။"}],[{"text":" A beam emitted by a light bulb is a divergent beam."}],[{"text":" မီးသီးမှထုတ်လွှတ်လိုက်သောအလင်းတန်းစုသည် ခွဲဖြာအလင်းတန်းစုဖြစ်သည်။"}]]}'::jsonb,11,true),
(10,'definitions','Incident Ray ရိုက်လင်းတန်း','8','{"title":"Incident Ray ရိုက်လင်းတန်း","paragraphs":[[{"text":" A ray which represents the incident light is an incident ray. "}],[{"text":" မျက်နှာပြင်ကိုလာထိသည့်အလင်းအား ကိုယ်စားပြုဖော်ပြသောအလင်းတန်းကို ရိုက်လင်းတန်းဟုခေါ်သည်။"}]]}'::jsonb,12,true),
(10,'definitions','Reflected Ray ပြန်လင်းတန်း','8','{"title":"Reflected Ray ပြန်လင်းတန်း","paragraphs":[[{"text":" A ray which represents the reflected light is a reflected ray. "}],[{"text":" မျက်နှာပြင်မှပြန်ထွက်လာသည့်အလင်းအား ကိုယ်စားပြုဖော်ပြသောအလင်းတန်းကို ပြန်လင်းတန်းဟုခေါ်သည်။"}]]}'::jsonb,13,true),
(10,'definitions','Normal မတ်မျဉ်း','8','{"title":"Normal မတ်မျဉ်း","paragraphs":[[{"text":" A line perpendicular to the surface at the point of incidence is called a normal. "}],[{"text":" အလင်းထိရိုက်သည့်အမှတ်တွင် မျက်နှာပြင်ပေါ်ထောင့်မတ်ကျ၍ဆွဲထားသောမျဉ်းကို မတ်မျဉ်းဟုခေါ်သည်။"}]]}'::jsonb,14,true),
(10,'definitions','Angle of Incidence (i) ရိုက်ထောင့်','8','{"title":"Angle of Incidence (i) ရိုက်ထောင့်","paragraphs":[[{"text":" An angle between the incident ray and the normal is an angle of incidence. "}],[{"text":" ရိုက်လင်းတန်းနှင့် မတ်မျဉ်းကြားရှိထောင့်ကို ရိုက်ထောင့်ဟုခေါ်သည်။"}]]}'::jsonb,15,true),
(10,'definitions','Angle of Reflection (r) ပြန်ထောင့်','8','{"title":"Angle of Reflection (r) ပြန်ထောင့်","paragraphs":[[{"text":" An angle between the reflected ray and the normal is an angle of reflection."}],[{"text":" ပြန်လင်းတန်းနှင့် မတ်မျဉ်းကြားရှိထောင့်ကို ပြန်ထောင့်ဟုခေါ်သည်။"}]]}'::jsonb,16,true),
(10,'definitions','Laws of Reflection အလင်းပြန်ခြင်း နိယာမ','8','{"title":"Laws of Reflection အလင်းပြန်ခြင်း နိယာမ","paragraphs":[[{"text":" (1) The incident ray, the reflected ray and the normal all lie in the same plane. "}],[{"text":" (2) The angle of incidence is equal to the angle of reflection. "}],[{"text":" ရိုက်လင်းတန်း၊ ပြန်လင်းတန်းနှင့် မတ်မျဉ်းတို့သည် ပြင်ညီတစ်ခုတည်းပေါ်တွင်ရှိသည်။ ရိုက်ထောင့်နှင့် ပြန် ထောင့်တို့တူညီကြသည်။"}]]}'::jsonb,17,true),
(10,'definitions','Mirror ကြေးမုံ','8','{"title":"Mirror ကြေးမုံ","paragraphs":[[{"text":" An object having a smooth reflecting surface is called a mirror. "}],[{"text":"A common mirror is a plane mirror. "}],[{"text":"ချောမွေ့သည့် အလင်းပြန်မျက်နှာပြင်တစ်ဖက်ရှိသောဝတ္ထုကို ကြေးမုံဟုခေါ်သည်။ (ပြင်ညီကြေးမုံကို အသုံးများ)"}]]}'::jsonb,18,true),
(10,'definitions','Plane mirror ပြင်ညီကြေးမုံ','8','{"title":"Plane mirror ပြင်ညီကြေးမုံ","paragraphs":[[{"text":" If the reflecting surface is plane, the mirror is called a plane mirror. Eg. looking glass."}],[{"text":" ကြေးမုံ၏အလင်းပြန်သောမျက်နှာပြင်သည် ပြင်ညီဖြစ်နေလျှင် ပြင်ညီကြေးမုံဟုခေါ်သည်။"}]]}'::jsonb,19,true),
(10,'definitions','Virtual image ပုံရိပ်ယောင်','8','{"title":"Virtual image ပုံရိပ်ယောင်","paragraphs":[[{"text":" The image formed by the apparent intersection of the reflected rays produced backward is a virtual image."}],[{"text":"The virtual image cannot be formed on a screen. It is inverted."}],[{"text":"ပြန်လင်းတန်းများကိုနောက်ပြန်ဆက်ဆွဲမှ ဖြတ်သွားသည့်ဟုထင်ရပြီး ပေါ်လာသည့်ပုံရိပ်ကို ပုံရိပ်ယောင်ဟုခေါ် သည်။ ကားချပ်ပေါ်တွင် ဖမ်းယူ၍မရ၊ ကြေးမုံအတွင်း၌သာပုံရိပ်ကိုမြင်ရသည်။"}]]}'::jsonb,20,true),
(10,'definitions','Real image ပုံရိပ်စစ်','8','{"title":"Real image ပုံရိပ်စစ်","paragraphs":[[{"text":" The image formed by the actual intersection of the reflected rays is a real image. "}],[{"text":"A real image can be focused on a screen. It is erect."}],[{"text":" ပြန်လင်းတန်းများအမှန်တကယ်ဖြတ်သွားပြီး ပေါ်လာသည့်ပုံရိပ်ကို ပုံရိပ်စစ်ဟုခေါ်သည်။"}]]}'::jsonb,21,true),
(10,'definitions','Properties of an Image in a Plane Mirror','8','{"title":"Properties of an Image in a Plane Mirror","paragraphs":[[{"text":"The image is of the same size as the object."}],[{"text":"အရွယ်တူ"}],[{"text":"The image is virtual."}],[{"text":"ပုံရိပ်ယောင်"}],[{"text":"The image is erect."}],[{"text":"အတည့်ပေါ်"}],[{"text":"The image is laterally inverted."}],[{"text":"ဘက်ခြင်းပြောင်းပြန်"}],[{"text":"The image is situated on the line passing through the object and perpendicular to the plane mirror."}],[{"text":"တတန်းတည်း"}],[{"text":"The image is as far behind the mirror as the object is in front."}],[{"text":"အကွာအဝေးတူ"}]]}'::jsonb,22,true),
(10,'definitions','Principle of Reversibility of Light ပြောင်းပြန်လှန်နိုင်သော အလင်းလမ်းကြောင်းနိယာမ','8','{"title":"Principle of Reversibility of Light ပြောင်းပြန်လှန်နိုင်သော အလင်းလမ်းကြောင်းနိယာမ","paragraphs":[[{"text":" If the direction of a ray of light is reversed, the light ray will travel along its original path. This is known as the principle of reversibility of light. "}],[{"text":" အလင်းတန်းဦးတည်ချက်ကိုပြောင်းပြန်ပေးလိုက်ပါက အလင်းတန်းသည် မူလလမ်းကြောင်းအတိုင်းပင်သွားမည်။ ပြန်လင်းတန်းလမ်းကြောင်းအတိုင်းအလင်းရိုက်ပါက မူလရိုက်လင်းတန်းလမ်းကြောင်းပေါ်တထပ်တည်းပြန်မည်။"}]]}'::jsonb,23,true),
(10,'definitions','Concave Mirror ကြေးမုံခွက်','8','{"title":"Concave Mirror ကြေးမုံခွက်","paragraphs":[[{"text":" If the reflecting surface of a mirror forms part of the inner surface of a hollow sphere, the mirror is called a concave mirror. "}],[{"text":" Eg. Shaving mirror, torchlight, telescope, car head lamp."}],[{"text":" ကြေးမုံတစ်ချပ်၏အလင်းပြန်မျက်နှာပြင်သည် အခေါင်းပေါက်ပါစက်လုံး၏ အတွင်းဘက်မျက်နှာပြင်ကဲ့သို့ခွက်နေ ပါက ကြေးမုံခွက်ဟုခေါ်သည်။"}]]}'::jsonb,24,true),
(10,'definitions','Convex Mirror ကြေးမုံခုံး','8','{"title":"Convex Mirror ကြေးမုံခုံး","paragraphs":[[{"text":" If the reflecting surface of a mirror forms part of the outer surface of a hollow sphere, the mirror is called a convex mirror."}],[{"text":" Eg. Car rear view mirror"}],[{"text":" ကြေးမုံတစ်ချပ်၏ အလင်းပြန်မျက်နှာပြင်သည် အခေါင်းပေါက်ပါစက်လုံး၏ အပြင်ဘက်မျက်နှာပြင်ကဲ့သို့ခုံးနေ ပါ က ကြေးမုံခုံးဟုခေါ်သည်။"}]]}'::jsonb,25,true),
(10,'definitions','Pole of a concave (or) convex mirror','8','{"title":"Pole of a concave (or) convex mirror","paragraphs":[[{"text":" The centre of the surface of a concave (or) convex mirror is called its pole. "}],[{"text":" ကြေးမုံခွက် (သို့) ကြေးမုံခုံးတစ်ခု၏ မျက်နှာပြင်အလယ်ဗဟိုမှတ်ကို pole (ဝင်ရိုးမှတ်) ဟုခေါ်သည်။"}]]}'::jsonb,26,true),
(10,'definitions','Centre of Curvature of a Concave or Convex Mirror ကြေးမုံခွက်ကြေးမုံခုံး၏ ကွေးမှုဗဟို','8','{"title":"Centre of Curvature of a Concave or Convex Mirror ကြေးမုံခွက်ကြေးမုံခုံး၏ ကွေးမှုဗဟို","paragraphs":[[{"text":" The centre of a sphere, part of whose surface is the concave (or) convex mirror, is called the centre of curvature of that mirror. "}],[{"text":" မျက်နှာပြင်တစိတ်တပိုင်းကို ကြေးမုံခွက်(သို့) ကြေးမုံခုံးအဖြစ်သုံးထားသည့် စက်လုံး၏ဗဟိုကို ကြေးမုံ၏ကွေးမှု ဗဟိုဟုခေါ်သည်။ "}]]}'::jsonb,27,true),
(10,'definitions','Radius of Curvature of a Concave (or) Convex Mirror','8','{"title":"Radius of Curvature of a Concave (or) Convex Mirror","paragraphs":[[{"text":" The radius of a sphere, part of whose surface is the concave (or) convex mirror, is called the radius of curvature of that mirror. "}],[{"text":" မျက်နှာပြင်တစိတ်တပိုင်းကို ကြေးမုံခွက်(သို့) ကြေးမုံခုံးအဖြစ်သုံးထားသည့် စက်လုံး၏အချင်းဝက်ကို ကွေးမှု အချင်းဝက်ဟုခေါ်သည်။"}]]}'::jsonb,28,true),
(10,'definitions','Principal Axis မူလဝင်ရိုး','8','{"title":"Principal Axis မူလဝင်ရိုး","paragraphs":[[{"text":" The line passing through the centre of curvature and the pole of a concave (or) convex mirror is called the principal axis. "}],[{"text":" ကြေးမုံခွက်(သို့)ကြေးမုံခုံး၏ pole နှင့် ကွေးမှုဗဟိုကို ဆက်ဆွဲထားသောမျဉ်းကို မူလဝင်ရိုးဟုခေါ်သည်။"}]]}'::jsonb,29,true),
(10,'definitions','Principal Focus of a Concave Mirror ကြေးမုံခွက်၏မူလဆုံမှတ်','8','{"title":"Principal Focus of a Concave Mirror ကြေးမုံခွက်၏မူလဆုံမှတ်","paragraphs":[[{"text":" When the rays parallel and close to the principal axis are incident on a concave mirror, the reflected rays pass through a point on the principal axis. That point is called the principal focus of the concave mirror. "}],[{"text":" မူလဝင်ရိုးနှင့်အပြိုင် နီးကပ်စွာလာသည့်အလင်တန်းများက ကြေးမုံခွက်ကို ထိရိုက်သောအခါ ဖြစ်ပေါ်လာသော ပြန်လင်းတန်းများက မူလဝင်ရိုးပေါ်ရှိ အမှတ်တစ်ခုတွင်ဖြတ်သည်။ ထိုအမှတ်ကို ကြေးမုံခွက်၏မူလဆုံချက်ဟု ခေါ်သည်။"}]]}'::jsonb,30,true),
(10,'definitions','Principal Focus of a Convex Mirror ကြေးမုံခုံး၏ မူလဆုံမှတ်','8','{"title":"Principal Focus of a Convex Mirror ကြေးမုံခုံး၏ မူလဆုံမှတ်","paragraphs":[[{"text":" When the rays parallel and close to the principal axis are incident on a convex mirror, the reflected rays appear to come from a point on the principal axis. That point is called the principal focus of the convex mirror. "}],[{"text":" မူလဝင်ရိုးနှင့်အပြိုင် နီးကပ်စွာလာသည့်အလင်တန်းများက ကြေးမုံခုံးကို ထိရိုက်သောအခါ ဖြစ်ပေါ်လာသော ပြန် လင်းတန်းများက မူလဝင်ရိုးပေါ်ရှိ အမှတ်တစ်ခုမှလာသည်ဟု ထင်ရသည်။ ထိုအမှတ်ကို ကြေးမုံခုံး၏မူလဆုံချက် ဟု ခေါ်သည်။"}]]}'::jsonb,31,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','Focal Length ဆုံတာ','8','{"title":"Focal Length ဆုံတာ","paragraphs":[[{"text":" The distance between the pole and the focus of a concave (or) convex mirror is called the focal length of the concave (or) convex mirror."}],[{"text":" ကြေးမုံခွက် (သို့) ကြေးမုံခုံး၏ pole နှင့် အလင်းဆုံချက်ကြားအကွာအဝေးကို ဆုံတာဟုခေါ်သည်။"}]]}'::jsonb,32,true),
(10,'definitions','Magnification ချဲ့ကိန်း','8','{"title":"Magnification ချဲ့ကိန်း","paragraphs":[[{"text":" The lateral magnification produced by a mirror is defined as the ratio of the height of the image to the height of the object. "}],[{"text":" ပုံရိပ်၏အမြင့်နှင့် ဝတ္ထု၏အမြင့်တို့အချိုးကို ထိုပုံရိပ်ကိုထုတ်ပေးသည့်ကြေးမုံ၏ဘေးတိုက်ချဲ့ကိန်းဟုခေါ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,33,true),
(10,'definitions','Electrostatics (or) static electricity တည်ငြိမ်လျှပ်စစ်','9','{"title":"Electrostatics (or) static electricity တည်ငြိမ်လျှပ်စစ်","paragraphs":[[{"text":" Electrostatics is the study of electric charge at rest."}],[{"text":" ရွေ့လျားမှုမရှိသောလျှပ်မှုန်များကို လေ့လာသည့်ပညာရပ်ကို electrostatics ဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Electrodynamics တည်ငြိမ်လျှပ်စစ်','9','{"title":"Electrodynamics တည်ငြိမ်လျှပ်စစ်","paragraphs":[[{"text":" Electrodynamics is the study of moving electric charges and their interaction with magnetic and electric fields."}],[{"text":" ရွေ့လျားနေသောလျှပ်မှုန်များနှင့် ၎င်းတို့၏သံလိုက်စက်ကွင်းနှင့် လျှပ်စစ်စက်ကွင်းတို့ပေါ် သက်ရောက်မှုများကို လေ့လာသောပညာရပ်ကို electrodynamics ဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Electric charge  လျှပ်စစ်ဓာတ်','9','{"title":"Electric charge  လျှပ်စစ်ဓာတ်","paragraphs":[[{"text":" Electric charge is the physical property of matter that causes an electric force when placed in an electromagnetic field."}],[{"text":" လျှပ်စစ်သံလိုက်စက်ကွင်းအတွင်းရှိ ဒြပ်သားများကို လျှပ်စစ်အားသက်ရောက်မှု ဖြစ်စေသော ဒြပ်တို့၏ရုပ်ဂုဏ် သတ္တိကို လျှပ်စစ်ဓာတ်ဟုခေါ်သည်။"}]]}'::jsonb,2,true),
(10,'definitions','Electric current  လျှပ်စစ်စီးကြောင်း','9','{"title":"Electric current  လျှပ်စစ်စီးကြောင်း","paragraphs":[[{"text":" The flow of electric charges is called an electric current. "}],[{"text":" လျှပ်စစ်ဓာတ်ဆောင်အမှုန်များရွေ့လျားခြင်းကို လျှပ်စစ်စီးကြောင်းဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Bond electron   စည်းနှောင် အီလက်ထရွန်','9','{"title":"Bond electron   စည်းနှောင် အီလက်ထရွန်","paragraphs":[[{"text":" The inner electron that is tightly bound by the nucleus (or) an electron closer to the nucleus is called a bound electron. "}],[{"text":" နျူကလိယ၏တင်ကျပ်စွာစည်းနှောင်ထားခြင်းခံရသော အတွင်းပတ်လမ်းရှိ နျူကလိယနှင့်နီးသည့် အီလက်ထရွန် များကို စည်းနှောင်အီလက်ထရွန်များဟုခေါ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Free electron လွတ်လပ်အီလက်ထရွန်','9','{"title":"Free electron လွတ်လပ်အီလက်ထရွန်","paragraphs":[[{"text":" The outer electron that is loosely bound by the nucleus (or) an electron far away from the nucleus is called a free electron.  "}],[{"text":" နျူကလိယ၏လျော့ရဲစွာစည်းနှောင်ထားခြင်းခံရသော အပြင်ပတ်လမ်းရှိ နျူကလိယနှင့်ဝေးသည့် အီလက်ထရွန် များကို လွတ်လပ်အီလက်ထရွန်များဟုခေါ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Conductor လျှပ်ကူးပစ္စည်း','9','{"title":"Conductor လျှပ်ကူးပစ္စည်း","paragraphs":[[{"text":" The substance which has plenty of free electrons is called a conductor. "}],[{"text":" လွတ်လပ်အီလက်ထရွန်များစွာပါရှိ‌သောပစ္စည်းကို လျှပ်ကူးပစ္စည်းဟုခေါ်သည်။"}]]}'::jsonb,6,true),
(10,'definitions','Insulator လျှပ်ကာ','9','{"title":"Insulator လျှပ်ကာ","paragraphs":[[{"text":" The substance which has very few (or) no free electrons is called an insulator. "}],[{"text":" လွတ်လပ်အီလက်ထရွန် မပါသလောက်နည်းသော(သို့)မပါသောပစ္စည်းကို လျှပ်ကာပစ္စည်းဟုခေါ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','Semiconductor တပိုင်းလျှပ်ကူး','9','{"title":"Semiconductor တပိုင်းလျှပ်ကူး","paragraphs":[[{"text":" Some substances which contain a moderate amount of free electrons are called semiconductors."}],[{"text":" လွတ်လပ်အီလက်ထရွန် သင့်တင့်ရုံမျှသာပါရှိသောပစ္စည်းများကို တပိုင်းလျှပ်ကူးပစ္စည်းများဟုခေါ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Charging by friction ပွတ်တိုက်ခြင်းဖြင့် လျှပ်စစ်ဓာတ်ဖြစ်ပေါ်စေခြင်း','9','{"title":"Charging by friction ပွတ်တိုက်ခြင်းဖြင့် လျှပ်စစ်ဓာတ်ဖြစ်ပေါ်စေခြင်း","paragraphs":[[{"text":" If two uncharged objects are rubbed with one another, both of them become charged. This is called charging by friction."}],[{"text":" လျှပ်စစ်ဓာတ်မဆောင်သောပစ္စည်း ၂ ခုကို အချင်းချင်းပွတ်တိုက်ပါက ၎င်းတို့သည် လျှပ်စစ်ဓာတ်ဆောင်လာ သည်။ ထိုဖြစ်စဉ်ကို ပွတ်တိုက်ခြင်းဖြင့် လျှပ်စစ်ဓာတ်ဖြစ်ပေါ်စေခြင်း ဟုခေါ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Induction လျှပ်ညှို့ခြင်း','9','{"title":"Induction လျှပ်ညှို့ခြင်း","paragraphs":[[{"text":" Induction is the process of charging a conductor without any contact with the charged body."}],[{"text":" လျှပ်စစ်ဓာတ်ဆောင်ပစ္စည်းတစ်ခုနှင့်ထိတွေ့ရန်မလိုဘဲ လျှပ်ကူးပစ္စည်းတစ်ခုအား လျှပ်စစ်ဓာတ်ပေါ်လာစေခြင်း ကို လျှပ်ညှို့ခြင်းဟုခေါ်သည်။"}]]}'::jsonb,10,true),
(10,'definitions','Law of conservation of electric charge လျှပ်စစ်ဓာတ်တည်မြဲခြင်းနိယာမ','9','{"title":"Law of conservation of electric charge လျှပ်စစ်ဓာတ်တည်မြဲခြင်းနိယာမ","paragraphs":[[{"text":" The net electric charge in an isolated system remains constant. The net charge is the algebraic sum of the charges in an isolated system."}],[{"text":"ပြင်ပနှင့်လျှပ်ကူးမှုမရှိအောင်ဖန်တီးထားသော သီးခြားဖြစ်တည်အဖွဲ့အစည်းတစ်ခု၏ အသားတင်လျှပ်စစ်ပမာဏ သည်ကိန်းသေဖြစ်သည်။ အသားတင်လျှပ်စစ်ဓာတ်ဆိုသည်မှာ အဖွဲ့အစည်းအတွင်းရှိ အပေါင်းလျှပ်စစ်ဓာတ်နှင့် အနှုတ်လျှပ်စစ်ဓာတ်အားလုံးကို သင်္ချာနည်းအရ ပေါင်းထားခြင်းဖြစ်သည်။"}],[{"text":"*********************************"}]]}'::jsonb,11,true),
(10,'definitions','Magnet သံလိုက်','10','{"title":"Magnet သံလိုက်","paragraphs":[[{"text":" Magnets are the material which exhibit magnetic properties such as (1) attract magnetic materials, (2) have two poles, and (3) like poles repel and unlike poles attract."}],[{"text":" သံလိုက်ဓာတ်ပါပစ္စည်းများကိုဆွဲယူနိုင်ခြင်း၊ ဝင်ရိုးစွန်း ၂ ခုပါရှိခြင်း၊ မျိုးတူဝင်ရိုးစွန်းများအချင်းချင်း တွန်းကန်ပြီး မျိုးမတူဝင်ရိုးစွန်းများအချင်းချင်းဆွဲယူခြင်းစသည့်ဂုဏ်သတ္တိများပြသော ပစ္စည်းမျိုးကိုသံလိုက်ဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Magnetic materials သံလိုက်ဓာတ်ပါပစ္စည်းများ','10','{"title":"Magnetic materials သံလိုက်ဓာတ်ပါပစ္စည်းများ","paragraphs":[[{"text":" Materials such as cobalt, nickel and some alloys such as steel that are attracted by a magnet are called magnetic materials. "}],[{"text":" သံလိုက်၏ဆွဲယူခြင်းကိုခံရသည့် ကိုဘော့၊ နီကယ်နှင့် စတီးကဲ့သို့အချို့သောသတ္တုရောများကို သံလိုက်ဓာတ်ပါ ပစ္စည်းများဟုခေါ်သည်။"}]]}'::jsonb,1,true),
(10,'definitions','Non-magnetic materials သံလိုက်ဓာတ်မပါပစ္စည်းများ','10','{"title":"Non-magnetic materials သံလိုက်ဓာတ်မပါပစ္စည်းများ","paragraphs":[[{"text":" Materials such as brass, copper, wood and plastics that are not attracted by a magnet are called non-magnetic materials. "}],[{"text":" သံလိုက်ကဆွဲယူနိုင်စွမ်းမရှိသော ကြေးဝါ၊ ကြေးနီ၊ သစ်သားနှင့် ပလတ်စတစ်ကဲ့သို့ ပစ္စည်းများကို သံလိုက်ဓာတ် မပါပစ္စည်းများဟုခေါ်သည်။"}]]}'::jsonb,2,true),
(10,'definitions','Permanent magnet ထာဝရသံလိုက်','10','{"title":"Permanent magnet ထာဝရသံလိုက်","paragraphs":[[{"text":" Any materials (such as magnetite) that is able to keep its magnetism for a long time is called a permanent magnet. "}],[{"text":" သံလိုက်ဓာတ်ကိုကြာရှည်စွာထိန်းထားနိုင်သော တွင်းထွက်သံလိုက်ကျောက်ကဲ့သို့ပစ္စည်းတိုင်းကို ထာဝရသံလိုက် ဟုခေါ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Law of magnetic poles','10','{"title":"Law of magnetic poles","paragraphs":[[{"text":" Like poles repel and unlike poles attract."}],[{"text":" မျိုးတူဝင်ရိုးစွန်းများတွန်းကန်ကာ မျိုးမတူဝင်ရိုးစွန်းများဆွဲငင်ကြသည်။"}]]}'::jsonb,4,true),
(10,'definitions','Magnetic pole strength သံလိုက်ဝင်ရိုးစွန်းပြင်းအား','10','{"title":"Magnetic pole strength သံလိုက်ဝင်ရိုးစွန်းပြင်းအား","paragraphs":[[{"text":" Magnetic pole strength is a measure of the strength of magnetic poles. "}],[{"text":" သံလိုက်ဝင်ရိုးစွန်းပြင်းအားသည် သံလိုက်၏ဝင်ရိုးစွန်းများတွင်ရှိသည့်အားကိုဖော်ပြသော တိုင်းတာမှုဖြစ်သည်။"}]]}'::jsonb,5,true),
(10,'definitions','Magnetic force သံလိုက်အား','10','{"title":"Magnetic force သံလိုက်အား","paragraphs":[[{"text":" The magnetic force between the two poles is directly proportional to the product of the pole strengths and inversely proportional to the distance squared between them."}],[{"text":" သံလိုက်ဝင်ရိုးစွန်း ၂ ခုကြားအားသည် ၎င်းတို့၏ဝင်ရိုးစွန်းပြင်းအားများမြှောက်ခြင်းနှင့်တိုက်ရိုက်အချိုးကျကာ ၎င်း တို့၏အကွာအဝေး ၂ ထပ်နှင့်ပြောင်းပြန်အချိုးကျသည်။"}]]}'::jsonb,6,true),
(10,'definitions','Magnetic fields သံလိုက်စက်ကွင်း','10','{"title":"Magnetic fields သံလိုက်စက်ကွင်း","paragraphs":[[{"text":" The magnetic field is a region where magnetic effects can be detected."}],[{"text":" သံလိုက်သက်ရောက်မှုများတွေ့ရှိနိုင်သည့်နယ်ပယ်ကို သံလိုက်စက်ကွင်းဟုခေါ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','Magnetisation သံလိုက်ဓာတ်ပေါ်စေခြင်း','10','{"title":"Magnetisation သံလိုက်ဓာတ်ပေါ်စေခြင်း","paragraphs":[[{"text":" A process of making a magnetic material into a magnet is called magnetisation. "}],[{"text":" သံလိုက်ဓာတ်ပါပစ္စည်းတစ်ခုကို သံလိုက်ဖြစ်အောင်ပြုလုပ်သော ဖြစ်စဉ်ကို magnetisation ဟုခေါ်သည်။"}]]}'::jsonb,8,true),
(10,'definitions','Induced Magnetism ညှို့ရသံလိုက်ဓာတ်','10','{"title":"Induced Magnetism ညှို့ရသံလိုက်ဓာတ်","paragraphs":[[{"text":" When a piece of unmagnetised magnetic material (such as iron or steel) is brought near to the pole of a permanent magnet, it is attracted to the magnet and becomes a magnet itself. This is called induced magnetism. "}],[{"text":" သံလိုက်မဖြစ်သေးသည့် သံလိုက်ဓာတ်ပါပစ္စည်းအချို့ (ဥပမာ- သံ၊ စတီး) တို့ကို ထာဝရသံလိုက်၏ဝင်ရိုးစွန်း အနီး သို့ ယူလာပါက ၎င်းတို့ကိုသံလိုက်ကဆွဲယူပြီး သံလိုက်ဖြစ်လာတော့သည်။ ထိုကဲ့သို့သံလိုက်ဖြစ်စေခြင်းနည်းကို ညှို့ရသံလိုက်ဓာတ်ပေါ်စေခြင်းဟုခေါ်သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Hard magnetic materials','10','{"title":"Hard magnetic materials","paragraphs":[[{"text":" Magnetic materials such as steel which are harder to magnetise but retain their magnetism longer are called hard magnetic materials. "}],[{"text":" သံလိုက်ဓာတ်ကို အချိန်ကြာရှည်စွာထိန်းထားနိုင်သော်လည်း သံလိုက်ဓာတ်ပေါ်အောင်လုပ်ရခက်သည့်စတီးကဲ့သို့ သံလိုက်ဓာတ်ပါပစ္စည်းများကို hard magnetic material များဟုခေါ်သည်။"}]]}'::jsonb,10,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'definitions','Soft magnetic materials','10','{"title":"Soft magnetic materials","paragraphs":[[{"text":" Magnetic materials such as iron or special alloys like mumetal alloy which are easier to magnetise but do not retain their magnetism very long are called soft magnetic materials."}],[{"text":" သံလိုက်ဓာတ်ကို အချိန်ကြာရှည်စွာထိန်းမထားနိုင်သော်လည်း သံလိုက်ဓာတ်ပေါ်အောင်လုပ်ရလွယ်သည့် သံ(သို့) mumetal(သံနှင့်နီကယ်အရော)ကဲ့သို့ သံလိုက်ဓာတ်ပါပစ္စည်းများကို soft magnetic material များဟုခေါ်သည်။"}]]}'::jsonb,11,true),
(10,'definitions','The comparison of magnetic properties between iron and steel','10','{"title":"The comparison of magnetic properties between iron and steel","paragraphs":[[{"text":"The magnetic properties of iron | The magnetic properties of steel"}],[{"text":"- | can be easily magnetised and demagnetized\nသံလိုက်ဓာတ် ရလွယ်၊ ပျက်လွယ် | - | is hard to magnetise and demagnetise than iron\nသံလိုက်ဓာတ်ရရန်ခက်၊ ပျက်ရန်ခက်"}],[{"text":"- | can be magnetised by a weak magnetic field\nအားပျော့သောသံလိုက်စက်ကွင်းဖြင့်ပင် သံလိုက်ဓာတ်သွင်းနိုင် | - | requires a strong magnetic field to magnetise\nအားကောင်းသော သံလိုက်စက်ကွင်းမှသာ သံလိုက် ဓာတ်သွင်းနိုင်"}],[{"text":"- | retains its magnetism temporarily\nသံလိုက်ဓာတ်ကို ခနသာထိန်းထားနိုင် | - | retains its magnetism permanently\nသံလိုက်ဓာတ်ကို ကြာရှည်စွာထိန်းထားနိုင်"}],[{"text":"*********************************"}]]}'::jsonb,12,true),
(10,'definitions','Thermionic Emission (or) thermal electron emission အပူပေး electron ထုတ်လွှတ်ခြင်း','11','{"title":"Thermionic Emission (or) thermal electron emission အပူပေး electron ထုတ်လွှတ်ခြင်း","paragraphs":[[{"text":" The process by which, free electrons are emitted from the surface of a metal when external heat energy is applied, is called thermionic emission. "}],[{"text":" ပြင်ပမှအပူစွမ်းအင်ရရှိသောအခါ သတ္တုတစ်ခု၏မျက်နှာပြင်မှ လွတ်လပ်အီလက်ထရွန်ထုတ်လွှတ်ခြင်းဖြစ်စဉ်ကို thermionic emission ဟုခေါ်သည်။"}]]}'::jsonb,0,true),
(10,'definitions','Vacuum Diode လေဟာနယ်ဒိုင်အုပ်','11','{"title":"Vacuum Diode လေဟာနယ်ဒိုင်အုပ်","paragraphs":[[{"text":" Vacuum diode is the simplest form of vacuum tube. It consists of two electrodes, a cathode and an anode (or) plate. "}],[{"text":" Vacuum diode သည် အရိုးရှင်းဆုံးသော လေဟာနယ်ဖန်ပြွန်ဖြစ်သည်။ ဓာတ်မလျှပ်ငုတ် (cathode) နှင့် ဓာတ်ဖို လျှပ်ငုတ် (anode) ဟူသော လျှပ်ငုတ် ၂ ခုပါရှိသည်။"}]]}'::jsonb,1,true),
(10,'definitions','Cathode ဓာတ်မလျှပ်ငုတ်','11','{"title":"Cathode ဓာတ်မလျှပ်ငုတ်","paragraphs":[[{"text":" Cathode is an electron emitter and emits the free electrons by thermionic emission."}],[{"text":" ဓာတ်မလျှပ်ငုတ်သည် အီလက်ထရွန်ကိုထုတ်လွှတ်သည့် လျှပ်ငုတ်တစ်ခုဖြစ်သည်။"}]]}'::jsonb,2,true),
(10,'definitions','Anode ဓာတ်ဖိုလျှပ်ငုတ်','11','{"title":"Anode ဓာတ်ဖိုလျှပ်ငုတ်","paragraphs":[[{"text":" Anode collects the electrons."}],[{"text":" ဓာတ်ဖိုလျှပ်ငုတ်သည် အီလက်ထရွန်ကိုဖမ်းယူသည့် လျှပ်ငုတ်တစ်ခုဖြစ်သည်။"}]]}'::jsonb,3,true),
(10,'definitions','Black body အနက်ထည်','11','{"title":"Black body အနက်ထည်","paragraphs":[[{"text":" A blackbody is a perfect radiator of light that absorbs and emits all radiation incident on it. "}],[{"text":" အနက်ထည်သည် ၎င်းအပေါ်ကျရောက်သည့် ဖြာထွက်စွမ်းအင်အားလုံးကိုစုပ်ယူနိုင်ပြီး အပြည့်အဝပြန်ထုတ်နိုင် သည့် ပစ္စည်းဖြစ်သည်။"}]]}'::jsonb,4,true),
(10,'definitions','Blackbody radiation','11','{"title":"Blackbody radiation","paragraphs":[[{"text":" When a blackbody is heated, the radiation it emits is called blackbody radiation. "}],[{"text":" အနက်ထည်တစ်ခုကိုအပူပေးသောအခါ ၎င်းမှထုတ်သည့်ဖြာထွက်စွမ်းအင်ကို အနက်ထည်ဖြာထွက်မှုဟုခေါ်သည်"}]]}'::jsonb,5,true),
(10,'definitions','Intensity of radiation ဖြာထွက်ပြင်းအား','11','{"title":"Intensity of radiation ဖြာထွက်ပြင်းအား","paragraphs":[[{"text":" The intensity of the radiation is the energy emitted from unit area of the surface in one second."}],[{"text":" မျက်နှာပြင်တစ်ခု၏ ၁ ယူနစ်ဧရိယာမှ အချိန် ၁ စက္ကန့်အတွင်း ထုတ်လွှတ်သည့်စွမ်းအင်ပမာဏကို ဖြာထွက် ပြင်းအားဟုခေါ်သည်။"}]]}'::jsonb,6,true),
(10,'definitions','Blackbody spectrum အနက်ထည်ရောင်စဉ်','11','{"title":"Blackbody spectrum အနက်ထည်ရောင်စဉ်","paragraphs":[[{"text":" The graph drawn with the intensity of the blackbody radiation against the wavelength at a given temperature is called the blackbody spectrum. "}],[{"text":" သတ်မှတ်အပူချိန်တစ်ခုတွင် အနက်ထည်တစ်ခုမှထုတ်လွှတ်သောဖြာထွက်လှိုင်း၏ပြင်းအားကို ၎င်းလှိုင်း၏ လှိုင်း အလျားနှင့် ဆက်စပ်ကာဖော်ပြသည့် ဂရပ်ကို blackbody spectrum ဟုခေါ်သည်။"}]]}'::jsonb,7,true),
(10,'definitions','Wien''s Law','11','{"title":"Wien''s Law","paragraphs":[[{"text":" The wavelength at which maximum intensity occurs (max) is inversely proportional to the absolute temperature of the blackbody."}],[{"text":" "},{"math":true,"tex":"λ_{ max}","plain":"λ max"},{"text":" "},{"math":true,"tex":"\\propto ","plain":"∝"},{"text":" "},{"math":true,"tex":" \\frac{1}{T}","plain":" (1)/(T)"}],[{"text":" max = the wavelength at which maximum intensity occurs, "}],[{"text":"  T = the absolute temperature of the blackbody "}],[{"text":" အနက်ထည်ဖြာထွက်မှု ပြင်းအားအများဆုံးကိုဖြစ်စေသော လှိုင်းအလျားသည် ၎င်း၏ပကတိအပူချိန်နှင့် ပြောင်း ပြန်အချိုးကျသည်။"}]]}'::jsonb,8,true),
(10,'definitions','Stefan Boltzmann''s Law','11','{"title":"Stefan Boltzmann''s Law","paragraphs":[[{"text":" The total emissive power of a blackbody (0) is directly proportional to the fourth power of the absolute temperature. "}],[{"text":"  0 "},{"math":true,"tex":"\\propto ","plain":"∝"},{"text":" T4"}],[{"text":"  0 = T4"}],[{"text":"   = Stefan''s constant = 5.685 "},{"math":true,"tex":"\\times  10^{-8}","plain":"× 10⁻⁸"},{"text":" W m-2 K4"}],[{"text":"  0 = the total emissive power of a blackbody, "}],[{"text":"  T = the absolute temperature of the blackbody "}],[{"text":" အနက်ထည်တစ်ခု၏ စုစုပေါင်းထုတ်လွှတ်မှုစွမ်းအားသည် ၎င်း၏ပကတိအပူချိန် ၄ ထပ်နှင့် တိုက်ရိုက်အချိုးကျ သည်။"}]]}'::jsonb,9,true),
(10,'definitions','Photons ဖိုတွန်','11','{"title":"Photons ဖိုတွန်","paragraphs":[[{"text":" Photons are particles which carry energy. They are chargeless, massless and travel with the speed of light c."}],[{"text":" ဖိုတွန်သည် လျှပ်စစ်ဓာတ် မရှိ ဒြပ်ထုမရှိ အလင်းအလျင်နှင့်သွားနိုင်သည့် စွမ်းအင်သယ်ဆောင်မှုန်ဖြစ်သည်။"}]]}'::jsonb,10,true),
(10,'definitions','Thomson''s atomic model','11','{"title":"Thomson''s atomic model","paragraphs":[[{"text":" Thomson''s suggested that an atom might be a spherical volume of positive charge with electrons embedded inside it like currant in a bun (or) plums in a pudding."}],[{"text":" အက်တမ်တစ်လုံးသည် လျှပ်စစ်ဓာတ်မအီလက်ထရွန်များနစ်မြုပ်နေသော အ‌ပေါင်းလျှပ်စစ်သတ္တိရှိသည့်စက်လုံး ထုထည်ဖြစ်ရမည်။ စပျစ်သီးခြောက်များပါသည့်ကွက်ကီး(သို့) ဆီးသီးခြောက်များပါသည့်ပူတင်းကဲ့သို့ဖြစ်မည်။"}]]}'::jsonb,11,true),
(10,'definitions','Rutherford''s atomic model','11','{"title":"Rutherford''s atomic model","paragraphs":[[{"text":" Rutherford concluded that the atom must be largely empty space with all of its positive charges and most of its mass concentrated in a small region. This concentrated volume at the centre of the atom is called the nucleus. Negatively charged electrons are moving around the tiny nucleus."}],[{"text":" အက်တမ်၏အပေါင်းလျှပ်စစ်အားလုံးနှင့် ဒြပ်ထုအများစုသည် အလယ်တွင်ကျစ်လစ်စုစည်းနေရမည်။ ကျန်နေရာ အားလုံးနေရာလွတ်ကြီးဖြစ်နေရမည်။ အက်တမ်၏အလယ်တွင်ကျစ်လစ်စုစည်း‌နေသည့်ထုထည်ကို နျူကလိယ (အက်တမ်ဝတ်ဆံ)ဟုခေါ်ရမည်။ လျှပ်စစ်ဓာတ်မ အီလက်တရွန်များက ၎င်းကိုလှည့်ပတ်နေရမည်။"}]]}'::jsonb,12,true),
(10,'definitions','Bohr''s atomic model','11','{"title":"Bohr''s atomic model","paragraphs":[[{"text":" Electrons move in circular orbits around the nucleus. The electric force between the positively charged proton inside the nucleus and the negatively charged electron holds the electron in orbit."}],[{"text":" However, only certain orbits are allowed in this model. The electron is never found between the allowed orbits. However, it can jump from one orbit to another."}],[{"text":" Bohr assumed that the atom does not emit energy in the form of radiation when the electron is in an allowed orbit."}],[{"text":" အီလက်ထရွန်များက နျူကလိယကိုစက်ဝိုင်းပုံပတ်လမ်းဖြင့် လှည့်ပတ်နေရမည်။ နျူကလိယထဲရှိ လျှပ်စစ်ဓာတ်ဖို ပရိုတွန်များနှင့် လျှပ်စစ်ဓာတ်မအီလက်ထရွန်တို့ကြား လျှပ်စစ်ဆွဲအားက အီလက်ထရွန်တို့ကို ပတ်လမ်းအတိုင်း ရှိနေစေခြင်းဖြစ်သည်။ အီလက်ထရွန်များသည် သတ်မှတ်ခွင့်ပြုထားသောပတ်လမ်းများပေါ်တွင်သာ ရှိကြရမည်။ ပတ်လမ်းများကြားတွင်မရှိရ။ သို့သော် အီလက်ထရွန်သည် ပတ်လမ်းတစ်ခုမှ တစ်ခုသို့ကူးနိုင်သေးသည်။ ခွင့်ပြု ပတ်လမ်းပေါ်တွင်ရှိနေစဉ် ရောင်ခြည်ဖြာခြင်းဖြင့် စွမ်းအင်စွန့်ထုတ်ခြင်းမပြုလုပ်နိုင်။"}]]}'::jsonb,13,true),
(10,'definitions','Atomic number အက်တမ်အမှတ်စဉ်','11','{"title":"Atomic number အက်တမ်အမှတ်စဉ်","paragraphs":[[{"text":" The atomic number of an element tells us how many protons (or) electrons are in an atom of that element. "}],[{"text":" ဒြပ်စင်တစ်ခု၏အက်တမ်အမှတ်စဉ်သည် ထိုဒြပ်စင်၏အက်တမ်တွင်ပါရှိသည့် ပရိုတွန်အရေအတွက်(သို့) အီလက် ထရွန်အရေအတွက်ကို ဖော်ပြသည်။"}]]}'::jsonb,14,true),
(10,'definitions','Mass Number ဒြပ်ထုကိန်း','11','{"title":"Mass Number ဒြပ်ထုကိန်း","paragraphs":[[{"text":" The total number of protons and neutrons in the nucleus of an atom is called the mass number (or) the nucleon number. "}],[{"text":" အက်တမ်တစ်လုံး၏ နျူကလိယထဲရှိ ပရိုတွန်နှင့် နျူထရွန်အရေအတွက်ကို ဒြပ်ထုကိန်း(သို့) နျူကလိယွန်နံပါတ် ဟုခေါ်သည်။"}]]}'::jsonb,15,true),
(10,'definitions','Isotopes','11','{"title":"Isotopes","paragraphs":[[{"text":" Atoms that have the same atomic number but different neutron numbers are called isotopes. "}],[{"text":" နျူကလိယထဲရှိ ပရိုတွန်အရေအတွက်တို့တူညီ(အက်တမ်အမှတ်စဉ်တူညီ)ကြသော်လည်း နျူထရွန်အရေအတွက် (ဒြပ်ထုကိန်း)မတူညီကြသည့် အက်တမ်များကို အိုင်ဆိုတုပ်ဟုခေါ်သည်။"}]]}'::jsonb,16,true),
(10,'definitions','Astronomy နက္ခတ္တဗေဒ','11','{"title":"Astronomy နက္ခတ္တဗေဒ","paragraphs":[[{"text":" Astronomy is a natural science that deals with the study of celestial objects, which are any natural bodies outside of the earth''s atmosphere. "}],[{"text":" Examples of celestial objects are the Moon, the Sun, the planets, the stars, the comets, the nebulae, the star clusters and the galaxies, etc."}],[{"text":" နက္ခတ္တဗေဒသည် ကမ္ဘာ့လေထုအပြင်ဘက်တွင် သဘာဝအလျောက်ဖြစ်တည်နေသော အာကာသပစ္စည်းများကို လေ့လာသည့် သဘာဝသိပ္ပံပညာရပ်တစ်ခုဖြစ်သည်။ လ၊ နေ၊ ဂြိုဟ်များ၊ ကြယ်များ၊ ကြယ်တံခွန်များ၊ အာကာသ တိမ်တိုက်ကြီးများ၊ ကြယ်စုများနှင့် ဂလက်ဆီများကိုလေ့လာသည်။"}]]}'::jsonb,17,true),
(10,'definitions','Astrophysics နက္ခတ္တ ရူပဗေဒ','11','{"title":"Astrophysics နက္ခတ္တ ရူပဗေဒ","paragraphs":[[{"text":" Astrophysics is the branch of astronomy that deals with the physics of the universe, including the physical properties of the celestial objects, as well as their interactions and behavior. "}],[{"text":" Among the objects studied are the galaxies, the stars, the planets, the exoplanets, the interstellar medium and the cosmic microwave background."}],[{"text":" နက္ခတ္တရူပဗေဒသည် နက္ခတ္တဗေဒ၏ဘာသာရပ်ခွဲတစ်ခုဖြစ်သည်။ အာကာသပစ္စည်းများ၏ အပြုအမှုနှင့် အပြန်အ လှန်သက်ရောက်မှုစသည့် ရုပ်ဂုဏ်သတ္တိလေ့လာခြင်းများပါဝင်သော စကြဝဠာဆိုင်ရာ ရူပဗေဒနယ်ပယ်ဖြစ်သည်။ ဂလက်ဆီများ၊ ကြယ်များ၊ ဂြိုဟ်များ၊ နေအဖွဲ့အစည်းပြင်ပဂြိုဟ်များ၊ ကြယ်များကြား-ကြားခံနယ်၊ အာကာသမိုက် ခရိုလှိုင်းနောက်ခံဖြာထွက်ခြင်းများကို လေ့လာသည်။"}]]}'::jsonb,18,true),
(10,'definitions','Cosmology စကြဝဠာဗေဒ','11','{"title":"Cosmology စကြဝဠာဗေဒ","paragraphs":[[{"text":" Cosmology studies the universe as a whole and its phenomena at largest scales. The difference between Astrophysics and Cosmology is the domain and scale of the study."}],[{"text":" စကြဝဠာဗေဒတွင် စကြဝဠာတစ်ခုလုံးနှင့်ဆိုင်သောဖြစ်ရပ်များကို ကျယ်ပြန့်စွာလေ့လာသည်။ နက္ခတ္တရူပဗေဒနှင့် စကြဝဠာဗေဒတို့သည် လေ့လာသည့်နယ်ပယ်အပိုင်းအခြားနှင့် အတိုင်းအတာတို့တွင်ခြားနားမှုရှိသည်။"}]]}'::jsonb,19,true),
(10,'definitions','Astronomical Unit (AU)','11','{"title":"Astronomical Unit (AU)","paragraphs":[[{"text":" One Astronomical unit (1 AU) is the mean distance between the Earth and the Sun."}],[{"text":" 1 AU = 1.496 × 108 km = 1.496 × 1011 m"}],[{"text":" နေနှင့်ကမ္ဘာကြားအကွာဝေးကို 1 AU ဟုသတ်မှတ်သည်။"}]]}'::jsonb,20,true),
(10,'definitions','Light year (ly) အလင်းနှစ်','11','{"title":"Light year (ly) အလင်းနှစ်","paragraphs":[[{"text":" The light year (ly) is the distance travelled by light in a vacuum in one year."}],[{"text":" တစ်နှစ်အတွင်း လေဟာနယ်ထဲ အလင်းသွားနိုင်သောခရီးအကွာအဝေးကို အလင်းနှစ်ဟုသတ်မှတ်သည်။"}]]}'::jsonb,21,true),
(10,'definitions','One parsec (pc)','11','{"title":"One parsec (pc)","paragraphs":[[{"text":" One parsec (pc) is the distance to a star that subtends an angle of 1 arc sec (arc second) at an arc length of 1 AU. "}],[{"text":" အဝန်းပိုင်းအလျား 1 AU ကို ထောင့် 1 arc sec ခံဆောင်ထားနိုင်လောက်အောင်ဝေးသော ကြယ်တစ်လုံးဆီသို့ အဝန်းပိုင်းမှအကွာအဝေးကို 1 pc ဟုသတ်မှတ်သည်။"}]]}'::jsonb,22,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.1','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><em><strong>Is physics useful in the study of chemistry, biology, and engineering subjects?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp; Yes.</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.1','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.1.</strong><strong> &nbsp; </strong><em><strong>Explain each of the following terms in your own words:</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; physical quantity, basic unit and derived unit.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; <strong>Physical quantity</strong> </p><p> &nbsp;  &nbsp; A physical quantity is the quantity that can be measured, and consists of a numerical magnitude and a unit.</p><p> &nbsp;  &nbsp; Q = N u, &nbsp; Where, Q = physical quantity, N = a dimensionless number, u = unit.</p><p> &nbsp;  &nbsp; <strong>Basic unit</strong></p><p> &nbsp;  &nbsp; A basic unit is a unit of basic type physical quantities such as length, mass, time, temperature, electric current, amount of substance, luminous intensity.</p><p> &nbsp;  &nbsp; <strong>Derived unit</strong></p><p> &nbsp;  &nbsp; A derived unit is a unit of measurement formed by combining the basic (or base) units of a system.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','No.2','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><em><strong>Determine the derived units of: </strong></em></p><p><em><strong> &nbsp; (a) speed (= distance/ time) </strong></em></p><p><em><strong> &nbsp; (b) volume (= length </strong></em>\\(×\\)<em><strong> width </strong></em>\\(×\\)<em><strong> height) </strong></em></p><p><em><strong> &nbsp; (c) density (= mass/ volume)</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; (a) &nbsp; speed = \\(\\frac{distance}{time}\\)</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>unit &nbsp; \\(⟹\\) &nbsp; speed = \\(\\frac{m}{s}\\) = m s<sup>-1</sup> (metre per second)</p><p> &nbsp;  &nbsp; (b) &nbsp; volume = length × width × height</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>unit &nbsp; \\(⟹\\) &nbsp; volume = m × m × m = m<sup>3</sup> (cubic metre)</p><p> &nbsp;  &nbsp; (c) &nbsp; density = \\(\\frac{mass}{volume}\\)</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>unit &nbsp; \\(⟹\\) &nbsp; density = \\(\\frac{kg}{{m}^{3}}\\) = kg m<sup>-3</sup> (kilogram per cubic metre)</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Rev.4','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong>Write the following numbers in scientific notation. (a) 320 000 (b) 0.000 075.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; (a) 320 000 = <strong>3.2 </strong>\\(× {10}^{5}\\)<strong> &nbsp; </strong>(b) 0.000 075 = <strong>7.5 </strong>\\(× {10}^{- 5}\\)</p></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Rev.2','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong>Write down the value of (a) 1 564 mm in m, and (ii) l 750 g in kg.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; (a) 1 564 mm = 1 564 \\(×{10}^{-3}\\) m = 1.564 \\(×{10}^{3}\\) \\(×{10}^{-3}\\) m = <strong>1.564 m</strong></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(b) 1 750 g = 1 750 \\(×{10}^{-3}\\) kg = 1.750 \\(×{10}^{3}\\) \\(×{10}^{-3}\\) kg = <strong>1.750 kg</strong></p></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Rev.3','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong>In each of the following pairs, which quantity is larger?</p><p> &nbsp;  &nbsp; (a) 2 km (or) 2500 m, &nbsp; (b) 2 m (or) 1500 mm, &nbsp;  &nbsp; (c) 2000 g (or) 3 kg</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; (a) 2 km (or) 2500 m</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>2 km = 2 \\(×{10}^{3}\\) m = <strong>2000 m</strong> &nbsp;  &nbsp;  &nbsp; \\(∴\\) 2500 m is larger.</p><p> &nbsp; <strong> &nbsp; </strong>(b) 2 m (or) 1500 mm</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>1500 mm = 1500 \\(×{10}^{-3}\\) m = <strong>1.5 m</strong><strong> &nbsp; </strong> &nbsp; \\(∴\\) 2 m is larger.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(c) 2000 g (or) 3 kg</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>3 kg = 3 \\(×{10}^{3}\\) g = <strong>3000 g</strong> &nbsp;  &nbsp;  &nbsp; \\(∴\\) 3 kg is larger.</p></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.5','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No. 5.</strong><strong> &nbsp; </strong>Write down in powers of ten of the values of the following: </p><p> &nbsp;  &nbsp; (a) 60 nF  &nbsp;  &nbsp; (b) 500 MW  &nbsp;  &nbsp; (c) 20 000 mm  &nbsp; (d) 400 C.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; (a) 60 nF = 6 \\(×10\\) nF = 6 \\(×10×{10}^{-9}\\) F = <strong>6 </strong>\\(×{10}^{-8}\\)<strong> F</strong></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(b) 500 MW = 5 \\(×1{0}^{2}\\) MW = 5 \\(×1{0}^{2}×{10}^{6}\\) W = <strong>5 </strong>\\(×{10}^{8}\\)<strong> W</strong></p><p> &nbsp;  &nbsp; (c) 20 000 mm = 2 \\(×1{0}^{4}\\) mm = 2 \\(×1{0}^{4}×{10}^{-3}\\) m = <strong>2 </strong>\\(×\\)<strong>10 m</strong></p><p> &nbsp;  &nbsp; (d) 400 C = 4 \\(×1{0}^{2}\\) C = 4 \\(×1{0}^{2}×{10}^{-6}\\) C = <strong>4 </strong>\\(×{10}^{-4}\\)<strong> C</strong></p></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.8','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The sun is a medium-sized star. In the Milky Way galaxy which includes the sun, there are one hundred billion stars. Write down this figure in the standard form. </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(1 billion = 10<sup>9</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; one hundred billion stars = 100 billion = 10<sup>2</sup>  10<sup>9</sup> = <strong>10</strong><strong><sup>11</sup></strong><strong> stars</strong></p></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.4','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No</strong><strong>.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Find the area of one page of a book whose dimensions are 20 cm × 25 cm in cm<sup>2</sup> and then convert this value to m<sup>2</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong> &nbsp; area of one page = 20 cm \\(×\\) 25 cm </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>= 20 \\(×{10}^{-2}\\)m \\(×25×{10}^{-2}\\)m</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>= 500 \\(×{10}^{-4}\\) m<sup>2</sup> = 5 \\(×{10}^{2}\\) \\(×{10}^{-4}\\) m<sup>2</sup> = <strong>5 </strong>\\(×{10}^{-2}\\)<strong> m</strong><strong><sup>2</sup></strong></p></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.6','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The thickness of a ream of printing paper is 5.2 cm. It contains 500 sheets of paper. What is the average thickness of one sheet of paper? Express your answer in SI unit. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Thickness of a ream of printing paper = 5.2 cm</p><p>Number of sheets = 500</p></td></tr><tr><td></td><td><p>Average thickness of one sheet of paper</p></td><td><p>=</p></td><td><p>\\(\\frac{Thickness of a ream}{Number of sheets}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{5.2 cm}{500}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1.04 \\(×{10}^{-2}\\) cm</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1.04 \\(×{10}^{-2}× {10}^{-2}\\) m</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>1.04 </strong>\\(×{10}^{-4}\\)<strong> m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.7','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The mass of 1 litre of water is 1 kg. Find the mass of 350 mL purified drinking water in a small sized bottle.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 L = 1 kg</p></td></tr><tr><td></td><td><p>Mass of 350 mL</p></td><td><p>=</p></td><td><p>350 \\(×{10}^{-3}\\) L \\(×\\frac{1 kg}{1 L}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>350 \\(×{10}^{-3}\\)kg</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong></strong> <strong>3.5 </strong>\\(×{10}^{-1}\\)<strong>kg</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.9','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The tissue of a cell is 70 Å thick. (Å = angstrom unit). If 1 Å = 10<sup>-10</sup>m, find the thickness of the tissue in terms of an inch. (1 m = 39.4 in)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 Å = 10<sup>-10</sup>m, &nbsp;  &nbsp; 1 m = 39.4 in</p></td></tr><tr><td></td><td><p>thickness of the tissue</p></td><td><p>=</p></td><td><p>70 Å</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>70 \\(×\\) 10<sup>-10</sup> m</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong></strong>70 \\(×\\) 10<sup>-10</sup> m \\(×\\frac{39.4 in}{1 m}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>2.758 </strong>\\(×\\)<strong> 10</strong><strong><sup>-7</sup></strong><strong> in</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.11','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong>One acre is equal to 43 560 ft<sup>2</sup>. How much is it in m<sup>2</sup>? [1 ft = 0.305 m]</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 ft = 0.305 m</p></td></tr><tr><td></td><td><p>Area 1 acre</p></td><td><p>=</p></td><td><p>43 560 ft<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong></strong>43 560 ft<sup>2</sup> \\(×\\frac{(0.305 m{)}^{2}}{{1 ft}^{2}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>4.052 </strong>\\(× {10}^{3}\\)<strong> m</strong><strong><sup>2</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.12','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong>One litre is equivalent to 1000 cm<sup>3</sup>. How many litres are there in 231 in<sup>3</sup>? </p><p> &nbsp;  &nbsp; [ 1 in= 2.54 cm]</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 L = 1000 cm<sup>3</sup>, &nbsp; 1 in= 2.54 cm</p></td></tr><tr><td></td><td><p>Volume</p></td><td><p>=</p></td><td><p>231 in<sup>3</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong></strong>231 in<sup>3</sup> \\(×\\frac{(2.54 cm{)}^{3}}{1 {in}^{3}}×\\frac{1 L}{1000 {cm}^{3}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{3.784 ×{10}^{3} L}{1000}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>3.784 L</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','Rev.5','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong>If the density of ice is 920 kg m<sup>-3</sup>, convert this value to g cm<sup>-3</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 kg = 10<sup>3</sup> g, &nbsp; 1 cm= 10<sup>-2</sup> m</p></td></tr><tr><td></td><td><p>Density</p></td><td><p>=</p></td><td><p>920 kg m<sup>-3</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>920 kg m<sup>-3</sup> \\(×\\frac{{10}^{3} g}{1 kg}×\\frac{{(10}^{-2} m{)}^{3}}{1 {cm}^{3}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{920 ×{10}^{3} ×{10}^{-6} g}{1 {cm}^{3}}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>920 </strong>\\(×{10}^{-3} g\\)<strong> cm</strong><strong><sup>-3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.3','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No. 3.</strong><strong> &nbsp; </strong>The density of water is 1.0 g cm<sup>-3</sup>. Convert this value to SI units.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 kg = 10<sup>3</sup> g, &nbsp; 1 cm = 10<sup>-2</sup> m</p></td></tr><tr><td></td><td><p>Density</p></td><td><p>=</p></td><td><p>1 g cm<sup>-3</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1 g cm<sup>-3</sup> \\(×\\frac{1 kg}{{10}^{3} g}×\\frac{1 {cm}^{3}}{{(10}^{-2} m{)}^{3}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{1 kg}{{10}^{3} ×{10}^{-6} {m}^{3}}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1 \\(×{10}^{3}\\) kg m<sup>-3</sup> = <strong>1 000 kg m</strong><strong><sup>-3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','No.10','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong>The size of an elementary particles (which are also called the smallest particles) is of the order of ~ 10<sup>-15</sup> m and the size of the universe is of the order of ~ 10<sup>26</sup> m. Determine the <strong>ratio</strong> of the size of the universe <strong>to</strong> the size of an elementary particle.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>size of an elementary particles = 10<sup>-15</sup> m,</p><p>size of the universe = 10<sup>26</sup> m</p></td></tr><tr><td></td><td><p>ratio</p></td><td><p>=</p></td><td><p>\\(\\frac{size of the universe}{size of an elementary particles}\\)<strong> = </strong>\\(\\frac{{10}^{26}}{{10}^{-15}}\\)<strong> = </strong><strong>10</strong><strong><sup>41</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','No.13','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13.</strong><strong> &nbsp; </strong>The shortest life-time of an elementary particle is 10<sup>-23</sup> s and the age of the universe is 10<sup>18</sup> s. Find the ratio of the two time intervals.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>shortest life-time of an elementary particle = 10<sup>-</sup><sup>23</sup> s</p><p>age of the universe = 10<sup>18</sup> m</p></td></tr><tr><td></td><td><p>ratio</p></td><td><p>=</p></td><td><p>\\(\\frac{age of the universe}{shortest life-time of an elementary particle}\\)<strong> = </strong>\\(\\frac{{10}^{18}}{{10}^{-23}}\\)<strong> = </strong><strong>10</strong><strong><sup>41</sup></strong></p></td></tr><tr><td><p><strong>[OR]</strong></p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>ratio</p></td><td><p>=</p></td><td><p>\\(\\frac{shortest life-time of an elementary particle}{age of the universe}\\)<strong> = </strong>\\(\\frac{{10}^{-23}}{{10}^{18}}\\)<strong> = </strong><strong>10</strong><strong><sup>-41</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.14','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14.</strong><strong> &nbsp; </strong>If the width of the Milky Way galaxy (which includes our solar system) is 10<sup>5</sup> <em>ly</em>, how long will a light signal take to travel that width?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 light year (distance) = 1 year (time taken)</p></td></tr><tr><td></td><td><p>width of the Milky Way galaxy</p></td><td><p>=</p></td><td><p>10<sup>5</sup> <em>ly</em></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>10<sup>5</sup> <em>ly</em> \\(×\\frac{1 year}{1 ly}\\) = <strong>10</strong><strong><sup>5</sup></strong><strong> years</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','No.15','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15.</strong><strong> &nbsp; </strong>According to observations and measurements the farthest galaxies are at a distance of 10<sup>26</sup> m from the earth. When space travel becomes highly advanced, do you think that man will be able to visit those galaxies? (Light travels 3 \\(×\\) 10<sup>8</sup> m in one second and there are approximately 10<sup>8</sup> s in a year.)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Light travels 3 \\(×\\) 10<sup>8</sup> m = 1 s, &nbsp;  &nbsp; 1 year = 10<sup>8</sup> s</p></td></tr><tr><td></td><td><p>Distance </p></td><td><p>=</p></td><td><p>10<sup>26</sup> m</p></td></tr><tr><td></td><td><p>Time taken </p></td><td><p>=</p></td><td><p>10<sup>26</sup> m \\(×\\frac{1 s}{3 × {10}^{8} m}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.333 \\(×{10}^{18}\\) s</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.333 \\(×{10}^{18}\\) s \\(×\\frac{1 year}{{10}^{8} s}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.333 \\(×{10}^{10}\\) years (or) <strong>3.33 </strong>\\(×{10}^{9}\\)<strong> years</strong></p></td></tr><tr><td></td><td><p>Age of man</p></td><td><p>\\(~\\)</p></td><td><p>100 years = <strong>10</strong><strong><sup>2</sup></strong><strong> years</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Since age of man is very less than the time take to reach galaxies, man will not be able to visit those galaxies.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','No.16','1','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16.</strong><strong> &nbsp; </strong>The mass of an electron is m<sub>e</sub> = 9.1 × 10<sup>-28</sup> g. The mass of a muon is about 207 m<sub>e</sub> and the mass of a proton is about 1 836 m<sub>e</sub>. Find the masses of muon and proton in kg. (Electron, muon and proton are the fundamental particles which are smaller than an atom.) </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>mass of an electron, m<sub>e</sub></p></td><td><p>=</p></td><td><p>9.1 \\(×\\) 10<sup>-28</sup> g</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>9.1 \\(×\\) 10<sup>-28</sup> g \\(×\\frac{1 kg}{{10}^{3}g}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>9.1 </strong>\\(×\\)<strong> 10</strong><strong><sup>-31</sup></strong><strong> kg</strong></p></td></tr><tr><td></td><td><p>mass of a muon</p></td><td><p>=</p></td><td><p>207 m<sub>e</sub></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>207 \\(×\\) 9.1 \\(×\\) 10<sup>-31</sup> kg</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>1.884 </strong>\\(×\\)<strong> 10</strong><strong><sup>-28</sup></strong><strong> kg</strong></p></td></tr><tr><td></td><td><p>mass of a proton</p></td><td><p>=</p></td><td><p>1 836 m<sub>e</sub></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1 836 \\(×\\) 9.1 \\(×\\) 10<sup>-31</sup> kg</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>1.6707 </strong>\\(×\\)<strong> 10</strong><strong><sup>-27</sup></strong><strong> kg</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','Rev.1','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.1.</strong><strong> &nbsp; </strong>Given that \\(\\vec{A}\\) = 2 units (west) and \\(\\vec{B}\\) = 4 units (south), draw vector diagrams to carry out the following vector operations. (i) \\(\\vec{A}\\) + \\(\\vec{B}\\) &nbsp; (ii) 2 \\(\\vec{A}\\) + \\(\\vec{B}\\) &nbsp; (iii) \\(\\vec{B}\\) - \\(\\vec{A}\\).</p><p><strong>Ans;</strong> &nbsp; \\(\\vec{A}\\) = 2 units (west), &nbsp; \\(\\vec{B}\\) = 4 units (south)</p><p>(i) \\(\\vec{A}\\) + \\(\\vec{B}\\) &nbsp; (ii) 2 \\(\\vec{A}\\) + \\(\\vec{B}\\) &nbsp; (iii) \\(\\vec{B}\\) - \\(\\vec{A}\\) = \\(\\vec{B}\\) + (- \\(\\vec{A}\\) )</p></div></div></article>"}'::jsonb,1,true),
(10,'calculations','No.2','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Given that \\(\\vec{A}\\) = 3 units (east) and \\(\\vec{B}\\) = 4 units (north), draw vector diagrams to carry out the following vector operations.</p><p> &nbsp;  &nbsp; (i) \\(\\vec{A}\\) + \\(\\vec{B}\\)    &nbsp;  &nbsp; (ii) 2 \\(\\vec{A}\\) + \\(\\vec{B}\\)     &nbsp;  &nbsp; (iii) \\(\\vec{A}\\) - \\(\\vec{B}\\)     &nbsp;   &nbsp; (iv) \\(\\vec{B}\\) - \\(\\vec{A}\\)  .</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>\\(\\vec{A}\\) = 3 units (east), &nbsp; \\(\\vec{B}\\) = 4 units (north)</p><p> &nbsp;  &nbsp; (i) \\(\\vec{A}\\) + \\(\\vec{B}\\) &nbsp; (ii) 2 \\(\\vec{A}\\) + \\(\\vec{B}\\)</p><p> &nbsp; (ii) \\(\\vec{A}\\) - \\(\\vec{B}\\) = \\(\\vec{A}\\) + (- \\(\\vec{B}\\) ) &nbsp; (iv) \\(\\vec{B}\\) - \\(\\vec{A}\\)  =  \\(\\vec{B}\\) + (- \\(\\vec{A}\\) )</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','No.3','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong> &nbsp;  &nbsp; A force 3 N pointing east and a force 6 N pointing north act on a particle. Find the magnitude of the resultant force. Check your answer by drawing a vector diagram.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\(\\vec{{F}_{1}}\\) = 3 N (east), &nbsp; \\(\\vec{{F}_{2}}\\) = 6 N (north)</p></td></tr><tr><td></td><td colspan=\"3\"><p>The magnitude of resultant force,</p></td></tr><tr><td></td><td><p>F<sup>2</sup></p></td><td><p><strong>=</strong></p></td><td><p>\\({F}_{1}^{2}\\) + \\({F}_{2}^{2}\\)</p></td></tr><tr><td></td><td><p>F</p></td><td><p><strong>=</strong></p></td><td><p>\\(\\sqrt{{F}_{1}^{2} + {F}_{2}^{2}}\\) </p></td></tr><tr><td></td><td><p>F</p></td><td><p><strong>=</strong></p></td><td><p>\\(\\sqrt{{3}^{2}+ {6}^{2}}\\) </p></td></tr><tr><td></td><td><p>F</p></td><td><p><strong>=</strong></p></td><td><p>\\(\\sqrt{45}\\) = <strong>6.708 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Rev.2','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.2.</strong><strong> &nbsp; </strong>A force 4 N, directed east, and a force 6 N, directed west, act on a particle. Find the magnitude of the resultant force.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>\\(\\vec{{F}_{1}}\\) = 4 N (east), &nbsp; \\(\\vec{{F}_{2}}\\) = 6 N (west)</p><p> &nbsp; The resultant force, \\(\\vec{F}\\) = \\(\\vec{{F}_{1}}\\) + \\(\\vec{{F}_{2}}\\)</p><p> &nbsp; Magnitude of resultant force, F = F<sub>2</sub> – F<sub>1</sub> = 6 - 4 = <strong>2 N</strong> (ဦးတည်ချက်ဆန့်ကျင်ဘက် နုတ်)</p></div></details></div></article>"}'::jsonb,4,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','Eg.1','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A boat travels east at 10 mi h<sup>-1</sup> in a river that flows south at 3 mi h<sup>-1</sup>. Find the boat’s velocity relative to the river bank (the earth).</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\({v}_{boat}\\) = 10 mi h<sup>-1</sup>, &nbsp; \\({v}_{river}\\) = 3 mi h<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"3\"><p>the magnitude of \\(\\vec{v}\\)</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{boat}^{2}\\) + \\({v}_{river}^{2}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p><strong>=</strong></p></td><td><p>\\(\\sqrt{{v}_{boat}^{2} + {v}_{river}^{2}}\\) </p></td></tr><tr><td></td><td><p>v</p></td><td><p><strong>=</strong></p></td><td><p>\\(\\sqrt{{10}^{2}+ {3}^{2}}\\) = \\(\\sqrt{109}\\) =<strong>10.44 mi h</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>the direction of \\(\\vec{v}\\)</p></td></tr><tr><td></td><td><p>\\(θ\\) </p></td><td><p><strong>=</strong></p></td><td><p>tan<sup>-1</sup> \\(\\frac{{v}_{river}}{{v}_{boat}}\\) = tan<sup>-1</sup> \\(\\frac{3}{10}\\) = tan<sup>-1</sup> 0.3 = <strong>16</strong>\\(°\\)<strong> </strong>\\(42''\\)</p></td></tr><tr><td></td><td colspan=\"3\"><p>The boat’s velocity relative to the river bank = 10.4 mi h<sup>-1</sup></p><p>The direction = east 17\\(°\\) south (17\\(°\\) south of east)</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Eg.2','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A force of magnitude 5 N is inclined at an angle of 37 to the horizontal. Find its horizontal and vertical components. (sin 37 = 0.6, cos 37 = 0.8)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>F = 5 N, &nbsp; \\(θ\\) = 37</p></td></tr><tr><td></td><td><p>Horizontal component</p></td></tr><tr><td></td><td><p>F<sub>x</sub> = F cos \\(θ\\) = 5 cos 37 = 5 \\(×\\) 0.8 = <strong>4 N</strong></p></td></tr><tr><td></td><td><p>Vertical component</p></td></tr><tr><td></td><td><p>F<sub>y</sub> = F sin \\(θ\\) = 5 sin 37 = 5 \\(×\\) 0.6 = <strong>3 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.4','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A vector of magnitude 5 units is inclined at an angle 37 to the x-axis and another vector of magnitude 10 units is inclined at 53 to the x-axis. What is the magnitude of the sum of the vector components (i) along the x-axis, (ii) along the y-axis? </p><p> &nbsp;  &nbsp; (sin 37 = cos 53 = 0.6,   sin 53 = cos 37 = 0.8)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>A = 5 units, &nbsp; \\(θ\\) = 37, &nbsp;  &nbsp;  &nbsp; B = 10 units, &nbsp; \\(β\\) = 53</p></td></tr><tr><td></td><td colspan=\"3\"></td></tr><tr><td></td><td><p>A<sub>x</sub></p></td><td><p><strong>=</strong></p></td><td><p>A cos \\(θ\\) = 5 cos 37 = 5 \\(×\\) 0.8 = <strong>4 units</strong></p></td></tr><tr><td></td><td><p>A<sub>y</sub></p></td><td><p><strong>=</strong></p></td><td><p>A sin \\(θ\\) = 5 sin 37 = 5 \\(×\\) 0.6 = <strong>3 units</strong></p></td></tr><tr><td></td><td><p>B<sub>x</sub></p></td><td><p><strong>=</strong></p></td><td><p>B cos \\(β\\) = 10 cos 53 = 10 \\(×\\) 0.6 = <strong>6 units</strong></p></td></tr><tr><td></td><td><p>B<sub>y</sub></p></td><td><p><strong>=</strong></p></td><td><p>B sin \\(β\\) = 10 sin 53 = 10 \\(×\\) 0.8 = <strong>8 units</strong></p></td></tr><tr><td><p>(i)</p></td><td colspan=\"3\"><p>the sum of the vector components along the x-axis = A<sub>x</sub> + B<sub>x</sub> = 4 + 6 = <strong>10 units</strong></p></td></tr><tr><td><p>(ii)</p></td><td colspan=\"3\"><p>the sum of the vector components along the y-axis = A<sub>y</sub> + B<sub>y</sub> = 3 + 8 = <strong>11 units</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','Rev.3','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.3.</strong><strong> &nbsp; </strong><em><strong>Define average velocity and instantaneous velocity.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The average velocity is the ratio of the total displacement \\(\\vec{s}\\) to the time taken t.</p><p> &nbsp;  &nbsp; average velocity, \\({\\vec{v}}_{av}\\) =  \\(\\frac{\\vec{s}}{t}\\)  &nbsp;  &nbsp; (or) &nbsp; \\(\\bar{\\vec{v}}\\) =  \\(\\frac{\\vec{s}}{t}\\)</p><p> &nbsp;  &nbsp; The instantaneous velocity is defined as the time rate of change of displacement.</p><p> &nbsp;  &nbsp; \\(\\vec{v}\\) = \\(\\frac{lim}{∆t →0}   \\frac{∆ \\vec{s} }{∆ t }\\) = \\(\\frac{d\\vec{s}}{dt}\\)</p></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','Rev.4','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.4.</strong><strong> &nbsp; </strong><em><strong>Define speed and velocity such that the two may be distinguished.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The instantaneous speed is defined as the time rate of change of distance. Speed is a  &nbsp; scalar quantity.</p><p> &nbsp; The instantaneous velocity is defined as the time rate of change of displacement.  &nbsp; Velocity is a vector quantity.</p></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.1','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following quantities are scalars and which are vectors?</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (a) Speed, (b) velocity, (c) average velocity, (d) acceleration, (e) displacement. </strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) speed = scalar</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(b) velocity = vector</p><p> &nbsp;  &nbsp; (c) average velocity = vector</p><p> &nbsp;  &nbsp; (d) acceleration = vector</p><p> &nbsp;  &nbsp; (e) displacement = vector</p></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','Eg.3','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) A body travels from A to B along a straight line and another body travels from A to B along a curve (shown by the dotted line). If the straight-line distance between A and B is 3 km, find the displacement of each body.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(b) The first body moves along the straight line from B back to A. The second body moves along the curved-path back to the same starting point A. What are the displacements of two bodies now? If the first body takes 2 h to travel from A to B, what will be its velocity?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans: </strong>(a)<strong> &nbsp; </strong>For both bodies, starting point is A and end point is B. displacement of the two bodies are the same.</p><p><strong> &nbsp; </strong>Displacement of first body = displacement of second body = 3 km</p><p> &nbsp; (b) &nbsp; When both bodies get back to A, for both bodies, starting point is A and end point is also A. (စမှတ် ဆုံးမှတ် တူ)</p><p><strong> &nbsp; </strong>Displacement of first body = displacement of second body = 0</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>For first body, &nbsp; s = 3 km, &nbsp; t = 2 h </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>v<sub>av</sub> = \\(\\frac{s}{t}\\) = \\(\\frac{3 km}{2 h}\\) = 1.5 km h<sup>-1</sup> </p><p> &nbsp;  &nbsp;  &nbsp; = \\(\\frac{1.5 km}{ h}\\) = \\(\\frac{1.5 × {10}^{3}m}{ 3600 s}\\) = \\(\\frac{1500 m}{ 3600 s}\\) = <strong>0.42 m s</strong><strong><sup>-1</sup></strong></p></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.5','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>A person goes from his house to a nearby shop at the corner of the street and returns home. Can you say that the distance travelled by him is equal to the magnitude of his displacement? Explain.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>No, his distance travelled is not equal to the magnitude of his displacement. His distance travelled is twice the distance between his house and the shop. But his displacement is zero since starting point and end points are the same.</p></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.6','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>In a one-round-about-town walking race the starting point is the same as the finishing point. Whose magnitude of displacement is greater: the one who completes the race (or) the one who gives up half-way?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The magnitude of displacement of the one who gives up half-way is greater.</p></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.8','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>In a 400 m race, the person running in the innermost lane clocked 50 s and won the gold medal. Find his average velocity. Is the magnitude of the average velocity the same as the value of the average speed? (Hint: For the innermost lane, the starting point is the same as the finishing point.)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>total displacement, \\(\\vec{s}\\) = 0, &nbsp;  &nbsp; t = 50 s</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>Average velocity, \\({\\vec{v}}_{av}\\) = \\(\\frac{\\vec{s}}{t}\\) = \\(\\frac{0}{50}\\) = <strong>0</strong></p><p> &nbsp;  &nbsp; total distance, s = 400 m, &nbsp;  &nbsp; t = 50 s</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>Average speed, \\({v}_{av}\\) = \\(\\frac{s}{t}\\) = \\(\\frac{400}{50}\\) = <strong>8 m s</strong><strong><sup>-1</sup></strong></p><p> &nbsp;  &nbsp; So, the magnitude of the average velocity is not the same as the value of average speed.</p></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.9','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A man walks 3 miles east and then 3 miles north. Draw a vector diagram to show his resultant displacement from his starting point. If he takes 2 hours to complete his journey, find his average speed and average velocity. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>time taken, t = 2 h</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>total distance, s = 3 + 3 = 6 mi</p><p> &nbsp;  &nbsp; total displacement, \\(\\vec{s}\\)  = \\(\\sqrt{{3}^{2}+{3}^{2}}\\) = \\(\\sqrt{18}\\) = <strong>4.24 mi</strong></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>average speed, v<sub>av</sub> = \\(\\frac{s}{t}\\) = \\(\\frac{6 mi}{2 h}\\) = 3 mi h<sup>-1</sup></p><p> &nbsp;  &nbsp; magnitude of average velocity, \\({\\vec{v}}_{av}\\) = \\(\\frac{\\vec{s}}{t}\\) = \\(\\frac{4.24 mi}{2 h}\\) = <strong>2.12 mi h</strong><strong><sup>-1</sup></strong></p><p> &nbsp;  &nbsp; direction of average velocity, \\(θ\\) = tan<sup>-1</sup> \\(\\frac{3}{3}\\) = tan<sup>-1</sup> 1 = <strong>45</strong>\\(°\\)<strong> (north of east)</strong></p></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.7','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Check whether the following statements are true or not.</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (a) If the speed changes, the velocity is also changes.</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (b) Although speed changes, there is no accelerations.</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (c) If the speed does not change, but the direction changes, there will be </strong></em><em><strong> &nbsp; </strong></em><em><strong>acceleration.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) True &nbsp;  &nbsp; (b) False &nbsp;  &nbsp; (c) True</p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Rev.5','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.5.</strong><strong> &nbsp; </strong><em><strong>Is the formula for average velocity </strong></em>\\(\\bar{v}\\)<em><strong> = </strong></em>\\(\\frac{{v}_{0}+ v}{2}\\)<em><strong> always true?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>No, the formula \\(\\bar{v}\\) = \\(\\frac{{v}_{0}+ v}{2}\\) is not always true. It is true only for motion with constant acceleration.</p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','No.13','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13.</strong><strong> &nbsp; </strong>An object moves with an initial velocity of 5 m s<sup>-1</sup>. After 10 s, its velocity is           10 m s<sup>-1</sup>. If the object moves with constant acceleration in a straight line, find (a) its average velocity, (b) the distance travelled in 10 s, and (c) its acceleration.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>initial velocity, \\({v}_{0}\\) = 5 m s<sup>-1</sup>, &nbsp;  &nbsp; t = 10 s, &nbsp; final velocity, v = 10 m s<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"6\"><p> (a) average velocity, \\(\\bar{v}\\) = ? &nbsp; (b) distance, s = ? &nbsp; (c) acceleration, a = ?</p></td></tr><tr><td><p>(a)</p></td><td><p>\\(\\bar{v}\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{{v}_{0}+ v}{2}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>(c)</p></td><td><p>\\(a\\) </p></td><td><p>= \\(\\frac{v- {v}_{0}}{t}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{5 + 10}{2}\\) = <strong>7.5 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td></td><td><p>= \\(\\frac{10 - 5}{10}\\) = <strong>0.5 m s</strong><strong><sup>-2</sup></strong></p></td></tr><tr><td><p>(b)</p></td><td><p>s</p></td><td><p>=</p></td><td><p>\\(\\bar{v}\\) t</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>7.5 \\(×\\) 10 = <strong>75 m</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.10','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong>A car moving on a straight road with constant acceleration arrives at a certain point after traveling 5 s from the starting point. If the initial velocity is 44 ft s<sup>-1</sup> and the final velocity is 66 ft s<sup>-1</sup>, find the acceleration and average velocity of the car. How far has it travelled during this 5 s?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>\\({v}_{0}\\) = 44 ft s<sup>-1</sup>, &nbsp;  &nbsp; v = 66 ft s<sup>-1</sup> &nbsp; t = 5 s<em>,</em> &nbsp;  &nbsp; <em>a</em> = ? &nbsp; \\(\\bar{v}\\) = ? &nbsp; s = ?</p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>\\(\\frac{v- {v}_{0}}{t}\\) </p></td><td><p>[OR]</p></td><td><p>s</p></td><td><p><strong>= </strong>v<sub>0</sub> t + \\(\\frac{1}{2}\\) <em>a</em> t<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{66 - 44}{5}\\) = \\(\\frac{22}{5}\\) = <strong>4.4 ft s</strong><strong><sup>-2</sup></strong></p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td></td><td><p><strong>= </strong>(44 \\(×\\) 5) + (\\(\\frac{1}{2}\\) \\(×\\) \\(\\frac{22}{5}\\) \\(×\\) 5 \\(×\\) 5)</p></td></tr><tr><td></td><td><p>\\(\\bar{v}\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{{v}_{0}+ v}{2}\\) </p></td><td></td><td></td><td><p><strong>= </strong>220 + 55</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{44 + 66}{2}\\) = \\(\\frac{110}{2}\\) = <strong>55 ft s</strong><strong><sup>-1</sup></strong></p></td><td></td><td></td><td><p><strong>= </strong><strong>275 ft</strong></p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td><p>\\(\\bar{v}\\) t = 55 \\(×\\) 5 = <strong>275 ft</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','No.14','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14.</strong><strong> &nbsp; </strong>A particle with initial velocity of 10 m s<sup>-1</sup> travels in a straight line and stops completely after 12 s. Find the uniform acceleration of the particle. How far has the particle travelled before coming to rest?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\({v}_{0}\\) = 10 m s<sup>-1</sup>, &nbsp;  &nbsp; t = 12 s &nbsp; v = 0 (stop), &nbsp; s = ? &nbsp; <em>a</em> = ?  </p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>= \\(\\frac{v- {v}_{0}}{t}\\) </p></td><td><p>s</p></td><td><p><strong>= </strong>v<sub>0</sub> t + \\(\\frac{1}{2}\\) <em>a</em> t<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{0 - 10}{12}\\) </p></td><td></td><td><p><strong>= </strong>(10 \\(×\\) 12) + (\\(\\frac{1}{2}\\) \\(×\\) \\(\\frac{(-10)}{12}\\) \\(×\\) 12 \\(×\\) 12)</p></td></tr><tr><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= <strong>- 0.833 m s</strong><strong><sup>-2</sup></strong></p></td><td></td><td><p><strong>= </strong>120 – 60</p></td></tr><tr><td></td><td colspan=\"2\"><p>velocity decreases with time.</p></td><td></td><td><p>= <strong>60 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','No.12','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong>A car moving with a speed of 108 km h<sup>-1</sup> (in a straight line) stops in 15 s due to uniform acceleration. Find the value of the acceleration.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Initial velocity, v<sub>0</sub> = 108 km h<sup>-1</sup> =  \\(\\frac{108 km}{h}\\) = \\(\\frac{108 × {10}^{3}m}{3600 s}\\) = <strong>30 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Final velocity, v = 0 (stop), &nbsp; t = 15 s, &nbsp; <em>a</em> = ?</p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>\\(\\frac{v- {v}_{0}}{t}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{0 - 30}{15}\\) = \\(\\frac{- 30}{15}\\) = <strong>- 2 m s</strong><strong><sup>-2</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Acceleration is negative because the velocity decreases with time.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','Eg.4','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A car is travelling with a constant velocity of 6 m s<sup>-1</sup>. The driver applies the brakes as he sees a cow which is at a distance of 24 m from the car. Find the acceleration of the car if it stops just in front of the cow.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 6 m s<sup>-1</sup>, &nbsp;  &nbsp; v = 0 (stop), &nbsp;  &nbsp; s = 24 m, &nbsp; <em>a</em> = ?</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 <em>a</em> s</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>6<sup>2</sup> + (2 \\(×a×\\)24)</p></td></tr><tr><td></td><td><p>- 6<sup>2</sup>  </p></td><td><p>=</p></td><td><p>2 \\(×a×\\)24</p></td></tr><tr><td></td><td><p>\\(a×\\) 48</p></td><td><p>=</p></td><td><p>- 36  </p></td></tr><tr><td></td><td><p>a</p></td><td><p>=</p></td><td><p>\\(\\frac{- 36}{48}\\) = <strong>- 0.75 m s</strong><strong><sup>-2</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Acceleration is negative because the velocity decreases with time.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,22,true),
(10,'calculations','No.17','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.17</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.17.</strong><strong> &nbsp; </strong>A car is travelling with a constant velocity 36 km h<sup>-1</sup>. The driver sees a cow on the road at a distance of 28 m from the current position, and applies the brakes. If the car decelerates at 2 m s<sup>-2</sup>, will the car hit the cow?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 36 km h<sup>-1</sup><sup> </sup>=  \\(\\frac{36 km}{h}\\) = \\(\\frac{36 × {10}^{3}m}{3600 s}\\) = <strong>10 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>v = 0 (stop) &nbsp;  &nbsp; decelerate, a = - 2 m s<sup>-2</sup></p></td></tr><tr><td></td><td colspan=\"3\"><p>distance between the car and the cow = 28 m</p></td></tr><tr><td></td><td colspan=\"3\"><p>stopping distance, s = ?</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 <em>a</em> s</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>10<sup>2</sup> + (2 (-2) s)</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>100 – 4 s</p></td></tr><tr><td></td><td><p>4 s</p></td><td><p>=</p></td><td><p>100</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td><p><strong>25 m</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>stopping distance &lt; distance between the car and the cow</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\(∴\\) the car <strong>will not hit</strong> the cow</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.11','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong>A plane starts from rest, speeds over a (straight line) distance of 450 m with constant acceleration for 15 s, and takes off. What is the acceleration of the plane? Find its take-off velocity in km h<sup>-1</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>\\({v}_{0}\\) = 0 (rest), &nbsp;  &nbsp; t = 15 s, &nbsp; s = 450 m, &nbsp; <em>a</em> = ?, &nbsp; v = ? (km h<sup>-1</sup>)</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) <em>a</em> t<sup>2</sup></p></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0 </sub>+ a t</p></td></tr><tr><td></td><td><p>450</p></td><td><p>=</p></td><td><p>0 + (\\(\\frac{1}{2}×a×\\)15 \\(×\\)15)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td><p>=</p></td><td><p>0 + (4 \\(×\\) 15) = 60 m s<sup>-1</sup></p></td></tr><tr><td></td><td><p>450</p></td><td><p>=</p></td><td><p>\\(\\frac{15 × 15}{2}\\) <em>a</em></p></td><td></td><td><p>=</p></td><td><p>60 m s<sup>-1 </sup>\\(×\\frac{1 km}{{10}^{3} m}×\\frac{3600 s}{1 h}\\)</p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>\\(\\frac{2 × 450}{15 ×15}\\) = <strong>4 m s</strong><strong><sup>-2</sup></strong></p></td><td><p>v</p></td><td><p>=</p></td><td><p><strong>216 km h</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,24,true),
(10,'calculations','Eg.5','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A car starting from rest travels with a uniform acceleration of 2 m s<sup>-2</sup> in the first 6 s. It then travels with a constant velocity for half an hour. Find the distance travelled in the first 6 s as well as the distance travelled in the following half an hour.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>For 1<sup>st</sup> part of motion, (\\(a\\) = constant)</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 0 (rest), &nbsp; <em>a</em> = 2 m s<sup>-2</sup>, &nbsp; t = 6s, &nbsp;  &nbsp; s = ?</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) a t<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0 + \\(\\frac{1}{2}\\) \\(×\\) 2 \\(×\\) 6 \\(×\\) 6 = <strong>36 m</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>velocity at 6 s</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0 </sub>+ a t</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0 + (2 \\(×\\) 6) = <strong>12 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>For 2<sup>nd</sup> part of motion, (v = constant)</p></td></tr><tr><td></td><td colspan=\"3\"><p>v = \\(\\bar{v}\\) = 12 m s<sup>-1</sup>, &nbsp; t = 30 min = 30 \\(×\\) 60 = 1800 s, &nbsp; s = ?</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td><p>\\(\\bar{v}\\) t</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>12 \\(×\\) 1800 = 21 600 m = <strong>21.6 km</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,25,true),
(10,'calculations','Rev.6','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.6.</strong><strong> &nbsp; </strong><em><strong>How can the magnitude o</strong></em><em><strong>f</strong></em><em><strong> displacement be determined from v-t graph?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The magnitude of displacement (distance) can be determined from v-t graph by calculating the area under the graph.</p></div></details></div></article>"}'::jsonb,26,true),
(10,'calculations','Eg.6','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A train starts from station A, with an acceleration of 0.2 m s<sup>-2</sup>, and attains its maximum speed in 1.5 min. After continuing at this speed for 4 min it is uniformly retarded for 45 s before coming to rest in station B. Find by drawing a suitable graph: (a) the distance between A and B in km, (b) the maximum speed in km h<sup>-1</sup>, (c) the average speed in m s<sup>-1</sup>, (d) acceleration during the last stage of motion.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Part I</p></td><td><p>Part II</p></td><td><p>Part III</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 0</p></td><td></td><td></td></tr><tr><td></td><td colspan=\"3\"><p><em>a</em> = 0.2 m s<sup>-</sup><sup>2</sup></p></td><td><p><em>a</em> = 0 (v = constant)</p></td><td><p><em>a</em> = - (uniformly retarded)  </p></td></tr><tr><td></td><td colspan=\"3\"><p>t = 1.5 min</p><p>  = 1.5 \\(×\\) 60 = 90 s</p></td><td><p>t = 4 min </p><p>  = 4 \\(×\\) 60 = 240 s</p></td><td><p>t = 45 s</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td colspan=\"3\"><p>v<sub>0 </sub>+ a t</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td colspan=\"3\"><p>0 + (0.2 \\(×\\) 90) = <strong>18 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"></td></tr><tr><td></td><td colspan=\"5\"><p>(a) distance between A and B in km</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td colspan=\"3\"><p>Area ACDB</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>Area ACF + Area CDEF + Area BED</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>( \\(\\frac{1}{2} ×\\)AF \\(×\\) FC) + (FC \\(×\\) CD) + ( \\(\\frac{1}{2} ×\\)BE \\(×\\) ED)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>( \\(\\frac{1}{2} ×\\)90 \\(×\\) 18) + (18 \\(×\\) 240) + ( \\(\\frac{1}{2} ×\\)45 \\(×\\) 18)</p></td></tr><tr><td></td><td><p>s</p></td><td><p>=</p></td><td colspan=\"3\"><p>810 + 4 320 + 405 = <strong>5 535 m</strong> (or) 5.535 km</p></td></tr><tr><td></td><td colspan=\"5\"><p>(b) the maximum speed in km h<sup>-1</sup>,</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td colspan=\"3\"><p>18 m s<sup>-1 </sup>\\(×\\frac{1 km}{{10}^{3} m}×\\frac{3600 s}{1 h}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p><strong>64.8 km h</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>(c) total distance travelled, s = 5 535 m,</p><p>  &nbsp; total time taken, t = 90 + 240 + 45 = 375 s</p></td></tr><tr><td></td><td><p>\\(\\bar{v}\\) </p></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{s}{t}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{5 535}{375}\\) = <strong>14.76 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>(d) acceleration during the last stage of motion</p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td colspan=\"3\"><p>slope of QR</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{QM}{MR}\\) =  \\(\\frac{0-18}{375-330}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{- 18}{45}\\) = <strong>- 0.4 m s</strong><strong><sup>-2</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>Negative sign indicates that the slope is negative. That is, it is a negative acceleration (or) retardation. </p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,27,true),
(10,'calculations','No.15','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15.</strong><strong> &nbsp; </strong>A body starts from rest and accelerates at 3 m s<sup>-2</sup> for 4 s. Its velocity remains constant at the maximum values so reached for 7 s and finally comes to rest with uniform negative acceleration after another 5 s. Use a graphical method to find each of the following: (a) the distance moved during each stage of motion, (b) the average velocity over the whole period.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Part I</p></td><td><p>Part II</p></td><td><p>Part III</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 0</p></td><td></td><td></td></tr><tr><td></td><td colspan=\"3\"><p><em>a</em> = 3 m s<sup>-</sup><sup>2</sup></p></td><td><p><em>a</em> = 0 (v = constant)</p></td><td><p><em>a</em> = - (negative acceleration)  </p></td></tr><tr><td></td><td colspan=\"3\"><p>t = 4 s</p></td><td><p>t = 7 s</p></td><td><p>t = 5 s</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td colspan=\"3\"><p>v<sub>0 </sub>+ a t</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td colspan=\"3\"><p>0 + (3 \\(×\\) 4) = <strong>12 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"></td></tr><tr><td><p>(a)</p></td><td colspan=\"5\"><p>For pat I</p></td></tr><tr><td></td><td><p>s<sub>1</sub></p></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{1}{2} ×\\)ON \\(×\\) NP</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{1}{2} ×\\)4 \\(×\\) 12 = <strong>24 m</strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>For pat II</p></td></tr><tr><td></td><td><p>s<sub>2</sub></p></td><td><p>=</p></td><td colspan=\"3\"><p>NP \\(×\\) NM</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>12 \\(×\\) 7 = <strong>84 m</strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>For pat III</p></td></tr><tr><td></td><td><p>s<sub>3</sub></p></td><td><p>=</p></td><td colspan=\"3\"><p> \\(\\frac{1}{2} ×\\)MR \\(×\\) MQ</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{1}{2} ×\\)5 \\(×\\) 12 = <strong>30 m</strong></p></td></tr><tr><td><p>(b)</p></td><td colspan=\"5\"><p>the average velocity, \\(\\bar{v}\\) = ?</p><p>Total displacement, s = s<sub>1</sub> + s<sub>2</sub> + s<sub>3</sub> = 24 + 84 + 30 = <strong>138 m</strong> </p><p>Total time taken, t = 4 + 7 + 5 = <strong>16 s</strong></p></td></tr><tr><td></td><td><p>\\(\\bar{v}\\) </p></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{s}{t}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{138}{16}\\) = <strong>8.625 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,28,true),
(10,'calculations','No.16','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16.</strong><strong> &nbsp; </strong>Draw a graph of velocity against time for a body which starts with an initial velocity of 4 m s<sup>-1</sup> and continues to move with an acceleration of 1.5 m s<sup>-2</sup> for 6 s. Show how you would find each of the following from the graph: (a) the average velocity (b) the distance moved in those 6 s.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\({v}_{0}\\) = 4 m s<sup>-1</sup>, &nbsp;  &nbsp; a = 1.5 m s<sup>-2</sup>, &nbsp;  &nbsp; t = 6 s, &nbsp;  &nbsp; (a) \\(\\bar{v}\\) = ? (b) s = ?</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0 </sub>+ a t</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>4 + (1.5 × 6) = 4 + 9 = <strong>13 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"></td></tr><tr><td><p>(a)</p></td><td><p>\\(\\bar{v}\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{{v}_{0}+ v}{2}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{4 + 13}{2}\\) = \\(\\frac{17}{2}\\) = <strong>8.5 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td><p>(b)</p></td><td><p>s</p></td><td><p>=</p></td><td><p>area of triangle CDE + area of rectangle ABED</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>( \\(\\frac{1}{2}\\)× DE × CE) + (AB × BE)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>( \\(\\frac{1}{2}\\)× 6 × 9) + (6 × 4)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>27 + 24 = <strong>51 m</strong></p></td></tr><tr><td><p><strong>[OR]</strong></p></td><td><p>s</p></td><td><p>=</p></td><td><p>Area of trapezium</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\)× AB (AD + BC)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\)×6 (4 + 13)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>51 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,29,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.18','2','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.18</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.18.</strong><strong> &nbsp; </strong>The motion of an object is recorded as shown in the table below. (i) Draw the       distance-time graph plotting time along the x-axis. (ii) Find the speed of the object.</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>time (s)</p></td><td><p>0</p></td><td><p>1</p></td><td><p>2</p></td><td><p>3</p></td><td><p>4</p></td><td><p>5</p></td></tr><tr><td><p>distance (m)</p></td><td><p>0</p></td><td><p>4</p></td><td><p>8</p></td><td><p>12</p></td><td><p>16</p></td><td><p>20</p></td></tr></tbody></table></div><p><figure><img src=\"cal-media/g11-g10-image8.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>speed</p></td><td><p>=</p></td><td><p>\\(\\frac{distance travelled }{time taken}\\) </p></td><td><p><strong>[OR]</strong></p></td><td><p>speed</p></td><td><p><strong>= </strong>slope</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{20 }{5}\\) = <strong>4 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td></td><td><p>= \\(\\frac{8 -4 }{2 - 1 }\\) = \\(\\frac{4 }{1}\\) = <strong>4 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,30,true),
(10,'calculations','Rev.1','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong>Is it correct to describe Newton&#x27;s second law in symbols as \\(\\vec{F}\\) \\(∝\\) \\(\\vec{a}\\)?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Yes. By Newton’s second law of motion, \\(\\vec{F}\\) = m \\(\\vec{a}\\).</p><p><strong> &nbsp; </strong>m = constant, &nbsp; \\(\\vec{F}\\) \\(∝\\) \\(\\vec{a}\\) &nbsp;  &nbsp; \\(\\vec{F}\\) = net force, &nbsp; \\(\\vec{a}\\) = acceleration</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.2','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Although two forces act simultaneously on a body, it continues to move with a constant velocity. What can be said about the two forces?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>When the body moves with a constant velocity, it has no acceleration. According to Newton&#x27;s second law, the net force on the body will be zero. (F = m a)</p><p><strong> &nbsp; </strong>So, two forces acting simultaneously on that body are equal in magnitude and opposite in directions. (\\(\\vec{{F}_{1}}\\) = - \\(\\vec{{F}_{2}}\\))</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Rev.3','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Can action and reaction cancel each other? Why?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>No, action and reaction cannot cancel each other since action-reaction pair acts on two separate objects.</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','No.1','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No</strong><strong>.1.</strong><strong> &nbsp; </strong> &nbsp; <em><strong>Which is more difficult? To move a small stone (or) a big stone. Why?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>It is more difficult to move a big stone because mass of the big stone is greater than that of a small one. The big stone has greater inertia.</p></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Eg.1','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>If 10 N force acts upon a 2 kg mass, find the acceleration produced.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>F = 10 N, &nbsp; m = 2 kg, &nbsp; <em>a</em> = ?</p></td></tr><tr><td></td><td colspan=\"3\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>F </p></td><td><p>=</p></td><td><p>m <em>a</em></p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>\\(\\frac{F}{m}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{10}{2}\\) = <strong>5 m s</strong><strong><sup>-2</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Eg.2','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A 12 lb force gives a body an acceleration of 4 ft s<sup>-2</sup>. Find the mass of the body.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>F = 12 lb, &nbsp; <em>a</em> = 4 ft s<sup>-2</sup>, &nbsp; m = ?</p></td></tr><tr><td></td><td colspan=\"3\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>F </p></td><td><p>=</p></td><td><p>m <em>a</em></p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{F}{a}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{12}{4}\\) = <strong>3 </strong><strong>sl</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.3','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No</strong><strong>.3.</strong><strong> &nbsp; </strong> &nbsp; If a proton of mass 1.675 × 10<sup>-24</sup> g is accelerated by an accelerator to an acceleration of 10<sup>6</sup> m s<sup>-2</sup>, find the net force acting on the proton.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 1.675 × 10<sup>-24</sup> g = 1.675 × 10<sup>-24</sup> g × \\(\\frac{1 kg}{{10}^{3} g}\\) = <strong>1.675 × 10</strong><strong><sup>-27</sup></strong><strong> kg</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p><em>a</em> = 10<sup>6</sup> m s<sup>-2</sup>, &nbsp;  &nbsp; F = ?</p></td></tr><tr><td></td><td colspan=\"3\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>F </p></td><td><p>=</p></td><td><p>m <em>a</em></p></td></tr><tr><td></td><td><p>F</p></td><td><p>=</p></td><td><p>1.675 × 10<sup>-</sup><sup>27</sup> × 10<sup>6</sup><sup> </sup>= <strong>1.675 × 10</strong><strong><sup>-21</sup></strong><strong><sup> </sup></strong><strong>N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.4','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4</strong>. &nbsp;  &nbsp; If the velocity of a car of l200 kg mass increases from 60 m s<sup>-1</sup> to 120 m s<sup>-1</sup> in 10 s, what is the net force acting on the car?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p><figure><img src=\"cal-media/g11-g10-image10.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m = 1200 kg, &nbsp; v<sub>0</sub> = 60 m s<sup>-1</sup>, &nbsp; v = 120 m s<sup>-1</sup>, &nbsp; t = 10 s, &nbsp; F = ?</p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>\\(\\frac{v- {v}_{0}}{t}\\) </p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{120 - 60}{10}\\) </p></td><td><p>F </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{60}{10}\\) = <strong>6 m s</strong><strong><sup>-2</sup></strong></p></td><td><p>F</p></td><td><p>= 1200 \\(×\\) 6 = <strong>7200 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','Eg.3','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A 2 kg ball is moving with an initial speed of 15 m s<sup>-1</sup> on a rough plane, which is in a horizontal position, and gradually slows down and stops after travelling 20 m. Find the magnitude of the force which resists the motion of the ball.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>m = 2 kg, &nbsp; v<sub>0</sub> = 15 m s<sup>-1</sup>, &nbsp; v = 0 m s<sup>-1</sup>(stop), &nbsp; s = 20 m, &nbsp; F = ?</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 <em>a</em> s</p></td><td colspan=\"2\"></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>15<sup>2</sup> + (2 × \\(a\\) ×20)</p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>225 + 40 <em>a</em></p></td><td><p>F </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td><p>40 <em>a</em></p></td><td><p>=</p></td><td><p>- 225</p></td><td><p>F</p></td><td><p>= 2 × (- 5.6) </p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>- \\(\\frac{225 }{40}\\) = <strong>- 5.6 m s</strong><strong><sup>-2</sup></strong></p></td><td></td><td><p>= <strong>- 11.2 N</strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>The direction of the force is opposite to that of the motion of the ball. The magnitude of the force is 11.2 N.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.5','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5</strong>. &nbsp;  &nbsp; A truck of 2 000 kg mass moving at a velocity of 12 m s<sup>-1</sup> slides 15 m before it comes to a stop after applying the brakes. Find the resisting force of the brakes.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>m = 2 000 kg, &nbsp; \\({v}_{0}\\) = 12 m s<sup>-1</sup>, &nbsp; v = 0 (stop), &nbsp; s = 15 m, &nbsp; F = ?</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 <em>a</em> s</p></td><td colspan=\"2\"></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>12<sup>2</sup> + (2 × a × 15)</p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>144 + 30 <em>a</em></p></td><td><p>F </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td><p>30 <em>a</em></p></td><td><p>=</p></td><td><p>- 144</p></td><td><p>F</p></td><td><p>= 2000 × (- 4.8) </p></td></tr><tr><td></td><td><p><em>a</em></p></td><td><p>=</p></td><td><p>- \\(\\frac{144 }{30}\\) = <strong>- 4.8 m s</strong><strong><sup>-2</sup></strong></p></td><td></td><td><p>= <strong>- 9600 N</strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>The direction of the force is opposite to that of the motion of the truck. The magnitude of the force is 9600 N.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.6','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6</strong><strong>.</strong><strong> &nbsp; </strong> &nbsp; What is the acceleration of a body weighing 20 N due to the applied force             F<sub>net</sub> = 20 N?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>w = 20 N, &nbsp; F<sub>net</sub><sub></sub> = 20 N, &nbsp; g = 10 m s<sup>-2</sup>, &nbsp; <em>a</em> = ? </p></td></tr><tr><td></td><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>w</p></td><td><p>=</p></td><td><p>m g</p></td><td><p>F </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{w}{g}\\) </p></td><td><p><em>a</em></p></td><td><p>= \\(\\frac{F}{m}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{20}{10}\\)   = <strong>2 kg</strong></p></td><td></td><td><p>= \\(\\frac{20}{2}\\) = <strong>10 m s</strong><strong><sup>-2</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.8','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8</strong><strong>.</strong><strong> &nbsp; </strong> &nbsp; A 3-ton car moving with the velocity of 30 mi h<sup>-1</sup> is brought to a stop in 2 s. Find the resisting force of the brakes acting on the car.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>w = 3 ton = 3 ton × \\(\\frac{2240 lb}{1 ton}\\) = <strong>6720 </strong>\\(lb\\)</p><p>v<sub>0</sub> = 30 mi h<sup>-1</sup> = 30 mi h<sup>-1</sup> × \\(\\frac{5280 ft}{1 mi}\\) × \\(\\frac{1 h}{3600 s}\\) = 44 ft s<sup>-1</sup></p><p>v = 0 (stop), &nbsp; t = 2 s, &nbsp;  &nbsp; g = 32 ft s<sup>-2</sup>, &nbsp; F = ?</p></td></tr><tr><td></td><td><p>w</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m g</p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{w}{g}\\) </p></td><td><p>F </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{6720}{32}\\) </p></td><td><p>F</p></td><td><p>= 210 × (- 22)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>210 </strong>\\(sl\\)</p></td><td></td><td><p>= <strong>- 4620 </strong>\\(lb\\)</p></td></tr><tr><td></td><td colspan=\"5\"><p>The direction of the force is opposite to that of the motion of the car. The magnitude of the force is 4620 \\(lb\\).</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.9','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9</strong><strong>.</strong><strong> &nbsp; </strong> &nbsp; A lift weighing 2 000 lb is pulled up by a cable of tension (force) 5 000 lb. Find the mass of the lift and its upward acceleration.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>w = 2 000 \\(lb\\) (downward), T = 5 000 \\(lb\\) (upward), g = 32 ft s<sup>-2</sup>, m = ? a = ?</p></td></tr><tr><td></td><td><p>w</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m g</p></td><td colspan=\"2\"><p>Using Newton’s second law,</p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{w}{g}\\) = \\(\\frac{2000}{32}\\) = <strong>62.5 </strong>\\(sl\\)</p></td><td><p>F<sub>net</sub> </p></td><td><p>= m <em>a</em></p></td></tr><tr><td></td><td><p>\\(\\vec{F}\\) <sub>net</sub></p></td><td><p>=</p></td><td><p>\\(\\vec{T}\\) + \\(\\vec{w}\\)</p></td><td><p><em>a</em></p></td><td><p>= \\(\\frac{{F}_{net}}{m}\\)</p></td></tr><tr><td></td><td><p>F<sub>net</sub></p></td><td><p>=</p></td><td><p>T – w</p></td><td></td><td><p>= \\(\\frac{3000}{62.5}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>5000 – 2000 = <strong>3000 </strong>\\(lb\\)</p></td><td></td><td><p>= <strong>48 ft s</strong><strong><sup>-2</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.7','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.</strong><strong>7.</strong><strong> &nbsp; </strong> &nbsp; Compare the accelerations of the two bodies of masses M and 3M when the same net force of 20 N is applied to each of them.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>m<sub>1</sub> = M, &nbsp; m<sub>2</sub> = 3M, &nbsp; F<sub>1</sub> = F<sub>2</sub> = 20N, &nbsp;  &nbsp; \\(\\frac{{a}_{1}}{{a}_{2}}\\) = ?</p></td></tr><tr><td></td><td colspan=\"3\"><p>Using Newton’s second law,</p></td><td><p>F<sub>1</sub></p></td><td><p>=</p></td><td><p>F<sub>2</sub></p></td></tr><tr><td></td><td><p>F </p></td><td><p>=</p></td><td><p>m \\(a\\)</p></td><td><p>m<sub>1</sub> <em>a</em><sub>1</sub></p></td><td><p>=</p></td><td><p>m<sub>2</sub> <em>a</em><sub>2</sub></p></td></tr><tr><td></td><td><p>F<sub>1</sub></p></td><td><p>=</p></td><td><p>m<sub>1</sub> <em>a</em><sub>1</sub></p></td><td><p>M <em>a</em><sub>1</sub></p></td><td><p>=</p></td><td><p>3M <em>a</em><sub>2</sub></p></td></tr><tr><td></td><td><p>F<sub>2</sub></p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image10.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m<sub>2</sub> <em>a</em><sub>2</sub></p></td><td><p> <em>a</em><sub>1</sub></p></td><td><p>=</p></td><td><p>3 <em>a</em><sub>2</sub></p></td></tr><tr><td></td><td colspan=\"6\"><p>Acceleration of a body of mass M is 3 times as much as that of a body of mass 3M</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','Rev.4','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong>Express the value of G in the CGS units.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 kg = 10<sup>3</sup> g, &nbsp; 1 cm = 10<sup>-2</sup> m</p></td></tr><tr><td></td><td><p>G</p></td><td><p>=</p></td><td><p><strong>6.67 </strong><strong></strong><strong> 10</strong><strong><sup>-11 </sup></strong><strong>m</strong><strong><sup>3 </sup></strong><strong>kg</strong><strong><sup>-1</sup></strong><strong> s</strong><strong><sup>-2</sup></strong></p></td></tr><tr><td></td><td><p>G</p></td><td><p>=</p></td><td><p>6.67  10<sup>-11 </sup>m<sup>3 </sup>kg<sup>-1</sup> s<sup>-2</sup> × \\(\\frac{1 {cm}^{3}}{({10}^{-2} m{)}^{3}}\\) × \\(\\frac{1 kg}{{10}^{3} g}\\) = <strong>6.67 </strong><strong></strong><strong> 10</strong><strong><sup>-8</sup></strong><strong> cm</strong><strong><sup>3</sup></strong><strong> g</strong><strong><sup>-1</sup></strong><strong> s</strong><strong><sup>-2</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.2','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2</strong><strong>.</strong><strong> &nbsp; </strong> &nbsp; <em><strong>A man weighing 600 N stands on the earth’s surface. How much force does he exert on the earth? Explain.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; The weight of the body is the gravitational force acting on it.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>So, the force exerted by the earth <strong>on the man</strong> is 600 N and the force exert by the man <strong>on the earth</strong> is also 600 N.</p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Rev.5','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>The weight of a body may change when its location is changed, but mass does not. Why?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Mass is the quantity of matter in a body. Mass does not dependent on the gravity. Thus, mass does not change although its location changes.</p><p><strong> &nbsp; </strong>Weight is the force of gravity and gravity changes with location. Thus, the weight of a body may change when its location is changed.</p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','No.10','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10</strong><strong>.</strong><strong> &nbsp; </strong>If a body weighing 100 N is carried to the moon and put on the moon&#x27;s surface, what will happen to the weight of the body? Will the mass of the body change?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>w<sub>earth</sub> = 100 N, &nbsp;  &nbsp; g<sub>earth</sub> = 10 m s<sup>-2</sup>, &nbsp; g<sub>moon</sub> = 1.6 m s<sup>-2</sup></p></td></tr><tr><td></td><td><p>w</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image10.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m g</p></td><td><p>w<sub>moon</sub></p></td><td><p>=</p></td><td><p>m g<sub>moon</sub></p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{{w}_{earth}}{{g}_{earth}}\\) </p></td><td></td><td><p>=</p></td><td><p>10 × 1.6</p></td></tr><tr><td></td><td><p>m</p></td><td><p>=</p></td><td><p>\\(\\frac{100}{10}\\) = <strong>10 kg</strong></p></td><td><p>w<sub>moon</sub></p></td><td><p>=</p></td><td><p><strong>16 N</strong></p></td></tr><tr><td></td><td colspan=\"6\"><p>Mass is the quantity of matter in a body. Mass does not change with location.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.11','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11</strong><strong>.</strong><strong> &nbsp; </strong>Compared the moon&#x27;s gravitational forces acting on the two bodies of masses M and 3M falling simultaneously onto the moon&#x27;s surface from a height near the surface. If               M = 0.2 kg and acceleration due to the moon is 1.6 m s<sup>-2</sup>, find the moon&#x27;s gravitational forces acting on each of the bodies.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>m<sub>1</sub> = M, &nbsp; m<sub>2</sub> = 3M</p></td><td colspan=\"3\"></td></tr><tr><td></td><td colspan=\"7\"><p>Gravitational force acting on the body is weight.</p></td></tr><tr><td></td><td><p>w<sub>1</sub></p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image14.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m<sub>1</sub> g</p></td><td colspan=\"2\"><p>\\(\\frac{{w}_{2}}{{w}_{1}}\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{3 M g}{M g}\\) </p></td></tr><tr><td></td><td><p>w<sub>2</sub></p></td><td><p>=</p></td><td><p>m<sub>2</sub> g</p></td><td colspan=\"2\"><p>\\(\\frac{{w}_{2}}{{w}_{1}}\\) </p></td><td><p>=</p></td><td><p>3</p></td></tr><tr><td></td><td><p>\\(\\frac{{w}_{2}}{{w}_{1}}\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{{m}_{2}g}{{m}_{1}g}\\) </p></td><td colspan=\"2\"><p>w<sub>2</sub></p></td><td><p>=</p></td><td><p>3 w<sub>1</sub></p></td></tr><tr><td></td><td colspan=\"3\"><p>M = 0.2 kg, &nbsp; g = 1.6 m s<sup>-2</sup></p></td><td colspan=\"2\"></td><td></td><td></td></tr><tr><td></td><td><p>w<sub>1</sub></p></td><td><p>=</p></td><td><p>m<sub>1</sub> g</p></td><td colspan=\"2\"><p>w<sub>2</sub></p></td><td><p>=</p></td><td><p>m<sub>2</sub> g</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>M g</p></td><td colspan=\"2\"></td><td><p>=</p></td><td><p>3M g</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.2 × 1.6 <strong>= 0.32 N</strong></p></td><td colspan=\"2\"></td><td><p>=</p></td><td><p>3 × 0.2 × 1.6 <strong>= 0.96 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','No.12','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12</strong><strong>.</strong><strong> &nbsp; </strong>The gravitational force of the moon is less than that of the earth. The moon’s gravitational force acting on a body of mass 1 kg is 1.6 N. What will be the weight of a 40 kg mass on the moon?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>The moon’s gravitational force acting on a body of mass 1 kg is 1.6 N,</p></td></tr><tr><td></td><td><p><figure><img src=\"cal-media/g11-g10-image8.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>g = 1.6 kg N<sup>-1</sup> = 1.6 m s<sup>-2</sup></p></td><td><p>w</p></td><td><p>=</p></td><td><p>m g</p></td></tr><tr><td></td><td><p>m = 40 kg, &nbsp; w = ?</p></td><td></td><td><p>=</p></td><td><p>40 × 1.6 = <strong>64 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','Eg.4','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>If G = 6.67  10<sup>-11 </sup>m<sup>3</sup> kg<sup>-1</sup> s<sup>-2</sup>, mass of the earth, M = 5.97 × 10<sup>24</sup> kg and radius of the earth, R = 6.37×10<sup>6</sup> m, find the value of the acceleration due to gravity g.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>G = 6.67  10<sup>-11 </sup>m<sup>3</sup> kg<sup>-1</sup> s<sup>-2</sup>, &nbsp; M = 5.97 × 10<sup>24</sup> kg, &nbsp; R = 6.37×10<sup>6</sup> m</p></td></tr><tr><td></td><td colspan=\"3\"><p>Let,  &nbsp; the mass of body on the earth surface = m</p><p> &nbsp; weight of the body = w = mg</p></td></tr><tr><td></td><td colspan=\"3\"><p>By Newton’s law of gravitation, the gravitational force between the body and the earth</p></td></tr><tr><td></td><td><p>F</p></td><td><p>=</p></td><td><p>G \\(\\frac{M m}{{R}^{2}}\\)</p></td></tr><tr><td></td><td colspan=\"3\"><p>The weight of the body is the gravitational force acting on it.</p></td></tr><tr><td></td><td><p>w</p></td><td><p>=</p></td><td><p>F</p></td></tr><tr><td></td><td><p>m g</p></td><td><p>=</p></td><td><p> \\(\\frac{M m}{{R}^{2}}\\)</p></td></tr><tr><td></td><td><p>g</p></td><td><p>=</p></td><td><p>G \\(\\frac{M }{{R}^{2}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>6.67  10<sup>-11 </sup> \\(× \\frac{5.97 × 1{0}^{24} }{6.37×1{0}^{6} × 6.37×1{0}^{6} }\\) = <strong>9.8 m s</strong><strong><sup>-2</sup></strong><strong> (or) N kg</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','Eg.5','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>What is the velocity of a stone freely falling from a height of 20 m when it strikes the ground? How long does the stone take to reach the ground? (g = 10 m s<sup>-2</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>v<sub>0</sub> = 0 (freely falling), &nbsp;  &nbsp; h = - 20 m (below the origin) &nbsp;  &nbsp; g = - 10 m s<sup>-2</sup> &nbsp; </p><p>v = ? &nbsp;  &nbsp; t = ?</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 g h</p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g t<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0 + [2 (-10) (-20)]</p></td><td><p>- 20</p></td><td><p>=</p></td><td><p>0 + [ \\(\\frac{1}{2}\\) (-10) t<sup>2</sup>]</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>400</p></td><td><p>- 20</p></td><td><p>=</p></td><td><p>- 5 t<sup>2</sup></p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>\\(±\\) 20 m s<sup>-1</sup></p></td><td><p>t<sup>2</sup></p></td><td><p>=</p></td><td><p>4</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p><strong>- 20 m s</strong><strong><sup>-1</sup></strong><strong> (downward)</strong></p></td><td><p>t</p></td><td><p>=</p></td><td><p><strong>2 s</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,22,true),
(10,'calculations','Rev.6','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>6</strong><strong>.</strong><strong> &nbsp; </strong>A stone is thrown vertically straight up with 40 m s<sup>-1</sup>. What will be its respective velocities at 3 s, 4 s and 5 s after it has been thrown? Find the height of the stone at 3 s, 4 s and 5 s. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>v<sub>0</sub> = + 40 m s<sup>-1</sup> (upward), &nbsp; g = - 10 m s<sup>-2</sup>    t<sub>1</sub> = 3 s, t<sub>2</sub> = 4 s, t<sub>3</sub> = 5 s</p><p>v<sub>1</sub> =?  v<sub>2</sub> =?  v<sub>3</sub> =? &nbsp;  &nbsp; h<sub>1</sub> =?  h<sub>2</sub> =?  h<sub>3</sub> =?</p></td></tr><tr><td></td><td><p>v<sub>1</sub></p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t<sub>1</sub></p></td><td><p>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g \\({t}_{1}^{2}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>40 + (-10 \\(×\\) 3)</p></td><td></td><td><p>=</p></td><td><p>(40 \\(×\\) 3) + ( \\(\\frac{1}{2}\\) (-10) \\(×\\) 3 \\(×\\) 3)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image18.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure><strong>10 m s</strong><strong><sup>-1</sup></strong><strong> (upward)</strong></p></td><td></td><td><p>=</p></td><td><p><strong>+ 75 m (above origin)</strong></p></td></tr><tr><td></td><td><p>v<sub>2</sub></p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t<sub>2</sub></p></td><td><p>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g \\({t}_{2}^{2}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>40 + (-10 \\(×\\) 4)</p></td><td></td><td><p>=</p></td><td><p>(40 \\(×\\) 4) + ( \\(\\frac{1}{2}\\) (-10) \\(×\\) 4 \\(×\\) 4)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>0 (highest point)</strong></p></td><td></td><td><p>=</p></td><td><p><strong>+ 80 m (above origin)</strong></p></td></tr><tr><td></td><td><p>v<sub>3</sub></p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t<sub>3</sub></p></td><td><p>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g \\({t}_{3}^{2}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>40 + (-10 \\(×\\) 5)</p></td><td></td><td><p>=</p></td><td><p>(40 \\(×\\) 5) + ( \\(\\frac{1}{2}\\) (-10) \\(×\\) 5 \\(×\\) 5)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>-10 m s</strong><strong><sup>-1</sup></strong><strong> (downward)</strong></p></td><td></td><td><p>=</p></td><td><p><strong>+ 75 m (above origin)</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.14','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14</strong><strong>.</strong><strong> &nbsp; </strong>A man throws a stone vertically upward at 30 m s<sup>-1</sup>. How long does it take the stone to reach 40 m?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>v<sub>0</sub> = + 30 m s<sup>-1</sup> (upward),  &nbsp; h = + 40 m (above origin), &nbsp; t = ? &nbsp; g = - 10 m s<sup>-2</sup>  </p></td></tr><tr><td></td><td><p>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g t<sup>2</sup></p></td></tr><tr><td></td><td><p>40</p></td><td><p>=</p></td><td><p>30 t + [ \\(\\frac{1}{2}\\) (-10) t<sup>2</sup>]</p></td></tr><tr><td></td><td><p>40</p></td><td><p>=</p></td><td><p>30 t – 5 t<sup>2</sup></p></td></tr><tr><td></td><td><p>8</p></td><td><p>=</p></td><td><p>6 t – t<sup>2</sup></p></td></tr><tr><td></td><td><p>t<sup>2</sup> – 6 t + 8</p></td><td><p>=</p></td><td><p>0</p></td></tr><tr><td></td><td><p>(t – 4) (t – 2)</p></td><td><p>=</p></td><td><p>0</p></td></tr><tr><td></td><td colspan=\"3\"><p> &nbsp; t – 4 = 0 (or) t – 2 = 0</p></td></tr><tr><td></td><td colspan=\"3\"><p> &nbsp; t = 4 s (or) t = 2 s</p></td></tr><tr><td></td><td colspan=\"3\"><p>Two values of t means that the stone passes twice the point of 40 m, in rising up and in falling back.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,24,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','Eg.7','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A ball is thrown vertically upward and it is caught again after 6 s. </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) Find the total displacement for the whole distance travelled. </p><p> &nbsp;  &nbsp; (b) Find the velocity with which it is thrown. </p><p> &nbsp;  &nbsp; (c) Find the maximum height reached. </p><p> &nbsp;  &nbsp; (d) Find the average velocity for the whole distance travelled.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>T = 2 t = 6 s, (total time taken), &nbsp; t = 3 s, (ascending time)</p></td></tr><tr><td><p>(a)</p></td><td colspan=\"6\"><p>The total displacement for the whole distance travelled is <strong>zero</strong> because the starting point and the end point are the same.</p></td></tr><tr><td><p>(b)</p></td><td colspan=\"3\"><p>v<sub>0</sub> = ? &nbsp;  &nbsp; g = - 10 m s<sup>-2</sup></p></td><td><p>(c)</p></td><td><p>h</p></td><td><p>= v<sub>0</sub> t + \\(\\frac{1}{2}\\) g t<sup>2</sup></p></td></tr><tr><td></td><td colspan=\"3\"><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>v = 0 m s<sup>-1</sup> (highest point)</p></td><td></td><td></td><td><p>= [30 × 3] + [ \\(\\frac{1}{2}\\) (-10) 3<sup>2</sup>]</p></td></tr><tr><td></td><td colspan=\"3\"><p>t = 3 s (ascending time)</p></td><td></td><td></td><td><p>= 90 - 45</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t</p></td><td></td><td></td><td><p>= <strong>+ 45 m (above origin)</strong></p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>v<sub>0</sub> + (-10) 3</p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>v<sub>0</sub> - 30</p></td><td><p>(d)</p></td><td><p>\\({\\vec{v}}_{av}\\)</p></td><td><p>= \\(\\frac{total displacement}{total total time taken}\\)</p></td></tr><tr><td></td><td><p>v<sub>0</sub></p></td><td><p>=</p></td><td><p><strong>+ 30 m s</strong><strong><sup>-1</sup></strong><strong> (upward)</strong></p></td><td></td><td></td><td><p>= \\(\\frac{0}{6}\\) = <strong>0</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,25,true),
(10,'calculations','Eg.6','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A ball is thrown upwards with a velocity of 40 m s<sup>-1</sup>. How long does the ball stay in the air? What height does the ball reach? </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>v<sub>0</sub> = + 40 m s<sup>-1</sup> (upward), &nbsp; v = 0 (highest point), &nbsp; g = - 10 m s<sup>-2</sup>, &nbsp; h = ? &nbsp; T = ?</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t</p></td><td colspan=\"3\"><p>the total time the ball stays in the air,</p></td></tr><tr><td></td><td><p>0</p></td><td><p><em>=</em></p></td><td><p>40 + (-10) t</p></td><td><p>T</p></td><td><p>=</p></td><td><p>2 t = 2 × 4 = <strong>8 s</strong></p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>40 – 10 t</p></td><td><p>h</p></td><td><p>=</p></td><td><p>v<sub>0</sub> t + \\(\\frac{1}{2}\\) g t<sup>2</sup></p></td></tr><tr><td></td><td><p>10 t</p></td><td><p>=</p></td><td><p>40</p></td><td></td><td><p>=</p></td><td><p>[40 × 4] + [ \\(\\frac{1}{2}\\) (-10) 4<sup>2</sup>]</p></td></tr><tr><td></td><td><p>t</p></td><td><p>=</p></td><td><p><strong>4 s (ascending time)</strong></p></td><td><p>h</p></td><td><p>=</p></td><td><p><strong>+ 80 m (above origin)</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,26,true),
(10,'calculations','No.13','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13</strong><strong>.</strong><strong> &nbsp; </strong>An object is hurled vertically upwards with a speed of 50 m s<sup>-1</sup>. How long does it take the object to be caught again?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>v<sub>0</sub> = + 50 m s<sup>-1</sup> (upward), &nbsp; v = 0 (highest point)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t</p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>0</p></td><td><p><em>=</em></p></td><td><p>50 + (-10) t</p></td><td colspan=\"3\"><p>time taken to caught again</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>50 – 10 t</p></td><td><p>T</p></td><td><p>=</p></td><td><p>2 t</p></td></tr><tr><td></td><td><p>10 t</p></td><td><p>=</p></td><td><p>50</p></td><td></td><td><p>=</p></td><td><p>2 × 4 = <strong>8 s</strong></p></td></tr><tr><td></td><td><p>t</p></td><td><p>=</p></td><td><p><strong>5 s (ascending time)</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,27,true),
(10,'calculations','No.15','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15</strong><strong>.</strong><strong> &nbsp; </strong>A stone, thrown by a girl, reaches a height of 20 m. How long does it take the stone to be caught back? With what velocity does she throw the stone?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>h = + 20 m (above origin) &nbsp; g = - 10 m s<sup>-2</sup>, &nbsp; T = ? &nbsp; v<sub>0</sub> = ? &nbsp; v = 0 (highest point)</p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\) + 2 g h</p></td><td><p>v</p></td><td><p>=</p></td><td><p>v<sub>0</sub> + g t</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\)  + [2 (-10) 20]</p></td><td><p>0</p></td><td><p>=</p></td><td><p>20 + (-10) t</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>\\({v}_{0}^{2}\\)  - 400</p></td><td><p>10 t</p></td><td><p>=</p></td><td><p>20</p></td></tr><tr><td></td><td><p>\\({v}_{0}^{2}\\) </p></td><td><p>=</p></td><td><p>400</p></td><td><p>t</p></td><td><p>=</p></td><td><p><strong>2 s</strong></p></td></tr><tr><td></td><td><p>v<sub>0</sub></p></td><td><p>=</p></td><td><p>\\(±\\) 20 m s<sup>-1</sup></p></td><td colspan=\"3\"><p>time taken to caught again</p></td></tr><tr><td></td><td><p>v<sub>0</sub></p></td><td><p>=</p></td><td><p><strong>+ 20 m s</strong><strong><sup>-1 </sup></strong><strong>(upward)</strong></p></td><td><p>T</p></td><td><p>=</p></td><td><p>2 t = 2 × 2 = <strong>4 s</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,28,true),
(10,'calculations','Rev.7','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>7</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>How does the momentum of a body relate its velocity?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The momentum of a body is directly proportional to its velocity. Since \\(\\vec{p}\\) = m \\(\\vec{v}\\).</p></div></details></div></article>"}'::jsonb,29,true),
(10,'calculations','Rev.8','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>8</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Rewrite the relation</strong></em> m \\(\\frac{v- {v}_{0}}{t}\\) \\(∝\\) F <em><strong>in vector notation.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>In vector notation, m \\(\\frac{\\vec{v}- {\\vec{v}}_{0}}{t}\\) \\(∝\\) \\(\\vec{F}\\)</p></div></details></div></article>"}'::jsonb,30,true),
(10,'calculations','Eg.8','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A bullet of mass 50 g leaves the muzzle of a gun with a velocity of 20 000 cm s<sup>-1</sup>. Find the momentum of the bullet.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 50 g, &nbsp; v = 20 000 cm s<sup>-1</sup>, &nbsp; p = ?</p></td></tr><tr><td></td><td><p>p</p></td><td><p>=</p></td><td><p>m v</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>50 × 20 000 = 1 000 000 = <strong>10</strong><strong><sup>6</sup></strong><strong> g cm s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,31,true),
(10,'calculations','No.16','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16</strong><strong>.</strong><strong> &nbsp; </strong>If the velocity of a 0.02 kg bullet is 500 m s<sup>-1</sup>, find the magnitude of the momentum of the bullet. If the bullet is fired towards the north, what is the direction of its momentum?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 0.02 kg, &nbsp;  &nbsp; v = 500 m s<sup>-1</sup>, &nbsp;  &nbsp; p = ?</p></td></tr><tr><td></td><td><p>p</p></td><td><p>=</p></td><td><p>m v</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.02 × 500 = <strong>10 kg m s</strong><strong><sup>-1</sup></strong><strong> (toward the north)</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Since the bullet is fired towards the north, the direction of its momentum is also towards the north.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,32,true),
(10,'calculations','Eg.9','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A bullet of mass 16 g (0.016 kg) is fired from a 4 kg gun with a velocity of          600 m s<sup>-1</sup>. Find the recoil velocity of the gun.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td></td><td colspan=\"3\"><p>For bullet</p></td><td><p>For gun</p></td></tr><tr><td></td><td></td><td colspan=\"3\"><p>m<sub> b</sub> = 0.016 kg</p></td><td><p>m<sub> g</sub> = 4 kg</p></td></tr><tr><td></td><td><p>Before firing,</p></td><td colspan=\"3\"><p>v<sub>b</sub> = 0 (stop)</p></td><td><p>v<sub>g</sub> = 0 (stop)</p></td></tr><tr><td></td><td><p>After firing,</p></td><td colspan=\"3\"><p>\\({v''}_{b}\\) = 600 m s<sup>-1</sup></p></td><td><p>\\({v''}_{g}\\) = ?</p></td></tr><tr><td></td><td colspan=\"5\"><p>By the law of conservation of momentum, </p></td></tr><tr><td></td><td colspan=\"2\"><p>Total momentum before firing</p></td><td><p>=</p></td><td colspan=\"2\"><p>total momentum after firing</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({p}_{b}\\) + \\({p}_{g}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>\\({p''}_{b}\\) + \\({p''}_{g}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>m<sub>b</sub> \\({v}_{b}\\) + m<sub>g</sub> \\({v}_{g}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>m<sub>b</sub> \\({v''}_{b}\\) + m<sub>g</sub> \\({v''}_{g}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>(0.016 × 0) + (4 × 0)</p></td><td><p>=</p></td><td colspan=\"2\"><p>(0.016 × 600) + (4 × \\({v''}_{g}\\))</p></td></tr><tr><td></td><td colspan=\"2\"><p>0</p></td><td><p>=</p></td><td colspan=\"2\"><p>9.6 + 4 \\({v''}_{g}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>4 \\({v''}_{g}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>- 9.6</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({v''}_{g}\\) </p></td><td><p>=</p></td><td colspan=\"2\"><p><strong>- 2.4 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>The direction of the recoil velocity of the gun is opposite to that of the velocity of the bullet. The magnitude of the recoil velocity of the gun is 2.4 m s<sup>-1</sup>.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,33,true),
(10,'calculations','No.17','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.17</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.17</strong><strong>.</strong><strong> &nbsp; </strong>An object of mass 10 kg collides with a stationary object of mass 5 kg. If the two objects stick together, and move forward at a velocity of 4 m s<sup>-1</sup>, what was the original velocity of the moving object?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td></td><td colspan=\"3\"><p>For object 1 (moving)</p></td><td><p>For object 2 (stationary)</p></td></tr><tr><td></td><td></td><td colspan=\"3\"><p>m<sub> 1</sub> = 10 kg</p></td><td><p>m<sub> 2</sub> = 5 kg</p></td></tr><tr><td></td><td><p>Before collision,</p></td><td colspan=\"3\"><p>v<sub>1</sub> = ?</p></td><td><p>v<sub>2</sub> = 0</p></td></tr><tr><td></td><td><p>After collision,</p></td><td colspan=\"3\"><p>\\({v''}_{1}\\) = 4 m s<sup>-1</sup></p></td><td><p>\\({v''}_{2}\\) = 4 m s<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"5\"><p>By the law of conservation of momentum, </p></td></tr><tr><td></td><td colspan=\"2\"><p>Total momentum before firing</p></td><td><p>=</p></td><td colspan=\"2\"><p>total momentum after firing</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({p}_{1}\\) + \\({p}_{2}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>\\({p''}_{1}\\) + \\({p''}_{2}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>m<sub>1</sub> \\({v}_{1}\\) + m<sub>2</sub> \\({v}_{2}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>m<sub>1</sub> \\({v''}_{1}\\) + m<sub>2</sub> \\({v''}_{2}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>(10 × v<sub>1</sub>) + (5 × 0)</p></td><td><p>=</p></td><td colspan=\"2\"><p>(10 × 4) + (5 × 4)</p></td></tr><tr><td></td><td colspan=\"2\"><p>10 v<sub>1</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>40 + 20</p></td></tr><tr><td></td><td colspan=\"2\"><p>10 v<sub>1</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>60</p></td></tr><tr><td></td><td colspan=\"2\"><p>v<sub>1</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p><strong>6 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,34,true),
(10,'calculations','No.18','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.18</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.18</strong><strong>.</strong><strong> &nbsp; </strong>A man dived horizontally with a velocity of 1.5 m s<sup>-1</sup> from a 100 kg boat. If the recoil velocity of the boat is 0.9 m s<sup>-1</sup>, what is the mass of the man?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td></td><td colspan=\"3\"><p>For man</p></td><td><p>For boat</p></td></tr><tr><td></td><td></td><td colspan=\"3\"><p>m<sub> </sub><sub>m</sub> = ?</p></td><td><p>m<sub> b</sub> = 100 kg</p></td></tr><tr><td></td><td><p>Before diving,</p></td><td colspan=\"3\"><p>v<sub>m</sub> = 0 (stop)</p></td><td><p>v<sub>b</sub> = 0 (stop)</p></td></tr><tr><td></td><td><p>After diving,</p></td><td colspan=\"3\"><p>\\({v''}_{m}\\) = 1.5 m s<sup>-1</sup></p></td><td><p>\\({v''}_{b}\\) = - 0.9 m s<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"5\"><p>By the law of conservation of momentum, </p></td></tr><tr><td></td><td colspan=\"2\"><p>Total momentum before firing</p></td><td><p>=</p></td><td colspan=\"2\"><p>total momentum after firing</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({p}_{m}\\) + \\({p}_{b}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>\\({p''}_{m}\\) + \\({p''}_{b}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>m<sub>m</sub> \\({v}_{m}\\) + m<sub>b</sub> \\({v}_{b}\\)</p></td><td><p>=</p></td><td colspan=\"2\"><p>m<sub>m</sub> \\({v''}_{m}\\) + m<sub>b</sub> \\({v''}_{b}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>(m<sub>m</sub>× 0) + (100 × 0)</p></td><td><p>=</p></td><td colspan=\"2\"><p>(m<sub>m</sub> × 1.5) + (100 × (-0.9))</p></td></tr><tr><td></td><td colspan=\"2\"><p>0</p></td><td><p>=</p></td><td colspan=\"2\"><p>1.5 m<sub>m</sub> - 90</p></td></tr><tr><td></td><td colspan=\"2\"><p>1.5 m<sub>m</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>90</p></td></tr><tr><td></td><td colspan=\"2\"><p>m<sub>m</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{90}{1.5}\\) = <strong>60 kg</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,35,true),
(10,'calculations','Eg.10','3','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.10.</strong><strong> &nbsp; </strong>A soccer ball of mass 0.4 kg is moving towards the south with 30 m s<sup>-1</sup>. Goal keeper kicked it and moved to the north with 40 m s<sup>-1</sup>. The contact time of kick is 0.4 s. Calculate the change in its momentum, and the force acting on it.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>m = 0.4 kg, &nbsp; v<sub>0</sub> = - 30 m s<sup>-1</sup> (south), &nbsp; v = 40 m s<sup>-1</sup> (north), &nbsp; t = 0.4 s</p><p>\\(∆\\)p = ?, &nbsp;  &nbsp; F = ? </p></td></tr><tr><td></td><td colspan=\"3\"><p>Change in velocity, </p></td><td colspan=\"2\"><p>Change in momentum,</p></td></tr><tr><td></td><td><p>\\(∆\\)v</p></td><td><p>=</p></td><td><p>v – v<sub>0</sub></p></td><td><p>\\(∆\\)p</p></td><td><p>= m \\(∆\\)v</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image8.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>40 – (-30)</p></td><td></td><td><p>= 0.4 × 70</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>70 m s<sup>-1</sup> (north)</p></td><td></td><td><p>= 28 kg m s<sup>-1</sup> (north)</p></td></tr><tr><td></td><td colspan=\"3\"><p><figure><img src=\"cal-media/g11-g10-image8.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td colspan=\"2\"><p>By Newton&#x27;s second law</p></td></tr><tr><td></td><td><p>\\(a\\)<sub> </sub></p></td><td><p>=</p></td><td><p>\\(\\frac{v- {v}_{0}}{t}\\) </p></td><td><p>F</p></td><td><p>= m \\(a\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{70}{0.4}\\) </p></td><td></td><td><p>= 0.4 × 175</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>175 m s<sup>-2</sup></p></td><td></td><td><p>= 70 N (north)</p></td></tr></tbody></table></div><p><strong>1.</strong> &nbsp; <em><strong>A 4.0 kg object is moving across a friction-free surface with a constant velocity of        2 m s</strong></em><em><strong><sup>-1</sup></strong></em><em><strong>. How much the horizontal forces are needed to maintain this state of motion?</strong></em></p><p>Ans: &nbsp; v = constant, \\(a\\) = 0 and F<sub>net</sub> = 0, since frictional force is zero, no horizontal force is needed.</p><p><strong>2.</strong> &nbsp; Two forces are acting on an object of 5 kg mass simultaneously. If one force of 8 N pulls to the left and another force of 20 N pulls to the right, what is its acceleration?</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 5 kg, &nbsp; \\(\\vec{{F}_{1}}\\) = - 8 N (left), &nbsp; \\(\\vec{{F}_{2}}\\) = + 20 N (right), &nbsp; \\(a\\) = ?</p></td></tr><tr><td></td><td><p>\\(\\vec{{F}_{net}}\\) </p></td><td><p>=</p></td><td><p>\\(\\vec{{F}_{2}}\\) - \\(\\vec{{F}_{1}}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>20 – 8 = 12 N (right)</p></td></tr><tr><td></td><td colspan=\"3\"><p>By Newton’s second law</p></td></tr><tr><td></td><td><p>\\({F}_{net}\\) </p></td><td><p>=</p></td><td><p>m \\(a\\)</p></td></tr><tr><td></td><td><p>\\(a\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{{F}_{net}}{m}\\) = \\(\\frac{12}{5}\\)</p></td></tr><tr><td></td><td><p>\\(\\vec{a}\\) </p></td><td><p>=</p></td><td><p>2.4 m s<sup>-2</sup> (right)</p></td></tr></tbody></table></div><p><strong>3.</strong> &nbsp; <em><strong>Do action and reaction pairs of forces balance one another?</strong></em></p><p><strong>Ans:</strong><strong> </strong>Yes, action and reaction pairs of forces balance one another but they cannot cancel out each other.</p><p><strong>4.</strong>  &nbsp; A water skier is being pulled at a constant speed 12 m s<sup>-1</sup> by a speed boat. The tension in the cable pulling the skier is 140 N. How large a frictional force is opposing the skier&#x27;s motion?</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>v = 12 m s<sup>-1</sup>(constant, a = 0 and \\(\\vec{{F}_{net}}\\) = 0) &nbsp; T = 140 N, &nbsp; F<sub>f</sub> = ?</p></td></tr><tr><td></td><td><p>\\(\\vec{{F}_{net}}\\) </p></td><td><p>=</p></td><td><p>\\(\\vec{T}\\) + \\(\\vec{{F}_{f}}\\)</p></td></tr><tr><td></td><td><p>0</p></td><td><p>=</p></td><td><p>140 + (- F<sub>f</sub>)</p></td></tr><tr><td></td><td><p>F<sub>f</sub></p></td><td><p>=</p></td><td><p>140 N</p></td></tr></tbody></table></div><p><strong>5.</strong><strong> &nbsp; </strong><em><strong>The sun contains the gases, which force holds the gas in the sun?</strong></em></p><p><strong>Ans:</strong><strong> &nbsp; </strong>Gravitational force</p><p><strong>6.</strong><strong> &nbsp; </strong><em><strong>If you throw up a ball in air, the ball comes down again. Which force causes this effect?</strong></em></p><p><strong>Ans:</strong><strong> &nbsp; </strong>Gravitational force</p></div></details></div></article>"}'::jsonb,36,true),
(10,'calculations','Rev.1','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>A person exerts pressure on the floor when standing, sitting and lying. Explain why the pressure is different when the person is in each of these positions.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>According to p = \\(\\frac{F}{A}\\) , &nbsp;  &nbsp; p \\(∝\\) \\(\\frac{1}{A}\\) (force = weight is constant for all positon)</p><p> &nbsp; The pressure is different for different contact areas.</p><p> &nbsp; The contact area in standing is smallest and the pressure is largest. </p><p> &nbsp; The contact area in lying is largest and the pressure is smallest.</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Eg.3','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The pressure in a motor car tire is 40 psi. What are the equivalent MKS unit and atm unit?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>1 psi = 6.9 \\(× {10}^{3}\\) Pa, &nbsp;  &nbsp; 1 Pa = 1 N m<sup>-1</sup>, &nbsp; 1 atm = 1.013 \\(× {10}^{5}\\) Pa</p></td></tr><tr><td></td><td><p>p</p></td><td><p>=</p></td><td><p>40 psi</p></td><td><p>p</p></td><td><p>= 40 psi</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><figure><img src=\"cal-media/g11-g10-image10.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>40 psi × \\(\\frac{6.9 × {10}^{3} Pa}{1 psi}\\)</p></td><td></td><td><p>= 276 ×\\({10}^{3}\\) Pa</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>276 ×</strong>\\({10}^{3}\\)<strong> Pa</strong></p></td><td></td><td><p>= 276 ×\\({10}^{3}\\) Pa ×\\(\\frac{1 atm}{1.013 × {10}^{5} Pa}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>276 ×</strong>\\({10}^{3}\\)<strong> N m</strong><strong><sup>-1</sup></strong><strong> (MKS)</strong></p></td><td></td><td><p>= <strong>2.724 atm</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Eg.4','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A drawing pin is pressed into the notice board. The pointed pin area is 0.25 mm<sup>2</sup> and the force exerted on the pin is 10 newtons. Compute the pressure.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>A = 0.25 mm<sup>2</sup> = 0.25 × (\\({10}^{-3}\\) m)<sup>2</sup> = 0.25 \\(× {10}^{-6}\\) m<sup>2</sup>, &nbsp; F = 10 N</p></td></tr><tr><td></td><td><p>p</p></td><td><p>=</p></td><td><p>\\(\\frac{F}{A}\\)  </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{10}{0.25 × {10}^{-6}}\\) = \\(\\frac{10  × {10}^{6}}{0.25 }\\) = <strong>4 </strong>\\(×\\)<strong> 10</strong><strong><sup>7</sup></strong><strong> Pa</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','No.1','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Normal atmospheric pressure 1 atm is equal to 1.013  10<sup>5</sup> Pa. How much force due to the atmosphere acts on a man whose total area is 2 m<sup>2</sup>?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>p<sub> </sub>= 1 atm = 1.013  10<sup>5</sup> Pa, &nbsp;  &nbsp; A = 2 m<sup>2</sup>, &nbsp; F = ?</p></td></tr><tr><td></td><td><p>p</p></td><td><p>=</p></td><td><p>\\(\\frac{F}{A}\\)  </p></td><td></td><td></td></tr><tr><td></td><td><p>F</p></td><td><p>=</p></td><td colspan=\"3\"><p>p A = 1.013  10<sup>5</sup>  2 = <strong>2.026 </strong><strong></strong><strong> 10</strong><strong><sup>5</sup></strong><strong> N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Eg.1','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Bi</strong>cycle tire has 6 cm  4 cm area touching the ground. The mass of the bicycle is   22 kg and the mass of the cyclist is 60 kg. Find the minimum pressure needed in the tire.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Total area, A &nbsp; = 2 (6 cm  4 cm)</p></td><td><p>F</p></td><td><p>= w</p></td></tr><tr><td></td><td><p> &nbsp; = 2  24 cm<sup>2</sup></p></td><td></td><td><p>= m g</p></td></tr><tr><td></td><td><p> &nbsp; = 48  (10<sup>-2</sup> m)<sup>2</sup> </p></td><td></td><td><p>= 82 × 10 = <strong>820 N</strong></p></td></tr><tr><td></td><td><p><figure><img src=\"cal-media/g11-g10-image20.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure> &nbsp; = <strong>48 </strong><strong></strong><strong> 10</strong><strong><sup>-4</sup></strong><strong> m</strong><strong><sup>2</sup></strong></p></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td><p>Total mass, m &nbsp; = 22 + 60</p></td><td></td><td><p>= \\(\\frac{820}{48 × {10}^{-4}}\\)</p></td></tr><tr><td></td><td><p> &nbsp; = <strong>82 kg</strong></p></td><td></td><td><p>= <strong>1.708 × </strong>\\({10}^{5}\\)<strong> Pa</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','No.2','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A man has mass 55 kg. His foot has the dimension of 24 cm  8 cm. Find the pressure on his feet.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Total area, A &nbsp; = 2 (24 cm  8 cm)</p></td><td><p>F</p></td><td><p>= w</p></td></tr><tr><td></td><td><p> &nbsp; = 2  192 cm<sup>2</sup></p></td><td></td><td><p>= m g</p></td></tr><tr><td></td><td><p> &nbsp; = 384  (10<sup>-2</sup> m)<sup>2</sup> </p></td><td></td><td><p>= 55 × 10 = <strong>550 N</strong></p></td></tr><tr><td></td><td><p><figure><img src=\"cal-media/g11-g10-image20.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure> &nbsp; = <strong>384 </strong><strong></strong><strong> 10</strong><strong><sup>-4</sup></strong><strong> m</strong><strong><sup>2</sup></strong></p></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td><p>Total mass, m &nbsp; = 55 kg</p></td><td></td><td><p>= \\(\\frac{550}{384 × {10}^{-4}}\\)</p></td></tr><tr><td></td><td><p> &nbsp; </p></td><td></td><td><p>= <strong>1.432 × </strong>\\({10}^{4}\\)<strong> Pa</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.3','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A four-wheel truck has each tire 20 cm  12 cm area touching the ground. The mass of the truck and the passengers are altogether 4 400 kg. Find the minimum pressure needed in a tire.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Total area, A &nbsp; = 4 (20 cm  12 cm)</p></td><td><p>F</p></td><td><p>= w</p></td></tr><tr><td></td><td><p> &nbsp; = 4  240 cm<sup>2</sup></p></td><td></td><td><p>= m g</p></td></tr><tr><td></td><td><p> &nbsp; = 960  (10<sup>-2</sup> m)<sup>2</sup> </p></td><td></td><td><p>= 4 400 × 10 = <strong>44 000 N</strong></p></td></tr><tr><td></td><td><p><figure><img src=\"cal-media/g11-g10-image20.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure> &nbsp; = <strong>960 </strong><strong></strong><strong> 10</strong><strong><sup>-4</sup></strong><strong> m</strong><strong><sup>2</sup></strong></p></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td><p>Total mass, m &nbsp; = 4 400 kg</p></td><td></td><td><p>= \\(\\frac{44 000}{960 × {10}^{-4}}\\) </p></td></tr><tr><td></td><td><p> &nbsp; </p></td><td></td><td><p>= <strong>4.583 × </strong>\\({10}^{5}\\)<strong> Pa</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','Eg.2','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Low pressure area in the Bay of Bengal is 998 hPa. A fishing boat nearby has sail area 4 m<sup>2</sup> at the normal atmospheric pressure. (a) Find the pressure difference. (b) Find the force exerted on the sail. [Hints: force exerts due to the atmospheric pressure difference.]</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>p<sub>low </sub>= 998 hPa, &nbsp;  &nbsp; A = 4 m<sup>2</sup>, &nbsp; p<sub>atm</sub> = 1013 hPa</p></td></tr><tr><td></td><td colspan=\"5\"><p>(a) pressure difference, \\(∆\\)p = ? &nbsp; (b) F = ?</p></td></tr><tr><td><p>(a)</p></td><td><p>\\(∆\\)p</p></td><td><p>= p<sub>atm</sub><sub> </sub>– p<sub>low</sub></p></td><td><p>(b)</p></td><td><p>\\(∆\\)p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td></td><td><p>= 1013 hPa – 998 hPa</p></td><td></td><td><p>F</p></td><td><p>= \\(∆\\)p A</p></td></tr><tr><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image10.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= 15 hPa</p></td><td></td><td></td><td><p>= 1500 × 4 </p></td></tr><tr><td></td><td></td><td><p>= <strong>1500 Pa</strong></p></td><td></td><td></td><td><p>= <strong>6000 N</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.4','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A brick of mass 2 kg has length 22 cm, breadth 11 cm and height 7 cm. Calculate the weight and the three kinds of pressure when it lies on a plane for three positions. In the missing (c), draw a sketch with base area 22 cm  7 cm.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>m = 2 kg, &nbsp; length = 22 cm, &nbsp; breadth = 11 cm, &nbsp; height = 7 cm</p></td></tr><tr><td></td><td colspan=\"5\"><p>F = w = m g = 2 × 10 = 20 N</p></td></tr><tr><td><p>(a)</p></td><td><p>Base area, A</p></td><td><p>= 22 cm \\(×\\) 11 cm</p></td><td></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td></td><td><p>= 242 cm<sup>2</sup></p></td><td></td><td></td><td><p>= \\(\\frac{20}{242 × {10}^{-4}}\\)</p></td></tr><tr><td></td><td></td><td><p>= 242 × (\\({10}^{-2}\\)m )<sup>2</sup></p></td><td></td><td></td><td><p>= <strong>826 Pa</strong></p></td></tr><tr><td></td><td></td><td><p>= <strong>242 ×</strong>\\({10}^{-4}\\)<strong> m</strong><strong><sup>2</sup></strong></p></td><td></td><td></td><td></td></tr><tr><td><p>(b)</p></td><td><p>Base area, A</p></td><td><p>= 7 cm × 11 cm</p></td><td></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td></td><td><p>= 77 cm<sup>2</sup></p></td><td></td><td></td><td><p>= \\(\\frac{20}{77 × {10}^{-4}}\\)</p></td></tr><tr><td></td><td></td><td><p>= 77 × (\\({10}^{-2}\\)m )<sup>2</sup></p></td><td></td><td></td><td><p>= <strong>2597 Pa</strong></p></td></tr><tr><td></td><td></td><td><p>= <strong>77 ×</strong>\\({10}^{-4}\\)<strong> m</strong><strong><sup>2</sup></strong></p></td><td></td><td></td><td></td></tr><tr><td><p>(b)</p></td><td><p>Base area, A</p></td><td><p>= 22 cm \\(×\\) 7 cm</p></td><td></td><td><p>p</p></td><td><p>= \\(\\frac{F}{A}\\)</p></td></tr><tr><td></td><td></td><td><p>= 154 cm<sup>2</sup></p></td><td></td><td></td><td><p>= \\(\\frac{20}{154 × {10}^{-4}}\\)</p></td></tr><tr><td></td><td></td><td><p>= 154 × (\\({10}^{-2}\\)m )<sup>2</sup></p></td><td></td><td></td><td><p>= <strong>1298 Pa</strong></p></td></tr><tr><td></td><td></td><td><p>= <strong>154 ×</strong>\\({10}^{-4}\\)<strong> m</strong><strong><sup>2</sup></strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','Rev.2','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong>We say that the density of iron is 7.9 g cm<sup>-3</sup>. Write this in kg m<sup>-3</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>1 kg = 10<sup>3</sup> g, &nbsp; 1 cm = 10<sup>-2</sup> m</p></td></tr><tr><td></td><td><p>Density</p></td><td><p>=</p></td><td><p>7.9 g cm<sup>-3</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>7.9 g cm<sup>-3</sup> \\(×\\frac{1 kg}{{10}^{3} g}×\\frac{1 {cm}^{3}}{{(10}^{-2} m{)}^{3}}\\) = <strong>7.9 </strong>\\(×{10}^{3}\\)<strong> kg m</strong><strong><sup>-3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','Eg.5','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A helium flying balloon has the size of 6 m radius. </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) Find the volume and the mass of helium. </p><p> &nbsp;  &nbsp; (b) Find the mass of air displaced by the balloon.</p><p> &nbsp;  &nbsp;      (\\(ρ\\) <sub>helium</sub> = 0.164 kg m<sup>-3</sup>, &nbsp;  &nbsp; \\(ρ\\) <sub>air</sub> = 1.3 kg m<sup>-3</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>r = 6 m &nbsp;  &nbsp; (a) m <sub>helium</sub> = ? &nbsp;  &nbsp; (b) m <sub>air</sub> = ?</p></td></tr><tr><td><p>(a)</p></td><td colspan=\"5\"><p>Volume, V = \\(\\frac{4}{3}\\) \\(π\\) r<sup>3</sup> = \\(\\frac{4}{3}\\) × 3.142 × 6<sup>3</sup> = 904.8 m<sup>3</sup></p></td></tr><tr><td></td><td><p>m <sub>helium</sub></p></td><td><p>= \\(ρ\\) <sub>helium</sub> × V</p></td><td><p>(b)</p></td><td><p>m <sub>air</sub></p></td><td><p>= \\(ρ\\) <sub>air</sub> × V</p></td></tr><tr><td></td><td></td><td><p>= 0.164 × 904.8</p></td><td></td><td></td><td><p>= 1.3 × 904.8</p></td></tr><tr><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= <strong>148.4 kg</strong></p></td><td></td><td></td><td><p>= <strong>1 176 kg</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','Eg.6','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A concrete slab 1.0 m by 0.5 m by 0.1 m has a mass of 120 kg. What is the density of the concrete?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>m = 120 kg, &nbsp; \\(ρ\\) = ?</p></td></tr><tr><td></td><td><p>V</p></td><td><p>= length \\(×\\) width \\(×\\) height</p></td><td></td><td><p>\\(ρ\\) </p></td><td><p>= \\(\\frac{m}{V}\\)</p></td></tr><tr><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= 1.0 m \\(×\\) 0.5 m \\(×\\) 0.1 m</p></td><td></td><td></td><td><p>= \\(\\frac{120}{0.05}\\)</p></td></tr><tr><td></td><td></td><td><p>= <strong>0.05 m</strong><strong><sup>3</sup></strong></p></td><td></td><td></td><td><p>= <strong>2 400 kg m</strong><strong><sup>-3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','Rev.3','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong>The relative density of sulphur is 2. Find the volume of 1 kg of sulphur. </p><p> &nbsp; (density of water = 1000 kg m<sup>-3</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>RD of Sulphur = 2, &nbsp; \\(ρ\\)<sub>water </sub> = 1000 kg m<sup>-3</sup>, &nbsp; m = 1 kg, &nbsp; V = ?</p></td></tr><tr><td></td><td><p>RD of sulphur</p></td><td><p>= \\(\\frac{{ ρ}_{sulphur}}{{ ρ}_{water}}\\)</p></td><td></td><td><p>\\(ρ\\) </p></td><td><p>= \\(\\frac{m}{V}\\)</p></td></tr><tr><td></td><td><p>\\({ ρ}_{sulphur}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= RD × \\({ ρ}_{water}\\)</p></td><td></td><td><p>V </p></td><td><p>= \\(\\frac{m}{ρ}\\)</p></td></tr><tr><td></td><td></td><td><p>= 2 × 1000</p></td><td></td><td></td><td><p>= \\(\\frac{1}{2000}\\)</p></td></tr><tr><td></td><td></td><td><p>= <strong>2000 kg m</strong><strong><sup>-3</sup></strong></p></td><td></td><td></td><td><p>= <strong>5 × 10</strong><strong><sup>-4</sup></strong><strong> m</strong><strong><sup>3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.6','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A mini-submarine has the total volume of 24 m<sup>3</sup>. Its mass is 2 000 kg. Can it carry another 3 000 kg?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>\\(ρ\\) = 1000 kg m<sup>-3</sup>, &nbsp; V = 24 m<sup>3</sup>, &nbsp; m<sub>sub</sub> = 2000 kg, &nbsp; m<sub>load</sub> = 3000 kgs</p></td></tr><tr><td></td><td><p>Maximum weight of water displaced, w</p></td><td><p>= m g</p></td></tr><tr><td></td><td></td><td><p>= \\(ρ\\) V g</p></td></tr><tr><td></td><td></td><td><p>= 1 000 × 24 × 10 = 240 000 N</p></td></tr><tr><td></td><td colspan=\"2\"><p>By Archimedes&#x27; principle,</p></td></tr><tr><td></td><td colspan=\"2\"><p>Upward thrust = weight of water displaced = 240 000 N</p></td></tr><tr><td></td><td><p>Total mass of submarine and load, m</p></td><td><p>= m<sub>sub</sub> + m<sub>load</sub></p></td></tr><tr><td></td><td></td><td><p>= 2 000 + 3 000 = 5 000 kg</p></td></tr><tr><td></td><td><p>Total weight of submarine and load, w</p></td><td><p>= m g</p></td></tr><tr><td></td><td></td><td><p>= 5 000 × 10 = 50 000 N</p></td></tr><tr><td></td><td colspan=\"2\"><p>Since, upward thrust &gt; total weight of submarine and load, it can carry another 3000 kg.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','Rev.4','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong>An alloy is made by mixing 360 g of copper, of density 9 g cm<sup>-3</sup>, with 80 g of iron, of density 8 g cm<sup>-3</sup>. Find the density of the alloy. Assuming the volume of each metal used does not change during mixing.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>For copper</p></td><td colspan=\"2\"><p>For iron</p></td></tr><tr><td></td><td colspan=\"3\"><p>m <sub>copper </sub>= 360 g</p></td><td colspan=\"2\"><p>m <sub>iron </sub>= 80 g</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\({ρ}_{copper}\\) = 9 g cm<sup>-3</sup></p></td><td colspan=\"2\"><p>\\({ρ}_{iron}\\) = 8 g cm<sup>-3</sup></p></td></tr><tr><td></td><td colspan=\"3\"><p>Since, \\(ρ= \\frac{m}{V}\\) </p></td><td colspan=\"2\"></td></tr><tr><td></td><td><p>V<sub>copper</sub></p></td><td colspan=\"2\"><p>= \\(\\frac{{m}_{ copper}}{{ρ }_{copper}}\\)</p></td><td><p>V<sub>iron</sub></p></td><td><p>= \\(\\frac{{m }_{iron}}{{ρ }_{iron}}\\)</p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= \\(\\frac{360}{9}\\)  = 40 cm<sup>3</sup></p></td><td></td><td><p>= \\(\\frac{80}{8}\\)  = 10 cm<sup>3</sup></p></td></tr><tr><td></td><td colspan=\"5\"><p>Mass of alloy, m = m<sub>copper</sub> + m<sub>iron</sub> = 360 + 80 = 440 g</p></td></tr><tr><td></td><td colspan=\"5\"><p>volume of alloy, V = V<sub>copper</sub> + V<sub>iron</sub> = 40 + 10 = 50 cm<sup>3</sup></p></td></tr><tr><td></td><td colspan=\"2\"><p>Density of alloy</p></td><td colspan=\"3\"><p>= \\(\\frac{mass of alloy}{volume of alloy}\\) </p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(ρ\\) </p></td><td colspan=\"3\"><p>= \\(\\frac{m}{V}\\) </p></td></tr><tr><td></td><td colspan=\"2\"></td><td colspan=\"3\"><p>= \\(\\frac{440}{50}\\)  </p></td></tr><tr><td></td><td colspan=\"2\"></td><td colspan=\"3\"><p>= 8.8 g cm<sup>-3</sup></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.5','4','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>One litre of milk (density 1.2 g cm<sup>-3</sup>) is mixed with 0.5 litre of water (density           1 g cm<sup>-3</sup>). What is the density of the mixture? Find the relative density of the mixture.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>For milk</p></td><td colspan=\"2\"><p>For water</p></td></tr><tr><td></td><td colspan=\"2\"><p>V <sub>milk </sub>= 1 L = 1000 cm<sup>3</sup></p></td><td colspan=\"2\"><p>V <sub>water </sub>= 0.5 L = 0.5 × 1000 = 500 cm<sup>3</sup></p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({ρ}_{milk}\\) = 1.2 g cm<sup>-3</sup></p></td><td colspan=\"2\"><p>\\({ρ}_{ water}\\) = 1 g cm<sup>-3</sup></p></td></tr><tr><td></td><td colspan=\"2\"><p>Since, \\(ρ= \\frac{m}{V}\\) </p></td><td colspan=\"2\"></td></tr><tr><td></td><td><p>m<sub> milk</sub></p></td><td><p>= \\({ρ}_{milk} ×\\) V<sub> milk</sub></p></td><td><p>m<sub> water</sub></p></td><td><p>= \\({ρ}_{water} ×\\) V<sub> water</sub></p></td></tr><tr><td></td><td></td><td><p>= 1.2 \\(×\\) 1000 = 1200 g</p></td><td></td><td><p>= 1 \\(×\\) 500 = 500 g</p></td></tr><tr><td></td><td colspan=\"4\"><p>Mass of alloy, m = m<sub>milk</sub> + m<sub>water</sub> = 1200 + 500 = 1700 g</p></td></tr><tr><td></td><td colspan=\"4\"><p>volume of alloy, V = V<sub>milk</sub> + V<sub>water</sub> = 1000 + 500 = 1500 cm<sup>3</sup></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Eg.1','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A child is pulling a toy car with a 10 N force. The direction of the force makes an angle of 20° with the horizontal plane. If the car moves 6 m, how much work does the child do?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>F = 10 N, &nbsp; \\(θ\\) = 20°, &nbsp; s = 6 m, &nbsp; W = ?</p></td></tr><tr><td></td><td><p>W</p></td><td><p>= F s cos </p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= 10 × 6 × cos 20°</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= <strong>56.38 J</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.1','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong>A woman pushes a child, who is riding a tricycle, with a 200 N force. The tricycle moves a distance of 2 m and the work done by the woman is 100 J. Find the angle between the force and the displacement.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>F = 200 N, &nbsp; s = 2 m, &nbsp; W = 100 J, &nbsp; \\(θ\\) = ?       </p></td></tr><tr><td></td><td><p>W</p></td><td><p>= F s cos </p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>100</p></td><td><p>= 200 × 2 × cos </p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>cos </p></td><td><p>= \\(\\frac{100}{400}\\)</p></td><td></td><td></td><td></td></tr><tr><td></td><td><p></p></td><td><p>= cos<sup>-1</sup> 0.25 = <strong>75</strong>\\(°\\)<strong> 31</strong>\\(''\\)</p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Eg.2','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>How much work is done when a box is pushed with a force of 20 N through horizontal distance of 3 m?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>F = 20 N, &nbsp; \\(θ\\) = 0° (F and s are same direction), &nbsp; s = 3 m, &nbsp; W = ?</p></td></tr><tr><td></td><td><p>W</p></td><td><p>= F s cos </p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= 20 × 3 × cos 0°</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= <strong>60 J</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','No.8','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A block of wood is placed on a rough horizontal plane. If the frictional force between the block and the plane is 6 N, what is the work done to moves the block through a distance of 1.5 m?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>s = 1.5 m, &nbsp; W = ? &nbsp; <strong>[OR]</strong></p></td></tr><tr><td></td><td colspan=\"2\"><p>Frictional Force, F = - 6 N,</p></td><td colspan=\"2\"><p>Applied Force, F = 6 N,</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(θ\\) = 180° (F and s are opposite direction)</p></td><td colspan=\"2\"><p>\\(θ\\) = 0° (F and s are same direction)</p></td></tr><tr><td></td><td><p>W</p></td><td><p>= F s cos </p></td><td><p>W</p></td><td><p>= F s cos </p></td></tr><tr><td></td><td></td><td><p>= (- 6) × 1.5 × cos 180°</p></td><td></td><td><p>= 6 × 1.5 × cos 0°</p></td></tr><tr><td></td><td></td><td><p>= <strong>9 J</strong></p></td><td></td><td><p>= <strong>9 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','No.10','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong>A weightlifter raising an object that weight is 500 N through a distance of 2 m. How much work is done?<strong> &nbsp; </strong></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>F = 500 N, &nbsp; \\(θ\\) = 0° (F and s are same direction), &nbsp; s = 2 m, W = ?</p></td></tr><tr><td></td><td><p>W</p></td><td><p>=</p></td><td><p>F s cos </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>500 \\(×\\) 2 \\(×\\) cos 0°</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>1000 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','No.9','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A student lifts a box weighing 50 N through a vertical height 1.1 m, and then walks horizontally for 2.0 m at constant speed while holding the box. What is the work done by the student on the box?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>F = w = 50 N, &nbsp;  &nbsp; vertical height = 1.1 m, &nbsp; horizontal distance = 2 m</p></td></tr><tr><td></td><td colspan=\"4\"><p>W = ?</p></td></tr><tr><td></td><td colspan=\"2\"><p>While lifting the box,</p></td><td colspan=\"2\"><p>walking, while holding the box,</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(θ\\) = 0° (F and s are same direction)</p></td><td colspan=\"2\"><p>\\(θ\\) = 90° (F and s are perpendicular)</p></td></tr><tr><td></td><td><p>W</p></td><td><p>= F s cos </p></td><td><p>W</p></td><td><p>= F s cos </p></td></tr><tr><td></td><td></td><td><p>= 50 × 1.1 × cos 0°</p></td><td></td><td><p>= 50 \\(×\\) 2 \\(×\\) cos 90°</p></td></tr><tr><td></td><td></td><td><p>= <strong>55 J</strong></p></td><td></td><td><p>= <strong>0</strong></p></td></tr><tr><td></td><td colspan=\"4\"><p>The work done by the student on the box = 55 + 0 = <strong>55 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','Eg.3','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A truck with mass 1 500 kg is traveling with a speed of 20 m s<sup>-1</sup>. What is the kinetic energy of the truck?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 1 500 kg, &nbsp;  &nbsp; v = 20 m s<sup>-1</sup>, &nbsp;  &nbsp; KE = ?</p></td></tr><tr><td></td><td><p>KE</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sup>2</sup> = \\(\\frac{1}{2}\\) × 1500 × 20<sup>2</sup> = <strong>3 × 10</strong><strong><sup>5 </sup></strong><strong>J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.1','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A car with a mass of 800 kg travels at a speed of 20 m s<sup>-1</sup>. What is its kinetic energy?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 800 kg,  &nbsp;  &nbsp; v = 20 m s<sup>-1</sup>, &nbsp;  &nbsp; KE = ?</p></td></tr><tr><td></td><td><p>KE</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) × 800 × 20 × 20 = 1.6 × 10<sup>5 </sup>J</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.5','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Calculate the kinetic energy of </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) 1 kg mass of a toy car moving at 2 m s<sup>-1</sup> </p><p> &nbsp;  &nbsp; (b) 2 g (0.002 kg) bullet travelling at 400 m s<sup>-1</sup> </p><p> &nbsp;  &nbsp; (c) 500 kg car travelling at 72 km h<sup>-1</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p><figure><img src=\"cal-media/g11-g10-image23.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>(a) m = 1 kg, &nbsp; v = 2 m s<sup>-1</sup>, &nbsp; KE = ?</p></td><td colspan=\"2\"><p>(c) m &nbsp; = 500 kg,</p></td></tr><tr><td></td><td><p>KE</p></td><td><p>= \\(\\frac{1}{2}\\) m v<sup>2</sup></p></td><td colspan=\"2\"><p> &nbsp; v = 72 km h<sup>-1</sup></p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{1}{2}\\) × 1 × 2<sup>2</sup> </p></td><td colspan=\"2\"><p> &nbsp; = 72 × 10<sup>3</sup> m h<sup>-1</sup> × \\(\\frac{1 h}{3600 s}\\)</p></td></tr><tr><td></td><td></td><td><p><strong>= 2</strong><strong><sup> </sup></strong><strong>J</strong></p></td><td colspan=\"2\"><p> &nbsp; = <strong>20 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"2\"><p>(b) m = 2 g = 2 \\(×\\) 10<sup>-3</sup> kg, &nbsp; v = 400 m s<sup>-1</sup></p></td><td><p>KE</p></td><td><p>= \\(\\frac{1}{2}\\) m v<sup>2</sup></p></td></tr><tr><td></td><td><p>KE</p></td><td><p>= \\(\\frac{1}{2}\\) m v<sup>2</sup></p></td><td></td><td><p>= \\(\\frac{1}{2}\\) × 500 × 20<sup>2</sup></p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{1}{2}\\) × 2 \\(×\\) 10<sup>-3</sup> × 400<sup>2</sup></p></td><td></td><td><p>= <strong>1 × 10</strong><strong><sup>5</sup></strong><strong> J</strong></p></td></tr><tr><td></td><td></td><td><p>= <strong>160 J</strong></p></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.6','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong>(a) What is the velocity of an object of mass 1 kg which has 200 J of kinetic energy?</p><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure><strong> &nbsp; </strong>(b) Calculate the potential energy of a 5 kg mass when it is (i) 3 m, (ii) 6 m, above the ground. (g = 10 N kg<sup>-1</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>(a) m = 1 kg, &nbsp; KE = 200 J, &nbsp; v = ?</p></td><td colspan=\"3\"><p>(b) m = 5 kg, &nbsp; g = 10 N kg<sup>-1</sup></p></td></tr><tr><td></td><td><p>KE</p></td><td><p>= \\(\\frac{1}{2}\\) m v<sup>2</sup></p></td><td><p>(i)</p></td><td><p>PE</p></td><td><p>= m g h</p></td></tr><tr><td></td><td><p>200</p></td><td><p>= \\(\\frac{1}{2}\\) × 1 × v<sup>2</sup></p></td><td></td><td></td><td><p>= 5 × 10 × 3 = <strong>150 J</strong></p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>= 400 </p></td><td><p>(ii)</p></td><td><p>PE</p></td><td><p>= m g h</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= <strong>20 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td></td><td><p>= 5 × 10 × 6 = <strong>300 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','Eg.4','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A girl lifts her school bag of mass 3 kg from the floor onto her lap through a height of 0.5 m. What is the gravitational potential energy gained by the bag?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 3 kg, &nbsp; h = 0.5 m, &nbsp; g = 10 m s<sup>-2</sup>, &nbsp; PE = ?</p></td></tr><tr><td></td><td><p>PE</p></td><td><p>=</p></td><td><p>m g h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>3 × 10 × 0.5 = <strong>15 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.11','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong>A man lifts a brick of mass 5 kg from the floor to a shelf 3 metres high. How much work is done?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 5 kg, &nbsp; g = 10 m s<sup>-2</sup>, &nbsp; h = 3 m, &nbsp; W = ?</p></td></tr><tr><td></td><td><p>W</p></td><td><p>=</p></td><td><p>m g h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>5 × 10 × 3 = <strong>150 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','Eg.5','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>How much more gravitational potential energy does a 20 kg box have when it is moved from a shelf 0.3 m height to a shelf 1.8 m height?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 20 kg, &nbsp; initial height, h<sub>0</sub> = 0.3 m, &nbsp; final height, h = 1.8 m</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\(∆\\)PE = ? &nbsp; g = 10 m s<sup>-2</sup>, &nbsp;  &nbsp; \\(∆\\)h = h – h<sub>0</sub> = 1.8 – 0.3 = 1.5 m</p></td></tr><tr><td></td><td><p>\\(∆\\)PE</p></td><td><p>=</p></td><td><p>m g \\(∆\\)h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>20 × 10 × 1.5 = <strong>300 J</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.2','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>What is the change in potential energy of a flower pot of mass 2 kg that falls from a balcony? The height of the balcony from the ground is 20 m. What happens to this energy?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 2 kg, &nbsp; initial height, h<sub>0</sub> = 20 m, &nbsp; final height, h = 0 m (ground)</p></td></tr><tr><td></td><td colspan=\"3\"><p>\\(∆\\)PE = ? &nbsp; g = 10 m s<sup>-2</sup>, &nbsp;  &nbsp; \\(∆\\)h = h<sub>0</sub> – h = 20 – 0 = 20 m</p></td></tr><tr><td></td><td><p>\\(∆\\)PE</p></td><td><p>=</p></td><td><p>m g \\(∆\\)h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>2 × 10 × 20 = <strong>400 J</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>When the flower pot strikes the ground, the potential energy will change to kinetic energy.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.3','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>What is the change in potential energy if you move a brick of 1.5 kg mass through a distance of 0.4 m on a horizontal table?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 1.5 kg, &nbsp; initial height, h<sub>0</sub> = h (horizontal) &nbsp; \\(∆\\)h = h – h<sub>0</sub> = 0</p></td></tr><tr><td></td><td><p>\\(∆\\)PE</p></td><td><p>=</p></td><td><p>m g \\(∆\\)h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>1.5 × 10 × 0 = <strong>0</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>There is no change in PE because of no change in vertical height.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','Rev.2','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Give some examples of electrical energy transforming into light energy.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Electric bulbs, electric lamps are some examples of electrical energy transforming into light energy.</p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Rev.3','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Why are the units of energy and work the same?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Energy is the capacity to do work. Whenever work is done on the body, the energy gained by the body is equal to the amount of work done on it. So, the units of energy and work are the same.</p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','Rev.4','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Write down the law of conservation of energy. Identify this law as being a fundamental law or not, and explain your answer.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong>Conservation of Energy</strong></p><p> &nbsp; The total energy of an isolated system is constant. </p><p> &nbsp; This law is fundamental law because the total energy of the universe is constant. It is true for the whole of universe.</p></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','Eg.6','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The figure shows the heights above the ground of some points on the track of a roller coaster. The speed of the carriage at A is 10 m s<sup>-1</sup>. What is the speed of the carriage at B and C? The friction and air resistance are assumed to be negligible.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>At A</p></td><td><p>At B</p></td><td><p>At C</p></td></tr><tr><td></td><td colspan=\"2\"><p>v<sub>A</sub> = 10 m s<sup>-1</sup></p></td><td><p>v<sub>B</sub> = ?</p></td><td><p>v<sub>C</sub> = ?</p></td></tr><tr><td></td><td colspan=\"2\"><p>h<sub>A</sub><sub> </sub>= 11.2 m</p></td><td><p>h<sub>B</sub> = 0</p></td><td><p>h<sub>C</sub> = 15.4 m</p></td></tr><tr><td></td><td colspan=\"4\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub>B</sub> + PE<sub>B</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>KE<sub>A</sub> + PE<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>B</sub><sup>2</sup> + m g h<sub>B</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) m v<sub>A</sub><sup>2</sup> + m g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>B</sub><sup>2</sup> + 0</p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) m v<sub>A</sub><sup>2</sup> + m g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>B</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) m v<sub>A</sub><sup>2</sup> + m g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>B</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\)  v<sub>A</sub><sup>2</sup> + g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>B</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>[ \\(\\frac{1}{2}\\) × 10<sup>2</sup>] + [ 10 × 11.2]</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>B</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>162</p></td></tr><tr><td></td><td><p>v<sub>B</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>324</p></td></tr><tr><td></td><td><p>v<sub>B</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p><strong>18 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td><p>KE<sub>C</sub> + PE<sub>C</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>KE<sub>A</sub> + PE<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>C</sub><sup>2</sup> + m g h<sub>C</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) m v<sub>A</sub><sup>2</sup> + m g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) v<sub>C</sub><sup>2</sup> + g h<sub>C</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) v<sub>A</sub><sup>2</sup> + g h<sub>A</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>C</sub><sup>2</sup> + [ 10 × 15.4] </p></td><td><p>=</p></td><td colspan=\"2\"><p>[ \\(\\frac{1}{2}\\) × 10<sup>2</sup>] + [ 10 × 11.2]</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>C</sub><sup>2</sup> + 154 </p></td><td><p>=</p></td><td colspan=\"2\"><p>50 + 112</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\)  v<sub>C</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>162 - 154</p></td></tr><tr><td></td><td><p>v<sub>C</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>2 × 8 = 16</p></td></tr><tr><td></td><td><p>v<sub>C</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p><strong>4 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','Eg.7','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A parcel of mass 4 kg slides down a smooth curve ramp as shown in figure. What is the speed of the parcel when it reaches the bottom? </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>At top</p></td><td><p>At bottom</p></td></tr><tr><td></td><td colspan=\"2\"><p>h <sub>top</sub> = 5 m</p></td><td><p>h<sub>bottom</sub> = 0</p></td></tr><tr><td></td><td colspan=\"2\"><p>v<sub>top</sub> = 0 (maximum height)</p></td><td><p>v<sub>bottom</sub> = ?</p></td></tr><tr><td></td><td colspan=\"3\"></td></tr><tr><td></td><td colspan=\"3\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub>bottom</sub> + PE<sub>bootom</sub></p></td><td><p>=</p></td><td><p>KE<sub>top</sub> + PE<sub>top</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup> + m g h<sub>bootom</sub> </p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sub>top</sub><sup>2</sup> + m g h<sub>top</sub> </p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td><p>m g h<sub>top</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td><p> 10 \\(×\\) 5</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td><p>50 </p></td></tr><tr><td></td><td><p>v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td><p>100</p></td></tr><tr><td></td><td><p>v<sub>bottom</sub> </p></td><td><p>=</p></td><td><p><strong>10 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','No.12','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong>A tennis ball which is thrown vertically upwards reaches the height of 50 m. Find the initial velocity of the ball. (Neglect air resistance.)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>At top</p></td><td><p>At bottom</p></td></tr><tr><td></td><td colspan=\"3\"><p>h <sub>top</sub> = 50 m</p></td><td><p>h<sub>bottom</sub> = 0</p></td></tr><tr><td></td><td colspan=\"3\"><p>v<sub>top</sub> = 0 (maximum height)</p></td><td><p>v<sub>bottom</sub> = ?</p></td></tr><tr><td></td><td colspan=\"4\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub>bottom</sub> + PE<sub>bootom</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p>KE<sub>top</sub> + PE<sub>top</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup> + m g h<sub>bootom</sub> </p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(\\frac{1}{2}\\) m v<sub>top</sub><sup>2</sup> + m g h<sub>top</sub> </p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>m g h<sub>top</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) × v<sub>bottom</sub><sup>2</sup> </p></td><td><p>=</p></td><td colspan=\"2\"><p>10 × 50</p></td></tr><tr><td></td><td><p>v<sub>bottom</sub><sup>2</sup></p></td><td><p>=</p></td><td colspan=\"2\"><p>1000</p></td></tr><tr><td></td><td><p>v<sub>bottom</sub></p></td><td><p>=</p></td><td colspan=\"2\"><p><strong>31.62 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','No.4','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A ball is thrown vertically upwards with a velocity of 10 m s<sup>-1</sup>. What is the maximum height it can reach?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>At top</p></td><td colspan=\"2\"><p>At bottom</p></td></tr><tr><td></td><td><p>h <sub>top</sub> = ?</p></td><td colspan=\"2\"><p>h<sub>bottom</sub> = 0</p></td></tr><tr><td></td><td><p>v<sub>top</sub> = 0 (maximum height)</p></td><td colspan=\"2\"><p>v<sub>bottom</sub> = 10 m s<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"3\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub>top</sub> + PE<sub>top</sub></p></td><td><p>=</p></td><td><p>KE<sub>bottom</sub> + PE<sub>bottom</sub></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{2}\\) m v<sub>top</sub><sup>2</sup> + m g h<sub>top</sub> </p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup> + m g h<sub>bottom</sub></p></td></tr><tr><td></td><td><p>m g h<sub>top</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sub>bottom</sub><sup>2</sup></p></td></tr><tr><td></td><td><p>10 × h<sub>top</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) × 10<sup>2</sup></p></td></tr><tr><td></td><td><p>h<sub>top</sub></p></td><td><p>=</p></td><td><p><strong>5 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,22,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.7','5','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A 100 g steel ball falls from a height of 1.8 m onto a metal plate and rebounds to a height of 1.25 m. Find </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) potential energy of the ball before the fall (g = 10 m s<sup>-2</sup>),</p><p> &nbsp;  &nbsp; (b) its kinetic energy as it hits the plate, </p><p> &nbsp;  &nbsp; (c) its velocity on hitting the plate,</p><p> &nbsp;  &nbsp; (d) the kinetic energy as it leaves the plate on the rebound, </p><p> &nbsp;  &nbsp; (e) its velocity of rebound.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>m = 100 g = 100 \\(×\\) 10<sup>-3</sup> kg = 0.1 kg, &nbsp;  &nbsp; g = 10 m s<sup>-2</sup> </p></td></tr><tr><td><p>(a)</p></td><td colspan=\"3\"><p>before the ball fall, &nbsp; PE<sub> Top</sub> = ? &nbsp; h = 1.8 m     </p></td></tr><tr><td></td><td><p>PE <sub>Top</sub></p></td><td><p>=</p></td><td><p>m g h</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.1 \\(×\\) 10 \\(×\\) 1.8 = <strong>1.8 J</strong> </p></td></tr><tr><td><p>(b)</p></td><td colspan=\"3\"><p>while hit the plate, KE<sub> bottom</sub> = ?</p></td></tr><tr><td></td><td colspan=\"3\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub> bottom</sub></p></td><td><p>=</p></td><td><p>PE <sub>Top</sub> = <strong>1.8 J</strong></p></td></tr><tr><td><p>(c)</p></td><td colspan=\"3\"><p>while hit the plate, v = ?</p></td></tr><tr><td></td><td><p>KE<sub> bottom</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sup>2</sup></p></td></tr><tr><td></td><td><p>1.8</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) \\(×\\) 0.1 v<sup>2</sup></p></td></tr><tr><td></td><td><p>v<sup>2</sup></p></td><td><p>=</p></td><td><p>\\(\\frac{1.8 × 2}{0.1}\\) = 36</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p><strong>6 m s</strong><strong><sup>-1</sup></strong><strong>  </strong></p></td></tr><tr><td><p>(d)</p></td><td colspan=\"3\"><p>When the ball leaves the plate on the <strong>rebound</strong>, KE<sub> bottom R</sub> = ? &nbsp; h<sub>R</sub> = 1.25 m</p></td></tr><tr><td></td><td colspan=\"3\"><p>By the law of conservation of energy, </p></td></tr><tr><td></td><td><p>KE<sub> bottom R</sub></p></td><td><p>=</p></td><td><p>PE <sub>Top R</sub> </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p> m g h<sub>R</sub></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>0.1 × 10 × 1.25 = <strong>1.25 J</strong></p></td></tr><tr><td><p>(e)</p></td><td colspan=\"3\"><p>while rebound, v<sub>R</sub> = ?</p></td></tr><tr><td></td><td><p>KE<sub> bottom R</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) m v<sub>R</sub> <sup>2</sup></p></td></tr><tr><td></td><td><p>1.25</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{2}\\) \\(×\\) 0.1 v<sub>R</sub> <sup>2</sup></p></td></tr><tr><td></td><td><p>v<sub>R</sub> <sup>2</sup></p></td><td><p>=</p></td><td><p>\\(\\frac{1.25 × 2}{0.1}\\) = 25</p></td></tr><tr><td></td><td><p>v<sub>R</sub></p></td><td><p>=</p></td><td><p><strong>5 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.1','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Complete the sentences below using words from the following list. </strong></em></p><p><em><strong>expansion, temperature, voltage</strong></em></p><p> &nbsp;  &nbsp; (a) The degree of hotness of an object is a measure of its ------. </p><p> &nbsp;  &nbsp; (b) The liquid-in-glass thermometer makes use of the ------ of the liquid when it ----- &nbsp; changes.</p><p> &nbsp;  &nbsp; (c) In a thermocouple thermometer, a change of ------ causes its ------ to  &nbsp; change.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) &nbsp; temperature. &nbsp; (b) expansion, temperature &nbsp; (c) temperature, voltage </p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.3','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Why is the temperature range of a clinical thermometer from 35 </strong></em><em><strong></strong></em><em><strong>C to 42 </strong></em><em><strong></strong></em><em><strong>C?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The temperature range of a clinical thermometer from 35 C to 42 C because the temperature of human body normally does not below 35 C or above 42 C.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','No.2','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong>(a) A liquid-in-glass clinical thermometer is marked with a scale from 32 C to 42 C which covers a distance of 80 mm. A liquid-in-glass laboratory thermometer is marked with a scale from 0 C to 100 C, which covers a distance of 160 mm. State and explain which thermometer; (i) has the greater range, (ii) is more sensitive.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>(i) &nbsp; Laboratory thermometer has the greater range.</p></td></tr><tr><td></td><td><p> &nbsp; The range of laboratory thermometer (0\\(℃\\) to 100 \\(℃\\) ) = 100 \\(℃\\)</p></td></tr><tr><td></td><td><p> &nbsp; The range of clinical thermometer (32\\(℃\\) to 42 \\(℃\\) ) = 10 \\(℃\\)</p></td></tr><tr><td></td><td><p>(ii) &nbsp; Clinical thermometer is more sensitive. (scale ပြောင်းလဲမှုကို သိလွယ်မြင်လွယ်သည်)</p></td></tr><tr><td></td><td><p> &nbsp; Sensitivity of clinical thermometer = \\(\\frac{80 mm}{10 ℃}\\) = 8 mm \\({℃}^{-1}\\)</p></td></tr><tr><td></td><td><p> &nbsp; Sensitivity of laboratory thermometer = \\(\\frac{160 mm}{100 ℃}\\) = 1.6 mm \\({℃}^{-1}\\)</p></td></tr></tbody></table></div><p><strong> &nbsp; </strong>(b) The following results were obtained when the voltage of a thermocouple thermometer was measured at different temperatures.</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>Voltage (millivolt)</p></td><td><p>0</p></td><td><p>1.4</p></td><td><p>2.8</p></td><td><p>4.3</p></td><td><p>5.7</p></td><td><p>6.9</p></td></tr><tr><td><p>Temperature (C)</p></td><td><p>0</p></td><td><p>20</p></td><td><p>40</p></td><td><p>60</p></td><td><p>80</p></td><td><p>100</p></td></tr></tbody></table></div><p> &nbsp; (i) Plot a graph of the voltage on the y-axis against temperature in C on the x-axis. </p><p> &nbsp; (ii) Use the graph to determine the voltage at 50 C and the temperature at 5.0 mV.</p><p>(ii) From graph, </p><p>The voltage at 50 C is <strong>3.5 mV</strong>.</p><p>The temperature at 5 mV is <strong>71</strong>\\(℃\\).</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Rev.4','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong>What temperature on the Celsius scale corresponds to 104 F, the body temperature of the person who is gravely ill?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T<sub>F</sub> = 104 F</p></td></tr><tr><td></td><td><p>T<sub>C</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (T<sub>F</sub> – 32)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (104 – 32) = <strong>40 </strong><strong></strong><strong>C</strong></p></td></tr></tbody></table></div><p><strong>Eg.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Normal body temperature is 98.6 F. What is the temperature in Celsius?</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T<sub>F</sub> = 98.6  F</p></td></tr><tr><td></td><td><p>T<sub>C</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (T<sub>F</sub> – 32)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (98.6 – 32) = <strong>37.0 </strong><strong></strong><strong>C</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Eg.1','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The room temperature is found to be 27 C. What is the temperature in kelvin?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T<sub>C</sub> = 27 C</p></td></tr><tr><td></td><td><p>T<sub>K</sub></p></td><td><p>=</p></td><td><p>T<sub>C</sub> + 273 = 27 + 273 = <strong>300 K</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Eg.2','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The lowest air temperature recorded in the world is 184 K. This temperature was measured in Antarctica in 1983. What is the temperature in degree Celsius?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T<sub>K</sub> = 184 K</p></td></tr><tr><td></td><td><p>T<sub>K</sub></p></td><td><p>=</p></td><td><p>T<sub>C</sub> + 273</p></td></tr><tr><td></td><td><p>T<sub>C</sub></p></td><td><p>=</p></td><td><p>T<sub>K</sub> – 273 = 184 – 273 = <strong>- 89 </strong><strong></strong><strong>C</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.5','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>If the temperature of a room is found to be 30 C, what is the temperature as measured on Kelvin scale?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T<sub>C</sub> = 30 C</p></td></tr><tr><td></td><td><p>T<sub>K</sub></p></td><td><p>=</p></td><td><p>T<sub>C</sub> + 273</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>30 + 273 = <strong>303 K</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.7','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>At what temperatures are the readings on a Fahrenheit and Celsius scales the same? </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Let, T<sub>C</sub> = T<sub>F</sub> = T</p></td></tr><tr><td></td><td><p>T<sub>C</sub></p></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (T<sub>F</sub> – 32) </p></td></tr><tr><td></td><td><p>T </p></td><td><p>=</p></td><td><p>\\(\\frac{5}{9}\\) (\\(x\\) – 32)</p></td></tr><tr><td></td><td><p>9 T</p></td><td><p>= </p></td><td><p>5 (\\(x\\) – 32)</p></td></tr><tr><td></td><td><p>9<em> </em>T</p></td><td><p>=</p></td><td><p>5<em> </em>\\(x\\) – 160</p></td></tr><tr><td></td><td><p>4<em> </em>T</p></td><td><p>=</p></td><td><p>- 160</p></td></tr><tr><td></td><td><p>T </p></td><td><p>=</p></td><td><p>- 40</p></td></tr><tr><td></td><td><p>T<sub>C</sub></p></td><td><p>=</p></td><td><p>- 40 C, &nbsp; T<sub>F</sub> = - 40 F</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.3','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>A solid expands when heated. What happen to its (i) mass, (ii) volume, and </strong></em><em><strong>      </strong></em><em><strong>(iii) density?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(i) mass does not change, &nbsp; (ii) volume increases, &nbsp; (iii) density decrease.</p></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','Eg.4','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The length of a metal bar having coefficient of linear expansion </strong></em><em><strong></strong></em><em><strong> is </strong></em>\\(l\\)<em><strong> at the temperature T. What is the length of that metal bar at the temperature T + </strong></em><em><strong></strong></em><em><strong>T?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>temperature = T</p></td><td><p>length = \\(l\\)</p></td></tr><tr><td></td><td colspan=\"3\"><p>change in temperature = \\(∆\\)T</p></td><td><p>change in length = \\(∆l\\) = \\(α l ∆\\)T</p></td></tr><tr><td></td><td colspan=\"4\"><p>The length of the metal bar at the temperature T + T</p></td></tr><tr><td></td><td><p>\\(l''\\) </p></td><td><p>=</p></td><td colspan=\"2\"><p>\\(l\\) + \\(∆l\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"2\"><p>\\(l\\) + \\(α l ∆\\)T</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td colspan=\"2\"><p>\\(l\\) (1 + \\(α ∆\\)T) </p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.4','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>If the unit of the coefficient of linear expansion is changed from per K to per </strong></em><em><strong></strong></em><em><strong>F, does the numerical value change?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Since, \\(α= \\frac{∆l}{l}\\)×\\(\\frac{1}{∆T}\\) . &nbsp; The unit of \\(α\\) can be K<sup>-1</sup> (or) \\({℃}^{-1}\\) (or) \\({℉}^{-1}\\), come from \\(∆T\\).</p><p> &nbsp;  &nbsp; \\(∆T\\) = 1 K = 1 \\(℃\\) = 1.8 \\(℉\\)</p><p> &nbsp;  &nbsp; If the unit of the coefficient of linear expansion is changed from per K to per F numerical value will change. &nbsp; သိထားရန် [ K to \\(℃\\) \\(→\\) numerical value ပြောင်းလဲမှာမဟုတ်]</p></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','Eg.3','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>One roadbed of a steel bridge is 12.80 m long. If the temperature varies from 25 C to 35 C during a day, what is the difference in lengths at those temperatures? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(The road is supported by steel girders. For steel,  = 1.27  10<sup>-5</sup> K<sup>-1</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\(l\\) = 12.80 m, &nbsp; T<sub>2</sub> = 35 \\(℃\\) , &nbsp; T<sub>1</sub> = 25 C, &nbsp; \\(α\\) = 1.27  10<sup>-5</sup> K<sup>-1</sup>, &nbsp; \\(∆l\\) = ?</p></td></tr><tr><td></td><td><p>\\(∆\\)T</p></td><td><p>= T<sub>2</sub> – T<sub>1</sub></p></td><td><p>\\(∆l\\) </p></td><td><p>= \\(α l ∆\\)T</p></td></tr><tr><td></td><td></td><td><p>= 35 – 10</p></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td><p>= 1.27  10<sup>-5</sup><sup> </sup>\\(×\\)<sup> </sup>12.8 \\(×\\) 10</p></td></tr><tr><td></td><td></td><td><p>= <strong>10 </strong><strong></strong><strong>C = 10 K</strong></p></td><td></td><td><p>= <strong>0.00 162 m (or) 0.162 cm</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.8','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A steel railroad track is 20 m long at 20 C. How much longer is it at 40 C? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(The coefficient of linear expansion of steel is 1.27  10<sup>-5</sup> K<sup>-1</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\(l\\) = 20 m, &nbsp; T<sub>1</sub> = 20 C, &nbsp; T<sub>2</sub> = 40 C, &nbsp; \\(α\\) = 1.27  10<sup>-5</sup> K<sup>-1</sup>, &nbsp; \\(∆ l\\) = ?</p></td></tr><tr><td></td><td><p>\\(∆\\)T</p></td><td><p>= T<sub>2</sub> – T<sub>1</sub></p></td><td><p>\\(∆l\\) </p></td><td><p>= \\(α l ∆\\)T</p></td></tr><tr><td></td><td></td><td><p>= 40 – 20</p></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td><p>= 1.27 × 10<sup>-5</sup> × 20 × 20 </p></td></tr><tr><td></td><td></td><td><p>= <strong>20 </strong><strong></strong><strong>C = 20 K</strong></p></td><td></td><td><p>= <strong>0.00 508 m (or) 0.508 cm</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.9','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A steel railroad track is 30 m long at 0 C. How much shorter is it at -20 C? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(The coefficient of linear expansion of steel is 1.27  10<sup>-5</sup> K<sup>-1</sup>)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\(l\\) = 30 m, &nbsp; T<sub>1</sub> = - 20 C, &nbsp; T<sub>2</sub> = 0 C, &nbsp; \\(α\\) = 1.27  10<sup>-5</sup> K<sup>-1</sup>, &nbsp; \\(∆ l\\) = ?</p></td></tr><tr><td></td><td><p>\\(∆\\)T</p></td><td><p>= T<sub>2</sub> – T<sub>1</sub></p></td><td><p>\\(∆l\\) </p></td><td><p>= \\(α l ∆\\)T</p></td></tr><tr><td></td><td></td><td><p>= 0 – (– 20)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image6.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td><p>= 1.27 × 10<sup>-5</sup> × 30 × 20 </p></td></tr><tr><td></td><td></td><td><p>= <strong>20 </strong><strong></strong><strong>C = 20 K</strong></p></td><td></td><td><p>= <strong>0.00 762 m (or) 0.762 cm</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.10','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong>A heat-resistant glass at 15 C is fully filled with 250 cm<sup>3</sup> of glycerine. If the temperature increases to 25 C how much glycerine overflows? The coefficient of volume expansion of glycerine is 5.1  10<sup>-4</sup> K<sup>-1</sup> and that of glass is 0.09  10<sup>-4</sup> K<sup>-1</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>For glycerine</p></td><td colspan=\"3\"><p>For glass</p></td></tr><tr><td></td><td colspan=\"2\"><p>V<sub>gly</sub> = 250 cm<sup>3</sup></p></td><td colspan=\"3\"><p>V<sub>glass</sub> = 250 cm<sup>3</sup></p></td></tr><tr><td></td><td colspan=\"2\"><p>\\({γ}_{gly}\\) = 5.1  10<sup>-4</sup> K<sup>-1</sup></p></td><td colspan=\"3\"><p>\\({γ}_{glass}\\) = 0.09  10<sup>-4</sup> K<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"5\"><p>T<sub>1</sub> = 15 C, &nbsp; T<sub>2</sub> = 25 C</p></td></tr><tr><td></td><td colspan=\"5\"><p>\\(∆\\)T = T<sub>2</sub> – T<sub>1</sub> = 25 – 15 = <strong>10 </strong><strong></strong><strong>C = 10 K</strong></p></td></tr><tr><td></td><td><p>\\(∆\\)V<sub>gly</sub></p></td><td colspan=\"2\"><p>= \\({γ}_{gly}\\) V<sub>gly</sub><sub> </sub>\\(∆\\)T</p></td><td><p>\\(∆\\)V<sub>glass</sub></p></td><td><p>= \\({γ}_{glass}\\) V<sub>glass </sub>\\(∆\\)T</p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= 5.1  10<sup>-4</sup> \\(×\\) 250 \\(×\\) 10</p></td><td></td><td><p>= 0.09  10<sup>-4</sup> \\(×\\) 250 \\(×\\) 10</p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= <strong>1.275 cm</strong><strong><sup>3</sup></strong></p></td><td></td><td><p>= <strong>0.0225 cm</strong><strong><sup>3</sup></strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>Overflow amount of glycerine = \\(∆\\)V<sub>gly</sub> - \\(∆\\)V<sub>glass</sub> = 1.275 – 0.0225 = <strong>1.2525 cm</strong><strong><sup>3</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.6','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The coefficient of volume expansion of Pyrex glass is one-third that of ordinary glass. Which glass can stand more thermal strain?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Pyrex glass can stand more thermal strain than ordinary glass. Lower coefficient of volume expansion means less expansion and contraction with temperature changes. A beaker made of Pyrex glass will not break when boiling water is poured into it, while a tumbler made of ordinary glass is likely to crack.</p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Eg.5','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The area of a metal plate is A</strong></em><em><strong><sub>1</sub></strong></em><em><strong> at the temperature T</strong></em><em><strong><sub>1</sub></strong></em><em><strong> and A</strong></em><em><strong><sub>2</sub></strong></em><em><strong> at T</strong></em><em><strong><sub>2</sub></strong></em><em><strong>. If T</strong></em><em><strong><sub>2</sub></strong></em><em><strong> &gt; T</strong></em><em><strong><sub>1</sub></strong></em><em><strong>, obtain the relation between A</strong></em><em><strong><sub>1</sub></strong></em><em><strong> and A</strong></em><em><strong><sub>2</sub></strong></em><em><strong>. The coefficient of area expansion of the metal is </strong></em><em><strong></strong></em><em><strong>.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>At temperature = T<sub>1</sub> &nbsp;  &nbsp; area = A<sub>1</sub></p></td></tr><tr><td></td><td colspan=\"3\"><p>At temperature = T<sub>2</sub> &nbsp;  &nbsp; area = A<sub>2</sub></p></td></tr><tr><td></td><td colspan=\"3\"><p>Increase in temperature, \\(Δ\\)T = T<sub>2</sub> – T<sub>1</sub></p></td></tr><tr><td></td><td colspan=\"3\"><p>Increase in area,  \\(Δ\\)A = A<sub>2</sub> – A<sub>1</sub></p></td></tr><tr><td></td><td><p>\\(∆A\\) </p></td><td><p>=</p></td><td><p>\\(β A ∆\\)T</p></td></tr><tr><td></td><td><p>A<sub>2</sub> – A<sub>1</sub></p></td><td><p>=</p></td><td><p>\\(β {A}_{1}\\)(T<sub>2</sub> – T<sub>1</sub>)</p></td></tr><tr><td></td><td><p>A<sub>2</sub></p></td><td><p>=</p></td><td><p>\\(β {A}_{1}\\)(T<sub>2</sub> – T<sub>1</sub>) + A<sub>1</sub></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>A<sub>1</sub> [ \\(β\\) (T<sub>2</sub> – T<sub>1</sub>) + 1]</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','Rev.5','6','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Obtain the relationship between the coefficient of linear expansion and the coefficient of area expansion of a substance.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Initial area = A</p></td><td colspan=\"3\"><p>= \\({l}^{2}\\)</p></td></tr><tr><td></td><td><p>Final area = A<sub>2</sub></p></td><td colspan=\"3\"><p>= (\\(l\\) + \\(Δl\\))<sup>2</sup></p></td></tr><tr><td></td><td></td><td colspan=\"3\"><p>= \\({l}^{2}\\) + 2 \\(l ∆l\\) + (\\(Δl\\))<sup>2</sup></p></td></tr><tr><td></td><td></td><td colspan=\"3\"><p>= \\({l}^{2}\\) + 2 \\(l ∆l\\) &nbsp;  &nbsp; (\\(∵{Δl}^{2}\\) is very small)</p></td></tr><tr><td></td><td colspan=\"2\"><p>Change in area, \\(∆ A\\) </p></td><td><p>=</p></td><td><p>A<sub>2</sub> – A</p></td></tr><tr><td></td><td colspan=\"2\"></td><td><p>=</p></td><td><p>\\({l}^{2}\\) + 2 \\(l ∆l\\) – \\({l}^{2}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(∆ A\\) </p></td><td><p>=</p></td><td><p>2 \\(l Δl\\)</p></td></tr><tr><td></td><td colspan=\"2\"></td><td><p>=</p></td><td><p>2 \\(l α l ∆\\)T &nbsp; (\\(∵Δl\\) = \\(α l ∆\\)T)</p></td></tr><tr><td></td><td colspan=\"2\"></td><td><p>=</p></td><td><p>2 \\(α {l}^{2} ∆\\)T</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(∆ A\\) </p></td><td><p>=</p></td><td><p>2 \\(α A ∆\\)T &nbsp; (\\(∵\\) A = \\({l}^{2}\\))</p></td></tr><tr><td></td><td colspan=\"2\"><p>We have         \\(∆ A\\)        </p></td><td><p>=</p></td><td><p>\\(β A ∆\\)T</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(β A ∆\\)T     </p></td><td><p>=</p></td><td><p>2 \\(α A ∆\\)T</p></td></tr><tr><td></td><td colspan=\"2\"><p>\\(β\\) </p></td><td><p>=</p></td><td><p>2 \\(α\\)</p></td></tr><tr><td></td><td colspan=\"4\"><p>The coefficient of area expansion is twice as the coefficient of linear expansion.</p></td></tr></tbody></table></div><p><strong>Extra</strong><strong>:</strong> &nbsp; <em><strong>Obtain the relationship between the coefficient of linear expansion and the coefficient of volume expansion of a substance.</strong></em></p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Initial volume = V</p></td><td colspan=\"2\"><p>= \\({l}^{3}\\)</p></td></tr><tr><td></td><td><p>Final volume = V<sub>2</sub></p></td><td colspan=\"2\"><p>= (\\(l\\) + \\(Δl\\))<sup>3</sup></p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= \\({l}^{3}\\) + 3 \\({l}^{2} Δl\\) + 3 \\(l {Δl}^{2}\\) + (\\(Δl\\))<sup>3</sup></p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= \\({l}^{3}\\) + 3 \\({l}^{2} Δl\\) &nbsp;  &nbsp; (\\(∵{Δl}^{2}\\), \\({Δl}^{3}\\) is very small)</p></td></tr><tr><td></td><td><p>Change in volume, \\(∆V\\) </p></td><td><p>=</p></td><td><p>V<sub>2</sub> – V</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\({l}^{3}\\) + 3 \\({l}^{2} Δl\\) – \\({l}^{3}\\)</p></td></tr><tr><td></td><td><p>\\(∆V\\) </p></td><td><p>=</p></td><td><p>3 \\({l}^{2} Δl\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>3 \\({l}^{2} α l ∆\\)T &nbsp; (\\(∵Δl\\) = \\(α l ∆\\)T)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>3 \\(α {l}^{3} ∆\\)T</p></td></tr><tr><td></td><td><p>\\(∆V\\) </p></td><td><p>=</p></td><td><p>3 \\(α V ∆\\)T &nbsp; (\\(∵\\) V = \\({l}^{3}\\))</p></td></tr><tr><td></td><td><p>We have         \\(∆V\\)        </p></td><td><p>=</p></td><td><p>\\(γ V ∆\\)T</p></td></tr><tr><td></td><td><p>\\(γ V ∆\\)T</p></td><td><p>=</p></td><td><p>3 \\(α V ∆\\)T</p></td></tr><tr><td></td><td><p>\\(γ\\) </p></td><td><p>=</p></td><td><p>3 \\(α\\)</p></td></tr><tr><td></td><td colspan=\"3\"><p>The coefficient of volume expansion is triple as the coefficient of linear expansion</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.1','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Sound waves can travel in all the following except </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; A. solids,</strong></em><em><strong> &nbsp; B. liquids,</strong></em><em><strong> &nbsp; C. air,</strong></em><em><strong> &nbsp; </strong></em><em><strong> &nbsp; D. vacuum</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>D.</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','No.10','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong><em><strong>Define wavelength, frequency and velocity of a sound wave. Write down the relationship between them. Can this relationship be used for other waves (such as light waves)?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Wavelength (</strong><strong></strong><strong>)</strong></p><p>  &nbsp;  &nbsp; The distance between any two consecutive wave crests (or) any two consecutive wave troughs is called the wavelength. </p><p> &nbsp;  &nbsp; <strong>Frequency (f)</strong></p><p> &nbsp;  &nbsp; The number of complete waves passing a point per second is called the frequency of the waves.</p><p> &nbsp;  &nbsp; <strong>Velocity</strong><strong> of</strong><strong> </strong><strong>a sound </strong><strong>Wave (v)</strong></p><p> &nbsp;  &nbsp; The velocity of wave is the speed with which a wave crest travels. </p><p> &nbsp;  &nbsp; The relationship between wavelength (\\(λ\\)), frequency (f), velocity (v) of a sound wave is v = f \\(λ\\)</p><p> &nbsp;  &nbsp; Yes, it can be used for other periodic waves.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Rev.3','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Write down the relation between period and frequency. Explain it.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>T = \\(\\frac{1}{f}\\) , &nbsp; where, T = period &nbsp; f = frequency</p><p><strong> &nbsp; </strong>Period is the inverse of the frequency. </p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Eg.1','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A distance of 0.33 m separates a wave crest from the adjacent trough, and the vertical distance from the top of a crest to the bottom of a trough is 0.24 m. What is the wavelength? What is the amplitude?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>Distance from wave crest to adjacent trough, \\(\\frac{λ}{2}\\) = 0.33 m</p></td></tr><tr><td></td><td colspan=\"3\"><p>Wavelength, \\(λ\\)</p></td><td><p>=</p></td><td><p>2 \\(×\\) 0.33 = <strong>0.66 m</strong></p></td></tr><tr><td></td><td colspan=\"5\"><p>Vertical distance from crest to trough, 2A = 0.24 m</p></td></tr><tr><td></td><td><p>Amplitude, A</p></td><td><p>=</p></td><td colspan=\"3\"><p>\\(\\frac{0.24}{2}\\) = <strong>0.12 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Eg.2','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>What is the speed of a 256 Hz sound with a wavelength of 1.35 m?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = 256 Hz, &nbsp; \\(λ\\) = 1.35 m</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) = 256 × 1.35 = <strong>345.5 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Eg.4','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A tall tree sways back and forth in the breeze with frequency of 2 Hz. What is the period of this?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = 2 Hz, &nbsp; T = ?</p></td></tr><tr><td></td><td><p>Period, T</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{f}\\) = \\(\\frac{1}{2}\\) = <strong>0.5 s</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,6,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.4','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>The displacement of an air particle with time as a sound wave travel through the air is as shown above. What is the frequency of the sound wave?</p><p> &nbsp;  &nbsp; A. 10 Hz &nbsp; B. 25 Hz &nbsp; C. 50 Hz &nbsp; D. 100 Hz</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>T = 0.04 s, &nbsp; f = ?</p></td></tr><tr><td></td><td><p>f</p></td><td><p>=</p></td><td><p>\\(\\frac{1}{T}\\) = \\(\\frac{1}{0.04}\\) = \\(\\frac{100}{4}\\) = <strong>25 Hz</strong><strong> </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(The correct answer is<strong> B</strong>.)</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','Eg.3','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>You dip your finger into a pan of water 14 times in 11 s, producing wave crests separated by 0.16 m. (a) What is the frequency? (b) What is the period? (c) What is the velocity?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\(λ\\) = 0.16 m, &nbsp; (a) f = ? &nbsp; (b) T = ? &nbsp; (c) v = ?</p></td></tr><tr><td><p>(a)</p></td><td><p>frequency, f </p></td><td><p>=</p></td><td><p>\\(\\frac{14}{11}\\) = <strong>1.27 Hz</strong></p></td></tr><tr><td><p>(b)</p></td><td><p>period, T </p></td><td><p>=</p></td><td><p>\\(\\frac{1}{f}\\) = \\(\\frac{1}{1.27}\\) = <strong>0.7874 s</strong></p></td></tr><tr><td><p>(c)</p></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) = 1.27 \\(×\\) 0.16 = <strong>0.20 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','Eg.5','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A typical sound wave associated with human speech has a frequency of 500 Hz and the frequency of the yellow light is about 5 × 10<sup>14</sup> Hz. The velocity of sound in air is 344 m s<sup>-1</sup> and the velocity of light is 3 × 10<sup>8</sup> m s<sup>-1</sup>. Find the wavelengths of the waves.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>For sound wave</p></td><td colspan=\"2\"><p>For yellow light wave</p></td></tr><tr><td></td><td><p>f = 500 Hz</p></td><td colspan=\"2\"><p>f = 5 × 10<sup>14</sup> Hz </p></td></tr><tr><td></td><td><p>v = 344 m s<sup>-1</sup></p></td><td colspan=\"2\"><p>c = 3 × 10<sup>8</sup> m s<sup>-1</sup></p></td></tr><tr><td></td><td><p>\\(λ\\) = ?</p></td><td colspan=\"2\"><p>\\(λ\\)  = ?</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\)</p></td></tr><tr><td></td><td><p>For sound wave, \\(λ\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{v}{f}\\) = \\(\\frac{344}{500}\\) = <strong>0.688 m</strong></p></td></tr><tr><td></td><td><p>For yellow light wave, \\(λ\\)</p></td><td><p>=</p></td><td><p>\\(\\frac{c}{f}\\) = \\(\\frac{3 × {10}^{8}}{5 × {10}^{14}}\\) = <strong>0.6 × </strong>\\({10}^{-6}\\)<strong> m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.7','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A sound frequency 400 Hz has a wavelength of 4.0 m in a medium. What is the speed of sound in the medium?</p><p> &nbsp;  &nbsp; A. 10<sup>-2</sup> m s<sup>-1</sup> &nbsp;  &nbsp; B. 100 m s<sup>-1</sup> &nbsp; C. 1 600 m s<sup>-1</sup> &nbsp;  &nbsp; D. 8 000 m s<sup>-1</sup>  </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = 400 Hz, &nbsp; \\(λ\\) = 4.0 m</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) = 400 × 4.0 = <strong>1 600 m s</strong><strong><sup>-1</sup></strong> &nbsp; (The correct answer is<strong> C</strong>.)</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.14','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14.</strong><strong> &nbsp; </strong>Find the wavelength of a wave with frequency 1 000 Hz and velocity 344 m s<sup>-1</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = 1 000 Hz, &nbsp;  &nbsp; v = 344 m s<sup>-1</sup>, &nbsp;  &nbsp; \\(λ\\) = ?</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) </p></td></tr><tr><td></td><td><p>\\(λ\\) </p></td><td><p>=</p></td><td><p>\\(\\frac{v}{f}\\) = \\(\\frac{344}{1 000}\\) = <strong>0.344 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.15','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15.</strong><strong> &nbsp; </strong>Find the frequency of a wave of velocity 200 m s<sup>-1</sup> and wavelength 0.5 m.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = ? &nbsp; \\(λ\\) = 0.5 m, &nbsp; v = 200 m s<sup>-1</sup></p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) </p></td></tr><tr><td></td><td><p>f</p></td><td><p>=</p></td><td><p>\\(\\frac{v}{λ}\\) = \\(\\frac{200}{0.5}\\) = \\(\\frac{2000}{5}\\) = <strong>400 Hz</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.17','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.17</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.17.</strong><strong> &nbsp; </strong>Find the frequency of a wave of 29 m wavelength telecast by a TV station. The velocity of that wave is the same as that of other electromagnetic waves and is         3 × 10<sup>8</sup> m s<sup>-1</sup>.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>f = ? &nbsp; \\(λ\\) = 29 m, &nbsp;  c = 3 × 10<sup>8</sup> m s<sup>-1</sup></p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\) </p></td></tr><tr><td></td><td><p>f</p></td><td><p>=</p></td><td><p>\\(\\frac{c}{λ}\\) = \\(\\frac{3 × {10}^{8}}{29}\\) = <strong>1.034</strong><strong>× </strong>\\({10}^{7}\\)<strong> Hz</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.16','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16.</strong><strong> &nbsp; </strong>A radar antenna emits electromagnetic radiation (c = 3 × 10<sup>8</sup> m s<sup>-1</sup>) of wavelength 0.03 m for 0.5 s. (a) Find the frequency of the radiation. (b) How many complete waves are emitted in 0.5 s?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>c = 3 × 10<sup>8</sup> m s<sup>-1</sup>, &nbsp; \\(λ\\) = 0.03 m, &nbsp; t = 0.5 s</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\)</p></td></tr><tr><td></td><td><p>f</p></td><td><p>=</p></td><td><p>\\(\\frac{c}{λ}\\) </p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{3 × {10}^{8}}{0.03}\\) = <strong>10</strong><strong><sup>10</sup></strong><strong> Hz (or) 10</strong><strong><sup>10</sup></strong><strong> s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>In 1 second, the number of complete waves = 10<sup>10</sup> waves</p></td></tr><tr><td></td><td colspan=\"3\"><p>In 0.5 second, the number of complete waves = \\(\\frac{0.5 s}{1 s}\\) × 10<sup>10</sup> = <strong>5 × 10</strong><strong><sup>9</sup></strong><strong> waves</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.11','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong><em><strong>What are wavefronts?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Wavefront</strong></p><p>  &nbsp;  &nbsp; The surface that joins all the points of the same phase is called wavefront.</p></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.12','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong><em><strong>What is meant by (a) reflection (b) refraction and (c) diffraction?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Reflection of waves</strong></p><p>  &nbsp;  &nbsp; When a series of waves strike an obstacle, they are turned back. This turning back of waves is called reflection of waves.</p><p> &nbsp;  &nbsp; <strong>Refraction of waves</strong></p><p> &nbsp;  &nbsp; When waves are incident to the boundary with an angle, the direction of the waves changes. Such a change in direction is called refraction. </p><p> &nbsp;  &nbsp; <strong>Diffraction of waves</strong></p><p>  &nbsp;  &nbsp; Diffraction is the spreading of waves from the straight-on direction through a gap (or) moves around an obstacle. </p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Rev.4','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What causes refraction of water waves?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong>  &nbsp; The change in speed of water wave due to change in depth of water causes refraction of water waves.</p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','Rev.5','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Does the speed of water waves depend upon the depth of water?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Yes. The speed of water waves depends upon the depth of water. The speed of water waves decreases when the depth of water becomes less deep.</p></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.22','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.22</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.22.</strong><strong> &nbsp; </strong><em><strong>The diagram below shows water waves passing through the entrance of a model harbour. </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (a) Describe what happens to the waves as they leave the gap between the harbour </strong></em><em><strong> &nbsp; walls. </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (b) What is this process called? </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (c) Describe one change that could be made to the above arrangement in order to </strong></em><em><strong> &nbsp; reduce this effect.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) <em>Water waves are spreading out</em> as they leave the gap between the harbor walls.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(b) This process is called <em>diffraction</em>. </p><p> &nbsp;  &nbsp; (c) To reduce this effect the gap between the harbor walls can be made <em>wider</em>.</p></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','No.5','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Which of the following is the normal audible frequency range of a human ear? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. 0 - l0 000 Hz      B. 0 - 20 000 Hz       C. 20 - 20 000 Hz     D. 100 - 100 000 Hz</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>C.</strong></p></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','No.6','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Which of the following frequencies of sound cannot be detected by the human ear? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. 50 Hz                   B. 500 Hz                     C. 50 00 Hz               D. 50 000 Hz</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>D.</strong></p></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','Rev.6','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>6</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>How does the velocity of sound depend on the temperature of the medium through which its travels?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>According to the equation, v = 332 \\(\\sqrt{\\frac{T}{273}}\\)</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>The velocity of sound is directly proportional to the square root of the Kelvin temperature of the medium. Whenever the air temperature increases by 1 °C, the speed of sound will increase by 0.2 %.</p></div></details></div></article>"}'::jsonb,22,true),
(10,'calculations','Rev.7','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>7</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>‘Generally, the denser the medium the greater will be the velocity of sound&#x27;. Explain this statement.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The denser the medium, the greater the speed of sound, because the particles of the medium are tightly bound together. This means that the disturbance can be transferred more quickly from one particle to the next and thereby increasing the velocity of sound.</p></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.2','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>How does the speed of sound vary in the following media; water, air and wood?</strong></em></p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td></td><td><p>Highest speed</p></td><td><p>Lowest speed</p></td></tr><tr><td><p>A.</p></td><td><p>Air</p></td><td><p>water</p></td></tr><tr><td><p>B.</p></td><td><p>Water </p></td><td><p>wood</p></td></tr><tr><td><p>C.</p></td><td><p>Wood</p></td><td><p>water</p></td></tr><tr><td><p>D.</p></td><td><p>Wood</p></td><td><p>air</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; D.</strong></p></div></details></div></article>"}'::jsonb,24,true),
(10,'calculations','No.3','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which one of the following statements is true for both sound and light waves?</strong></em> </p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>A.</p></td><td><p>They are transverse waves. </p></td></tr><tr><td><p>B.</p></td><td><p>They are reflected from a glass surface. </p></td></tr><tr><td><p>C.</p></td><td><p>They travel faster in air than in water. </p></td></tr><tr><td><p>D.</p></td><td><p>They are electromagnetic waves.</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,25,true),
(10,'calculations','No.9','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following describes correctly the changes, if any, to the frequency, wavelength and speed of sound as is travels from air into water?</strong></em> </p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>Frequency</p></td><td><p>Wavelength</p></td><td><p>Speed</p></td></tr><tr><td><p>A. Remains unchanged </p></td><td><p>decreases</p></td><td><p>decreases</p></td></tr><tr><td><p>B. Remains unchanged </p></td><td><p>increases</p></td><td><p>increases</p></td></tr><tr><td><p>C. Increases</p></td><td><p>increases</p></td><td><p>increases</p></td></tr><tr><td><p>D. Increases </p></td><td><p>remains unchanged</p></td><td><p>decreases</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,26,true),
(10,'calculations','No.13','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13.</strong><strong> &nbsp; </strong><em><strong>Are the following statements true (or) false? Correct the statements which are wrong.</strong></em> </p><p> &nbsp;  &nbsp; (a) The frequency of a wave is directly proportional to its wavelength. </p><p> &nbsp;  &nbsp; (b) Sound wave is transverse wave and water wave is longitudinal wave. </p><p> &nbsp;  &nbsp; (c) The velocity of sound is the same in water, air and helium gas. </p><p> &nbsp;  &nbsp; (d) Sound waves cannot travel through vacuum.<strong> &nbsp; </strong></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) False.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The frequency of a wave is inversely proportional to its wavelength (f \\(∝\\) \\(\\frac{1}{λ}\\)).</p><p> &nbsp;  &nbsp; (b) False.</p><p> &nbsp;  &nbsp;  &nbsp; Sound wave is longitudinal wave and water wave is a mixture of longitudinal  &nbsp; wave and transverse wave.</p><p> &nbsp;  &nbsp; (c) False.</p><p> &nbsp;  &nbsp;  &nbsp; The velocity is different in water, air and helium gas.</p><p> &nbsp;  &nbsp; (d) True.</p></div></details></div></article>"}'::jsonb,27,true),
(10,'calculations','No.8','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A boy hears the thunder 2.0 s after seeing lightning flash. How far is the lightning flash from the boy? (Speed of sound = 330 m s<sup>-1</sup>)</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. 165 m, &nbsp; B. 330 m, &nbsp; C. 660 m, &nbsp; D. 1320 m</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>t = 2 s, &nbsp;  &nbsp; v = 330 m s<sup>-1</sup>, &nbsp;  &nbsp; d = ?</p></td></tr><tr><td></td><td><p>v</p></td><td><p>=</p></td><td><p>\\(\\frac{d}{t}\\) </p></td></tr><tr><td></td><td><p>d</p></td><td><p>=</p></td><td><p>v t = 330 × 2 = <strong>660 m</strong><strong> &nbsp; </strong> &nbsp; (The correct answer is<strong> C</strong>.)</p></td></tr></tbody></table></div><p><strong>¥</strong><strong>No.18.</strong><strong> &nbsp; </strong>The <strong>shortest</strong> wavelength of an ultrasonic wave emitted by a bat (in air at <strong>0 °C</strong>) is   3.3 mm. What is the frequency of this wave? Is this frequency the largest (or) the smallest?</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>\\(λ\\) = 3.3 mm = 3.3 × 10<sup>-3</sup> m, &nbsp; (at T = 0 °C) v = 332 m s<sup>-1</sup>, &nbsp; f = ?</p></td></tr><tr><td></td><td><p>By wave equation, v</p></td><td><p>=</p></td><td><p>f \\(λ\\)</p></td></tr><tr><td></td><td><p>f</p></td><td><p>=</p></td><td><p>\\(\\frac{v}{λ}\\) = \\(\\frac{332}{3.3 × {10}^{-3}}\\) = <strong>100.6</strong><strong>× </strong>\\({10}^{3}\\)<strong> Hz</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Since f \\(∝\\) \\(\\frac{1}{λ}\\) , For the shortest wavelength the frequency is the largest.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,28,true),
(10,'calculations','No.19','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.19</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.19.</strong><strong> &nbsp; </strong>The frequency of a musical note in air is 440 Hz. What is the wavelength of that sound in sea water and in CO<sub>2</sub> gas? (Velocities of sound in sea water and CO<sub>2</sub> gas are 1440 m s<sup>-1</sup> and 259 m s<sup>-1</sup> respectively.)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>f = 440Hz</p></td></tr><tr><td></td><td><p>In sea water, &nbsp; v = 1 440 m s<sup>-1</sup>, &nbsp; \\(λ\\) = ?</p></td></tr><tr><td></td><td><p>By wave equation, v = f \\(λ\\) &nbsp;  &nbsp; \\(λ\\) = \\(\\frac{v}{f}\\) = \\(\\frac{1 440}{440}\\) = <strong>3.273 m</strong></p></td></tr><tr><td></td><td><p>In CO<sub>2</sub>, &nbsp; v = 259 m s<sup>-1</sup>, &nbsp;  &nbsp; \\(λ\\) = ?</p></td></tr><tr><td></td><td><p>By wave equation, v = f \\(λ\\) &nbsp;  &nbsp; \\(λ\\) = \\(\\frac{v}{f}\\) = \\(\\frac{259}{440}\\) = <strong>0.5886 m</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,29,true),
(10,'calculations','No.20','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.20</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.20.</strong><strong> &nbsp; </strong>What is the velocity of sound in air at 20 °C?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>T = 20 °C = 20 + 273 = 293 K</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= 332 \\(\\sqrt{\\frac{T}{273}}\\)</p></td><td colspan=\"2\"><p>[OR]</p></td><td><p>v</p></td><td><p>\\(≅\\) 332 + 0.6 (T – 273)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= 332 \\(\\sqrt{\\frac{293}{273}}\\) </p></td><td colspan=\"2\"></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure></p></td><td><p>\\(≅\\) 332 + 0.6 (293 – 273)</p></td></tr><tr><td></td><td></td><td><p>= 332 × 1.036</p></td><td colspan=\"2\"></td><td></td><td><p>\\(≅\\) 332 + 0.6 (20)</p></td></tr><tr><td></td><td></td><td colspan=\"2\"><p>= <strong>343.9 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td></td><td><p>\\(≅\\) <strong>344 m s</strong><strong><sup>-1</sup></strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,30,true),
(10,'calculations','No.21','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.21</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.21.</strong><strong> &nbsp; </strong>If the temperature of the air medium is increased from 0°C to 40°C, by what percentage has the velocity of sound increased?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>At T = 0 °C, &nbsp;  &nbsp;  &nbsp;  &nbsp;  &nbsp; v<sub>0</sub> = 332 m s<sup>-1</sup></p></td></tr><tr><td></td><td colspan=\"4\"><p>At T = 40 °C = 40 + 273 = 313 K, &nbsp;  &nbsp; v<sub>40</sub> = ?</p></td></tr><tr><td></td><td><p>v<sub>40</sub></p></td><td><p>= 332 \\(\\sqrt{\\frac{T}{273}}\\)</p></td><td><p>\\(∆\\)v</p></td><td><p>= v<sub>40</sub> – v<sub>0</sub> = 355.24 – 332 = <strong>23.2 m s</strong><strong><sup>-1</sup></strong></p></td></tr><tr><td></td><td><p>v<sub>40</sub></p></td><td><p>= 332 \\(\\sqrt{\\frac{313}{273}}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure> Percentage</p></td><td><p>= \\(\\frac{∆v}{{v}_{0}}\\) \\(×\\) 100 \\(\\%\\)</p></td></tr><tr><td></td><td></td><td><p>= <strong>355.24 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td><p>= \\(\\frac{23.24}{332}\\) × 100 \\(\\%\\) = <strong>7 </strong>\\(\\%\\)</p></td></tr><tr><td><p><strong>[OR]</strong></p></td><td colspan=\"4\"><p>For 1°C increase in temperature  &nbsp; = 0.2 \\(\\%\\) increase in velocity of sound</p></td></tr><tr><td></td><td colspan=\"4\"><p>For 40°C increase in temperature &nbsp; = ?</p></td></tr><tr><td></td><td colspan=\"4\"><p> &nbsp;  &nbsp; = 0.2 \\(\\%\\) × \\(\\frac{40℃}{1℃}\\)</p></td></tr><tr><td></td><td colspan=\"4\"><p> &nbsp;  &nbsp; = <strong>8 </strong>\\(\\%\\) increase in velocity of sound</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,31,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','Eg.6','7','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>On a day when air temperature is 11 °C, you use a whistle to call your dog. If the wavelength of the sound produced is 0.015 m, what is the frequency? Could you hear the whistle?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\(λ\\) = 0.015 m= 15 \\(× {10}^{-3}\\)m</p></td></tr><tr><td></td><td colspan=\"4\"><p>T = 11 °C = 11 + 273 = 283 K, &nbsp; f = ?</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= 332 \\(\\sqrt{\\frac{T}{273}}\\)</p></td><td><p>By wave equation, v</p></td><td><p>= f \\(λ\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= 332 \\(\\sqrt{\\frac{283}{273}}\\)</p></td><td><p>f</p></td><td><p>= \\(\\frac{v}{λ}\\)</p></td></tr><tr><td></td><td></td><td><p>= <strong>338.64 m s</strong><strong><sup>-1</sup></strong></p></td><td></td><td><p>= \\(\\frac{338.64}{15 × {10}^{-3}}\\)</p></td></tr><tr><td></td><td></td><td></td><td></td><td><p>= <strong>22 570 Hz</strong></p></td></tr><tr><td></td><td colspan=\"4\"><p>No, we could not hear the whistle because the frequency of sound produced by whistle is greater than upper limit of audible sound (20 000 Hz).</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,32,true),
(10,'calculations','No.2','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Give two examples each of objects which (a) emit their own light (b) are only visible because they reflect light from another source.</strong></em> </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong>  &nbsp; (a) The sun, the stars, candle flame, fluorescent lamp. </p><p><strong> &nbsp; </strong>(b) Human beings, tree, books, the moon, the earth.</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.1','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Give the names of light source which emit parallel beam and divergent beam.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Searchlights used in trains and lighthouses, emit parallel beam of light. </p><p> &nbsp; Light bulbs emit divergent beam of light.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','No.1','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>State the laws of reflection of light.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(1) The incident ray, the reflected ray and the normal all <strong>lie</strong> in the same plane. </p><p> &nbsp;  &nbsp; (2) The angle of incidence is equal to the angle of reflection. </p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Rev.2','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Check the laws of reflection using a plane mirror.</strong></em></p><p> &nbsp;  &nbsp; AO = incident ray</p><p> &nbsp;  &nbsp; OB = reflected ray</p><p> &nbsp;  &nbsp; NO = normal</p><p> &nbsp;  &nbsp; i = angle of incidence</p><p> &nbsp;  &nbsp; r = angle of refraction</p><p> &nbsp; For checking the laws of reflection using a plane mirror, laser, rule and semicircle. </p><p> &nbsp; - Place a plane mirror and draw a normal line on the mirror. </p><p> &nbsp; - Incident a ray of laser light at the point on the mirror and normal interface.</p><p> &nbsp; - Mark the points on the incident ray and reflected ray and draw the lines</p><p> &nbsp; - Check the angle of incidence and angle of refraction.</p></div></div></article>"}'::jsonb,4,true),
(10,'calculations','Rev.3','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What are the differences between real and virtual images?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>Real image</p></td><td><p>Virtual image</p></td></tr><tr><td></td><td><p>reflected rays actually pass through it</p></td><td><p>reflected rays do not actually pass through it</p></td></tr><tr><td></td><td><p>can be formed on a screen</p></td><td><p>cannot be formed on a screen</p></td></tr><tr><td></td><td><p>inverted with respect to the object</p></td><td><p>erect with respect to the object</p></td></tr><tr><td></td><td><p>in front of the mirror</p></td><td><p>behind the mirror</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Rev.4','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What does it mean to say that a plane mirror produces a virtual image?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The reflected rays do not actually pass through the image. Only the reflected rays produced backwards pass through it. It cannot be formed on the screen. Thus, we say that a plane mirror produces a virtual image.</p></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.7','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>What is meant by lateral inversion? The letter R is 5 cm in front of a plane mirror. Draw accurately the image of R in the mirror.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Lateral inversion is the interchange of left and right in a mirror image.</p></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.3','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A man is looking into a plane mirror on the wall which is 6 ft away from him. He views the image of a chart which faces the mirror and is 2 ft behind him. Find the distance between his eyes and the image of the chart.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"></td></tr><tr><td></td><td colspan=\"4\"><p>EM = 6 ft, &nbsp; CE = 2 ft, &nbsp; E\\(C''\\) = ?</p></td></tr><tr><td></td><td><p>CM</p></td><td><p><figure><img src=\"cal-media/g11-g10-image8.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= EM + CE</p></td><td><p>CM</p></td><td><p>= M\\(C''\\) = 8 ft</p></td></tr><tr><td></td><td></td><td><p>= 2 + 6 = 8 ft</p></td><td><p>E\\(C''\\)</p></td><td><p>= EM + M\\({C}^{''}\\) = 6 + 8 = <strong>14 ft</strong> </p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','Eg.1','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A man 5 ft 6 in tall and whose eye level is 5 ft 2 in above the ground, looks at his image in a looking glass. What is the minimum vertical length of the looking glass if the man is to be able to see the whole of himself? </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"></td><td><p>H = man’s head</p><p>E = man’s eye</p><p>F = man’s feet</p><p>AB = length of looking glass</p></td></tr><tr><td></td><td><p>HF</p></td><td><p>=</p></td><td colspan=\"2\"><p>5 ft 6 in = (5 × 12 in) + 6 in = 60 in + 6 in = <strong>66 in</strong></p></td></tr><tr><td></td><td><p>EF</p></td><td><p>=</p></td><td colspan=\"2\"><p>5 ft 2 in = (5 × 12 in) + 2 in = 60 in + 2 in = <strong>62 in</strong></p></td></tr><tr><td></td><td><p>HE</p></td><td><p>=</p></td><td colspan=\"2\"><p><strong></strong>66 – 62 = 4 in</p></td></tr><tr><td></td><td colspan=\"4\"><p>Since the normal AN<sub>1</sub> bisects HE</p></td></tr><tr><td></td><td><p>AL</p></td><td><p>=</p></td><td colspan=\"2\"><p>EN<sub>1</sub> = \\(\\frac{HE}{2}\\) = \\(\\frac{4}{2}\\) = <strong>2 in</strong></p></td></tr><tr><td></td><td colspan=\"4\"><p>Since the normal BN<sub>2</sub> bisects EF</p></td></tr><tr><td></td><td><p>LB</p></td><td><p>=</p></td><td colspan=\"2\"><p>EN<sub>2</sub> = \\(\\frac{EF}{2}\\) = \\(\\frac{62}{2}\\) = <strong>31 in</strong></p></td></tr><tr><td></td><td><p>AB</p></td><td><p>=</p></td><td colspan=\"2\"><p>AL + LB = 2 + 31 = <strong>33 in</strong> = <strong>2 ft 9 in</strong></p></td></tr><tr><td></td><td colspan=\"4\"><p>The looking glass must have the minimum vertical length of 2 ft 9 in, which is half of the height of the man. </p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.4','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Draw a ray diagram to show that a vertical plane mirror need not be 5 ft long in order that a boy 5 ft tall may see a full-length image of himself in it.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>H = man’s head</p><p>E = man’s eye</p><p>F = man’s feet</p><p>HF = height of the body = 5 ft</p><p>AB = length of looking glass</p></td><td></td></tr><tr><td></td><td colspan=\"2\"><p> &nbsp; AB &lt; HF</p></td></tr><tr><td></td><td colspan=\"2\"><p>A vertical plane mirror need not 5 ft long.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.5','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A boy 5 ft tall looks at his full-length image in a looking glass. If the boy&#x27;s eyes are 4 in below the top of his head, find the height of the base of the mirror above floor level. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td><p>HF</p></td><td><p>=</p></td><td><p>5 ft = 5 × 12 in = <strong>60 in</strong> </p></td></tr><tr><td></td><td><p>HE</p></td><td><p>=</p></td><td><p>4 in </p></td></tr><tr><td></td><td><p>EF</p></td><td><p>=</p></td><td><p>60 – 4 = <strong>56 in</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>Since the normal BN<sub>2</sub> bisects EF</p></td></tr><tr><td></td><td><p>BG</p></td><td><p>=</p></td><td><p>FN<sub>2</sub></p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p>\\(\\frac{EF}{2}\\) = \\(\\frac{56}{2}\\) = <strong>28 in = 2 ft 4 in</strong></p></td></tr><tr><td></td><td colspan=\"3\"><p>The height of the base of the mirror above floor level is 2 ft 4 in.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.6','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Show that a point object and its image are at equal distance from any point on the plane mirror. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>OA is parallel to NB, &nbsp; i = \\(∠\\) AOB (alternate angle) သမသတ်ထောင့်</p></td></tr><tr><td></td><td colspan=\"3\"><p> &nbsp; r = \\(∠\\) AIB (corresponding angle) လိုက်ဖက်ထောင့်</p></td></tr><tr><td></td><td colspan=\"3\"><p>By the laws of reflection, i = r</p></td></tr><tr><td></td><td colspan=\"3\"><p>In \\(∆\\) OAB and \\(∆\\) IAB, </p></td></tr><tr><td></td><td><p>\\(∴\\) \\(∠\\)AOB</p></td><td><p>=</p></td><td><p>\\(∠\\)AIB</p></td></tr><tr><td></td><td><p>\\(∠\\)OAB</p></td><td><p>=</p></td><td><p>\\(∠\\)IAB &nbsp; (right angle)</p></td></tr><tr><td></td><td><p>AB</p></td><td><p>=</p></td><td><p>AB &nbsp; (common side)</p></td></tr><tr><td></td><td><p>\\(∆\\)OAB</p></td><td><p>\\(≅\\)</p></td><td><p>\\(∆\\)OAB</p></td></tr><tr><td></td><td><p>OA</p></td><td><p>=</p></td><td><p>AI</p></td></tr><tr><td></td><td><p>OB</p></td><td><p>=</p></td><td><p>BI</p></td></tr><tr><td></td><td colspan=\"3\"><p>Thus, a point object and its image are at equal distance from any point on the plane mirror.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.8','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>State the similarities and differences between the virtual images formed by the concave and convex mirrors.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans</strong><strong>:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Similarities</strong></p><p>(i)  &nbsp; Both are erect. &nbsp;  &nbsp; (ii) Both lie behind the mirrors. </p><p>(iii) &nbsp; Both images cannot be formed on a screen.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong>Differences</strong></p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td></td><td><p>Virtual image by concave mirror</p></td><td></td><td><p>Virtual image by convex mirror</p></td></tr><tr><td><p>1.</p></td><td><p>The image is larger than the object.</p></td><td colspan=\"2\"><p>The image is smaller than the object.</p></td></tr><tr><td><p>2.</p></td><td><p>The image is anywhere behind the mirror.</p></td><td colspan=\"2\"><p>The image is always between F and P.</p></td></tr><tr><td><p>3.</p></td><td><p>The virtual image is formed by only when the object is between F and P.</p></td><td colspan=\"2\"><p>The virtual image is formed wherever the object is in front of the mirror.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.10','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong><em><strong>Choose the correct answer from the following:</strong></em> </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. Only a virtual image smaller than the object is formed by a concave mirror. </p><p> &nbsp;  &nbsp; B. Only a virtual image larger than the object is formed by a convex mirror. </p><p> &nbsp;  &nbsp; C. The statements given in A and B are both wrong.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; C.</strong></p></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.11','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong><em><strong>Choose the correct answer from the following: </strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. Only real images are formed by a concave mirror. </p><p> &nbsp;  &nbsp; B. Real and virtual images can be formed by a concave mirror. </p><p> &nbsp;  &nbsp; C. Real and virtual images can be formed by a convex mirror.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','Eg.2','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>An object is (a) 20 cm (b) 4 cm in front of a concave mirror of focal length 12 cm. Find the nature and position of the image in each case. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>f = + 12 cm (concave mirror) &nbsp;  &nbsp; (a) u = 20 cm, &nbsp; (b) u = 4 cm &nbsp; v = ?</p></td></tr><tr><td></td><td colspan=\"5\"><p>By mirror formula,</p></td></tr><tr><td><p>(a)</p></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image14.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= \\(\\frac{1}{f}\\)</p></td><td><p>(b)</p></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{20}\\) + \\(\\frac{1}{v}\\) </p></td><td><p>=  \\(\\frac{1}{12}\\)</p></td><td></td><td><p>\\(\\frac{1}{4}\\) + \\(\\frac{1}{v}\\) </p></td><td><p>=  \\(\\frac{1}{12}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{1}{12}-\\frac{1}{20}\\)</p></td><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{1}{12}-\\frac{1}{4}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{5 - 3}{60}\\) = \\(\\frac{2}{60}\\)</p></td><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{1 - 3}{12}\\) = \\(\\frac{- 2}{12}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= \\(\\frac{60}{2}\\)</p></td><td></td><td><p>v</p></td><td><p>= \\(-\\frac{12}{2}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= <strong>+ 30 cm </strong><strong>(real image)</strong></p></td><td></td><td><p>v</p></td><td><p>= \\(-\\)<strong> 6 cm (virtual image)</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','No.12','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong><em><strong>Choose the correct answer from the following:</strong></em> </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>When an object is at the centre of curvature of a concave mirror the magnification is </p><p> &nbsp;  &nbsp; A. 0.5 &nbsp; B. - 1.0 &nbsp; C. 1.5</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','Eg.3','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>An object is placed 10 cm in front of a concave mirror of focal length 15 cm. Find the image position and the magnification.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>u = 10 cm, &nbsp; f = + 15 cm (concave mirror), &nbsp;  &nbsp; v = ? &nbsp; m = ?</p></td></tr><tr><td></td><td colspan=\"4\"><p>By mirror formula,</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>m</p></td><td><p>= \\(- \\frac{v}{u}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{10}\\) + \\(\\frac{1}{v}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>=  \\(\\frac{1}{15}\\)</p></td><td></td><td><p>=  \\(-\\frac{(-30)}{10}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{1}{15}\\) - \\(\\frac{1}{10}\\)</p></td><td></td><td><p>= <strong>+ 3 (erect)</strong></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{2 - 3}{30}\\) = \\(\\frac{- 1}{30}\\)</p></td><td></td><td></td></tr><tr><td></td><td><p>v</p></td><td><p>= <strong>- 30 cm (virtual image)</strong></p></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.18','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.18</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.18.</strong><strong> &nbsp; </strong>An object is placed 30 cm in front of a concave mirror of focal length of 10 cm. Find the image position and the magnification.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>u = 30 cm, &nbsp; f = + 10 cm (concave mirror), &nbsp;  &nbsp; v = ? &nbsp; m = ?</p></td></tr><tr><td></td><td colspan=\"4\"><p>By mirror formula,</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>m</p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{30}\\) + \\(\\frac{1}{v}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>=  \\(\\frac{1}{10}\\)</p></td><td></td><td><p>= - \\(\\frac{15}{30}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{1}{10}\\) - \\(\\frac{1}{30}\\)</p></td><td></td><td><p>= <strong>- </strong>\\(\\frac{1}{2}\\)<strong> (inverted)</strong></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{3 - 1}{30}\\) = \\(\\frac{2}{30}\\)</p></td><td></td><td></td></tr><tr><td></td><td><p>v</p></td><td><p>= <strong>+ 15 cm (real image)</strong></p></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','Eg.4','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The image of an object in a convex mirror is 4 cm from the mirror. If the mirror has a radius of curvature of 24 cm, find the object position and the magnification.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>v = - 4 cm (virtual image), &nbsp; R = - 24 cm (convex mirror), &nbsp; u = ? &nbsp; m = ?</p></td></tr><tr><td></td><td><p>f</p></td><td><p>= \\(\\frac{R}{2}\\)</p></td><td><p>\\(\\frac{1}{u}\\) </p></td><td><p>= \\(\\frac{-1+ 3}{12}\\) = \\(\\frac{2}{12}\\)</p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{- 24}{2}\\) = - 12 cm</p></td><td><p>u</p></td><td><p>= <strong>+ 6 cm</strong></p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td></td><td></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m</p></td><td><p>= \\(- \\frac{v}{u}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{(-4 )}\\) </p></td><td><p>= \\(\\frac{1}{(-12)}\\)</p></td><td></td><td><p>=  \\(-\\frac{(- 4)}{6}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) </p></td><td><p>= \\(\\frac{- 1}{12}\\) + \\(\\frac{1}{4}\\) </p></td><td></td><td><p>= <strong>+ </strong>\\(\\frac{2}{3}\\)<strong> (erect)</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,20,true),
(10,'calculations','No.14','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14.</strong><strong> &nbsp; </strong>An image is 6 cm from a convex mirror which has a radius of curvature of 36 cm. Find the object position and the magnification.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>v = - 6 cm (virtual image), &nbsp; R = - 36 cm (convex mirror), &nbsp; u = ? &nbsp; m = ?</p></td></tr><tr><td></td><td><p>f</p></td><td><p>= \\(\\frac{R}{2}\\)</p></td><td><p>\\(\\frac{1}{u}\\) </p></td><td><p>= \\(\\frac{- 1}{18}\\) + \\(\\frac{1}{6}\\)</p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{- 36}{2}\\) = - 18 cm</p></td><td><p>\\(\\frac{1}{u}\\) </p></td><td><p>= \\(\\frac{- 1 + 3}{18}\\) = \\(\\frac{2}{18}\\)</p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td><p>u</p></td><td><p>= <strong>+ 9 cm</strong></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image16.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>m</p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{(-6 )}\\) </p></td><td><p>= \\(\\frac{1}{(-18)}\\)</p></td><td></td><td><p>=  \\(-\\frac{(- 6)}{9}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) - \\(\\frac{1}{6 }\\) </p></td><td><p>= \\(\\frac{- 1}{18}\\) </p></td><td></td><td><p>= <strong>+ </strong>\\(\\frac{2}{3}\\)<strong> (erect)</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','No.15','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15.</strong><strong> &nbsp; </strong>An image <strong>one-third</strong> the size of an object is formed by a convex mirror of focal length 15 cm. How far is the object from the convex mirror?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>\\(I{I}^{''}\\) = + \\(\\frac{1}{3}\\) \\(×\\) \\(O{O}^{''}\\) (erect), &nbsp; f = - 15 cm (convex mirror), &nbsp; u = ?</p></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p>= \\(\\frac{1}{3}\\)</p></td><td><p>\\(\\frac{- 1}{3 v}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{-15}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td><td><p>\\(\\frac{- 1 + 3}{3 v}\\) </p></td><td><p>= \\(\\frac{1}{-15}\\)</p></td></tr><tr><td></td><td><p>\\(-\\frac{v}{u}\\) </p></td><td><p>= \\(\\frac{1}{3}\\)</p></td><td><p>\\(\\frac{2}{3 v}\\) </p></td><td><p>= \\(\\frac{1}{-15}\\)</p></td></tr><tr><td></td><td><p>u</p></td><td><p>= \\(-\\)3v</p></td><td><p>3v</p></td><td><p>= \\(-\\)30</p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td><p><figure><img src=\"cal-media/g11-g10-image25.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>v</p></td><td><p>= \\(-\\)<strong>10 cm (virtual image)</strong></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>u</p></td><td><p>= \\(-\\)3v</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{(-3 v)}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{-15}\\)</p></td><td></td><td><p>= \\(-\\)3 (\\(-\\)10) = <strong>30 cm</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,22,true),
(10,'calculations','Eg.5','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The image of an object in a concave mirror is <strong>erect</strong> and <strong>three times</strong> the size of the object. If the mirror has a radius of curvature of 36 cm, find the position of the object.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"6\"><p>\\(I{I}^{''}\\) = + 3 \\(×\\) \\(O{O}^{''}\\) (erect), &nbsp; R = + 36 cm (concave mirror), &nbsp; u = ?</p></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p>= 3</p></td><td colspan=\"2\"><p>By mirror formula,</p></td><td colspan=\"2\"></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>\\(\\frac{2}{3 u}\\) </p></td><td><p>= \\(\\frac{1}{18}\\)</p></td></tr><tr><td></td><td><p>\\(-\\frac{v}{u}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image14.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= 3</p></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{(-3 u)}\\) </p></td><td><p>= \\(\\frac{1}{18}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image14.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>3 u</p></td><td><p>= 36</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= \\(-\\)3u</p></td><td><p>\\(\\frac{1}{u}\\) - \\(\\frac{1}{3 u}\\) </p></td><td><p>= \\(\\frac{1}{18}\\) </p></td><td><p>u</p></td><td><p>= <strong>+ 12 cm</strong></p></td></tr><tr><td></td><td><p>f</p></td><td><p>= \\(\\frac{R}{2}\\)</p></td><td><p>\\(\\frac{3-1}{3 u}\\) </p></td><td><p>= \\(\\frac{1}{18}\\)</p></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{36}{2}\\) = <strong>+ 18 cm</strong></p></td><td></td><td colspan=\"3\"></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.17','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.17</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.17.</strong><strong> &nbsp; </strong>An object is 20 cm from a mirror. If the virtual image is <strong>half</strong> the size of the object, find the radius of curvature of the mirror. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>u = + 20 cm, &nbsp;  &nbsp; \\(I{I}^{''}\\) = + \\(\\frac{1}{2}\\) \\(×\\) \\(O{O}^{''}\\) (erect), &nbsp; R = ?</p></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p><figure><img src=\"cal-media/g11-g10-image25.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= \\(\\frac{1}{2}\\)</p></td><td><p>\\(\\frac{1}{20}\\) + \\(\\frac{1}{(-10)}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{I{I}^{''}}{O{O}^{''}}\\) </p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td><td><p>\\(\\frac{1}{20}\\) - \\(\\frac{1}{10}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>\\(-\\frac{v}{u}\\) </p></td><td><p>= \\(\\frac{1}{2}\\)</p></td><td><p>\\(\\frac{1 - 2}{20}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= \\(-\\frac{u}{2}\\)</p></td><td><p>\\(\\frac{- 1}{20}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td></td><td><p>= \\(-\\frac{20}{2}\\) = <strong>- 10 cm</strong></p></td><td><p>f</p></td><td><p>= <strong>- 20 cm (convex mirror)</strong></p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td><p>R</p></td><td><p>= 2f</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>R</p></td><td><p>= 2 (-20) = <strong>- 40 cm</strong> </p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,24,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.13','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13.</strong><strong> &nbsp; </strong><em><strong>A concave mirror can produce an image which is twice the size of the object. Draw a ray diagram to show this.</strong></em><em><strong> </strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"2\"><p>Let, focal length of the mirror = f</p></td><td></td><td></td></tr><tr><td></td><td colspan=\"2\"><p>For real image, m = \\(-\\)2 (inverted)</p></td><td></td><td></td></tr><tr><td></td><td><p>m</p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td><td><p>\\(\\frac{2 + 1}{2u}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>\\(-\\frac{v}{u}\\) </p></td><td><p>= \\(-\\)2</p></td><td><p>\\(\\frac{3 }{2u}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p><figure><img src=\"cal-media/g11-g10-image27.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= 2u</p></td><td><p>2u</p></td><td><p>= 3f</p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td><p>u</p></td><td><p>= 1.5f</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td><p>u</p></td><td><p>= f + 0.5 f</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{2u}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td></td><td></td></tr></tbody></table></div><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td></td><td colspan=\"2\"><p>Let, focal length of the mirror = f</p></td><td></td><td></td></tr><tr><td></td><td colspan=\"2\"><p>For virtual image, m = 2 (erect)</p></td><td><p>\\(\\frac{1}{u}\\) - \\(\\frac{1}{2 u}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>m</p></td><td><p><figure><img src=\"cal-media/g11-g10-image27.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= \\(-\\frac{v}{u}\\)</p></td><td><p>\\(\\frac{2 - 1}{2 u}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>\\(-\\frac{v}{u}\\) </p></td><td><p>= 2</p></td><td><p>\\(\\frac{1 }{2 u}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= \\(-\\)2u</p></td><td><p>2u</p></td><td><p>= f</p></td></tr><tr><td></td><td colspan=\"2\"><p>By mirror formula,</p></td><td><p>u</p></td><td><p>= 0.5f</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td></td><td></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{(-2 u)}\\) </p></td><td><p>= \\(\\frac{1}{f}\\)</p></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,25,true),
(10,'calculations','No.9','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>When a ray parallel to the principal axis is incident on a concave mirror, it passes through the focus after reflection. By using the laws of reflection, prove that f = \\(\\frac{R}{2}\\).</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>Since incident ray is parallel to the principal axis, </p></td></tr><tr><td></td><td colspan=\"4\"><p> &nbsp; i = \\(∠\\)ACP (corresponding angle) လိုက်ဖက်ထောင့်</p></td></tr><tr><td></td><td colspan=\"4\"><p>By the laws of reflection, i = r, &nbsp; In \\(∆\\) ACF,</p></td></tr><tr><td></td><td><p>r</p></td><td colspan=\"3\"><p>= \\(∠\\)ACP</p></td></tr><tr><td></td><td><p>CF</p></td><td colspan=\"3\"><p>= FA -------- (1)</p></td></tr><tr><td></td><td colspan=\"4\"><p>For the rays close to principal axis, A very close to P,</p></td></tr><tr><td></td><td><p>FP</p></td><td colspan=\"3\"><p>= FA   -------- (2)</p></td></tr><tr><td></td><td colspan=\"2\"><p>From eq (1) and (2)</p></td><td colspan=\"2\"><p>FP = f = focal length</p></td></tr><tr><td></td><td><p>CF</p></td><td><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= FP</p></td><td colspan=\"2\"><p>CP = R = radius of curvature</p></td></tr><tr><td></td><td><p>CP</p></td><td><p>= CF + FP</p></td><td></td><td></td></tr><tr><td></td><td><p>CP</p></td><td><p>= FP + FP</p></td><td><p>R</p></td><td><p>= 2 f</p></td></tr><tr><td></td><td><p>CP</p></td><td><p>= 2 FP</p></td><td><p>f</p></td><td><p>= \\(\\frac{R}{2}\\)</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,26,true),
(10,'calculations','No.16','8','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16.</strong><strong> &nbsp; </strong>An object is 20 cm in front of a concave mirror of focal length 15 cm. How far must the screen be placed from the centre of curvature of the concave mirror to receive the image of the object? If the object is 2 cm tall, find the size of the image.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>u = 20 cm, &nbsp; f = + 15 cm (concave mirror), &nbsp;  &nbsp; v - R = ? &nbsp; \\(II''\\) = ?</p></td></tr><tr><td></td><td colspan=\"4\"><p>By mirror formula,</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{u}\\) + \\(\\frac{1}{v}\\)</p></td><td><p><figure><img src=\"cal-media/g11-g10-image25.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= \\(\\frac{1}{f}\\)</p></td><td><p>v - R</p></td><td><p>= 60 – 30 = <strong>30 cm</strong></p></td></tr><tr><td></td><td><p>\\(\\frac{1}{20}\\) + \\(\\frac{1}{v}\\) </p></td><td><p>=  \\(\\frac{1}{15}\\)</p></td><td></td><td></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{ 1}{15}\\) - \\(\\frac{1}{20}\\)</p></td><td><p>\\(\\frac{{II}^{''}}{{OO}^{''}}\\) </p></td><td><p>= \\(-\\frac{v}{u}\\)</p></td></tr><tr><td></td><td><p>\\(\\frac{1}{v}\\) </p></td><td><p>= \\(\\frac{4 - 3}{60}\\) = \\(\\frac{1}{60}\\)</p></td><td><p>\\(II''\\) </p></td><td><p>= \\(\\frac{- v}{u}\\) × \\({OO}^{''}\\)</p></td></tr><tr><td></td><td><p>v</p></td><td><p>= <strong>60 cm (real image)</strong></p></td><td></td><td><p>= \\(\\frac{- 60}{20}\\) × \\(2\\) </p></td></tr><tr><td></td><td><p>R</p></td><td><p>= 2f</p></td><td><p>\\(II''\\) </p></td><td><p>= <strong>- 6 cm (inverted)</strong></p></td></tr><tr><td></td><td></td><td><p>= 2 × 15 = <strong>+ 30 cm</strong></p></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,27,true),
(10,'calculations','Rev.1','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>When two bodies attract each other electrically, must both of them be charged?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>No. One must be charged body but the other may be uncharged (or) unlike charge. </p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.2','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>When two bodies repel each other electrically, must both of them be charged?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans: </strong><strong> &nbsp; </strong>Yes. The two bodies must be charged body and must be like charge.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','No.1','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong> &nbsp; <em><strong>When a negatively charged sphere is brought near a suspended body, the suspended body is attracted to it. Is it correct to assume that the body is positively charged?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp;  &nbsp; No. The suspended body may be positively charged body (or) uncharged body.</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','No.5','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Common static electricity involves charges ranging from nanocoulombs to microcoulombs. (a) How many electrons are needed to form a charge of - 2 nC?   (b) How many electrons must be removed from a neutral object to have a net charge of +l μC?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"4\"><p>Charge of electron, e = 1.6 × \\({10}^{-19}\\) C</p></td></tr><tr><td></td><td colspan=\"2\"><p><figure><img src=\"cal-media/g11-g10-image12.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>(a)  Q = -2 nC = - 2 × \\({10}^{-9}\\) C    </p></td><td colspan=\"2\"><p>(b)  Q = + 1 \\(μ\\)C = + 1 × \\({10}^{-6}\\) C</p></td></tr><tr><td></td><td><p>Q</p></td><td><p>= n e</p></td><td><p>Q</p></td><td><p>= n e</p></td></tr><tr><td></td><td><p>n</p></td><td><p>= \\(\\frac{Q}{e}\\) </p></td><td><p>n</p></td><td><p>= \\(\\frac{Q}{e}\\) </p></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{2 × {10}^{-9}}{1.6 × {10}^{-19}}\\) </p></td><td></td><td><p>= \\(\\frac{1 × {10}^{-6}}{1.6 × {10}^{-19}}\\) </p></td></tr><tr><td></td><td></td><td><p>= <strong>1.25 × </strong>\\({10}^{10}\\)<strong> electrons</strong></p></td><td></td><td><p>= <strong>6.25 × </strong>\\({10}^{12}\\)<strong>  electrons</strong></p></td></tr><tr><td></td><td colspan=\"2\"><p>1.25 × \\({10}^{10}\\) electrons are needed.</p></td><td colspan=\"2\"><p>6.25 × \\({10}^{12}\\)  electrons must be removed.</p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','No.6','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>To start a car engine, the car battery moves 3.75 \\(× {10}^{20}\\) electrons through the starter motor in one second. How many coulombs of charge were moved in that time?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"3\"><p>Number of electrons, n = 3.75 × \\({10}^{20}\\) electrons, &nbsp; e = 1.6 × \\({10}^{-19}\\) C</p></td></tr><tr><td></td><td><p>Q</p></td><td><p>=</p></td><td><p>n e</p></td></tr><tr><td></td><td><p>Q</p></td><td><p>=</p></td><td><p>3.75 × \\({10}^{20}\\) × 1.6 × \\({10}^{-19}\\)</p></td></tr><tr><td></td><td></td><td><p>=</p></td><td><p><strong>5.999 × </strong>\\({10}^{1}\\)<strong> = 60 C</strong></p></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','Rev.3','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Why does a nucleus possess the positive charge?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The nucleus consists of two kinds of particles called proton and neutron. A proton is a positively charged particle and a neutron is an uncharged particle. Thus, the nucleus has net positive charge.</p></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','Rev.4','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What do you understand by a bound electron and a free electron?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong> &nbsp; <strong>Bond electron</strong></p><p> &nbsp;  &nbsp; The inner electron that is tightly bound by the nucleus (or) an electron closer to the nucleus is called a bound electron. </p><p> &nbsp;  &nbsp; <strong>Free electron</strong></p><p> &nbsp;  &nbsp; The outer electron that is loosely bound by the nucleus (or) an electron far away from the nucleus is called a free electron. </p></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','Rev.5','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Is your body a conductor (or) an insulator? Mention five insulators and five conductors.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong> &nbsp; My body is an electrically conductor.</p><p> &nbsp; Insulators &nbsp; - nonmetals such as plastic, glass, rubber, wax, wood.</p><p> &nbsp; Conductors &nbsp; - metals such as gold, silver, copper, brass, steel.</p></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','Rev.6','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>6</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>There are very large numbers of charged particles in most objects. Why then, don&#x27;t most objects exhibit static electricity?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>In a normal atom, the number of the orbiting electrons is always equal to the number of protons in the nucleus. Since the <strong>magnitude</strong> of the positive charge of the nucleus is equal to <strong>that </strong>of the total negative charge of the electrons. So, a normal atom has no net charge and most objects do not normally exhibit static electricity.</p></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','Rev.7','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>7</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>If the balloon near a wall is charged by rubbing with hair, the charged balloon will stick to a wall. Explain this phenomenon.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>When the balloon is rubbed with human hair, a certain amount of electrons passes from the hair towards the balloon, and the balloon becomes negatively charged body. The negative charges in the balloon repel the free electrons in the wall, leaving positive charges near to the balloon. The attractive force becomes larger than the repulsive force, and the balloon will stick to the wall.</p></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.2','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Choose the correct answer from the following.</strong></em> </p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>A.</p></td><td><p>When an object contains an excess of electrons it has a positive charge. </p></td></tr><tr><td><p>B.</p></td><td><p>When an object contains a deficiency of electrons it has a positive electric charge. </p></td></tr><tr><td><p>C.</p></td><td><p>Since the nuclei of the atoms in an object are positively charged it has a positive electric charge.</p></td></tr><tr><td><p>D.</p></td><td><p>When the electrons of the atoms in an object are positively charged it has a positive electric charge.</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The correct answer is <strong>B.</strong></p></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.3','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Choose the correct answer from the followings:</strong></em> </p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>(i)</p></td><td><p>The charge carriers of the conductor are -------.</p></td></tr><tr><td></td><td><p>(A. protons, &nbsp; B. neutrons, &nbsp; C. free electrons)</p></td></tr><tr><td><p>(ii)</p></td><td><p>------- is a conductor.</p></td></tr><tr><td></td><td><p>(A. Wood, &nbsp; B. Plastic, &nbsp; C. Metal)</p></td></tr><tr><td><p>(iii)</p></td><td><p>The SI unit of the electric charge is -------.</p></td></tr><tr><td></td><td><p>(A. coulomb, &nbsp; B. ampere, &nbsp; C. watt)</p></td></tr><tr><td><p>(iv)</p></td><td><p>When an electron is removed from a normal atom, it becomes ------- ion.</p></td></tr><tr><td></td><td><p>(A. positive, &nbsp; B. negative, &nbsp; C. none of them)</p></td></tr><tr><td><p>(v)</p></td><td><p>There is an electric current in conductor when electrons are -------.</p></td></tr><tr><td></td><td><p>(A. moving, &nbsp; B. at rest, &nbsp; C. none of them)</p></td></tr><tr><td><p>(vi)</p></td><td><p>The magnitude of the charge of an electron is 1.6 × 10<sup>-19</sup> C. A total of 10<sup>4</sup> electrons have been removed from an uncharged pith ball. Its charge now is -------.</p></td></tr><tr><td></td><td><p>(A. + 1.6 × 10<sup>-15</sup> C, &nbsp; B. + 1.6 × 10<sup>-23</sup> C, &nbsp; C. -1.6 × 10<sup>-15</sup> C)</p></td></tr><tr><td><p>(vii)</p></td><td><p>A glass rod becomes positively charged when it is rubbed with silk. The glass rod becomes charged because it -------.</p></td></tr><tr><td></td><td><p>(A. gains protons, &nbsp; B. gains electrons, &nbsp; C. loses electrons)</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(i) C. &nbsp; (ii) C. &nbsp; (iii) A. &nbsp; (iv) A. &nbsp; (v) A. &nbsp; (vi) A. &nbsp; (vii) C.</p></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.4','9','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Match the following:</strong></em></p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>(i)</p></td><td><p>Electron</p></td><td><p>A.</p></td><td><p>Positive charge</p></td></tr><tr><td><p>(ii)</p></td><td><p>Proton</p></td><td><p>B.</p></td><td><p>repel</p></td></tr><tr><td><p>(iii)</p></td><td><p>Like charge</p></td><td><p>C.</p></td><td><p>attract</p></td></tr><tr><td><p>(iv)</p></td><td><p>Unlike charge</p></td><td><p>D.</p></td><td><p>negative charge</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>(i) D. &nbsp; (ii) A. &nbsp; (iii) B. &nbsp; (iv) C</p></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','Rev.2','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Describe an experiment to determine the positions of the poles of a bar magnet.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Suspend bar magnet freely in air. When the suspended bar magnet comes to rest, one end always points towards the northern end of the Earth. This end of the magnet is called the north pole. The other end is the south pole. </p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.3','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What experiment would you conduct to show the magnetic lines around a magnet?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>To show the pattern of a magnetic lines around a bar magnet, we can sprinkle iron filings lightly on a paper, with a bar magnet underneath, and tap the paper gently.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Rev.4','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong>Sketch on Figures, the magnetic field patterns formed between each pair of poles of the magnets. </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong></p><p><strong> &nbsp; </strong>x = neutral point</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','No.2','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A small compass is placed in the uniform magnetic field as shown in figure. </p><p> &nbsp;  &nbsp; To which of the following directions will the compass needle point finally?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; C.</strong></p></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Rev.5','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong>As shown in figure when the switch is closed, which of the following pairs of poles is correct? </p><p> &nbsp; A. P is north and X is south </p><p> &nbsp; B. P is south and X is south</p><p> &nbsp; C. P is north and X is north</p><p> &nbsp; D. P is south and X is north</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','No.4','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Figure shows a strong magnet holding three paperclips. If a weaker magnet brought close to the end of the last clip as shown it will </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. bend away from the magnet. </p><p> &nbsp;  &nbsp; B. bend towards the magnet. </p><p> &nbsp;  &nbsp; C. fall to the ground. </p><p> &nbsp;  &nbsp; D. stay still.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; A.</strong></p></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','Rev.6','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>6</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Experiments were conducted to test the ability of a vertically held bar magnet to attract soft iron nails. The results are shown in the figure (a, b and c).</strong></em></p><p><em><strong> &nbsp; (i)</strong></em><em><strong> &nbsp; What happened to the soft iron nails when they were placed in contact with the magnet? </strong></em></p><p><em><strong> &nbsp; (ii)</strong></em><em><strong> &nbsp; Suggest why the soft iron in Figure (b) picked up almost as many nails as the magnet alone. </strong></em></p><p><em><strong> &nbsp; (iii)</strong></em><em><strong> &nbsp; State and explain what would happen if the magnet was gently removed whilst the soft iron is still holding the 7 nails. </strong></em></p><p><em><strong> &nbsp; (iv)</strong></em><em><strong> &nbsp; Although aluminium is a non-magnetic material, a few nails were attracted to it when it was placed at the end of the magnet. Suggest the reason for this.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>(i)<strong> &nbsp; </strong>The soft iron nails become induced magnets and get attracted to the bar magnet.</p><p><strong> &nbsp; </strong>(ii) &nbsp; The soft iron in Figure (b) picked up almost as many nails as the magnet alone because soft iron is a magnetic material and become induced magnet.</p><p> &nbsp; (iii) When the magnet was gently removed, the 7 iron nails would fall down as the soft iron demagnetised easily.</p><p> &nbsp; (iv) &nbsp; Some of magnetic field lines can pass through the aluminium. So a few nails are attracted to it.</p></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.5','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Which one of the following materials is most suitable for the core of an electromagnet? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A. Steel &nbsp; C. Iron</p><p> &nbsp;  &nbsp;  &nbsp; B. Brass &nbsp; D. Aluminium</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; C.</strong></p></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.6','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Which of the following materials is correctly described? </p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p>Material</p></td><td><p>property</p></td><td><p>use</p></td></tr><tr><td><p>A. iron</p></td><td><p>not easily demagnetized</p></td><td><p>permanent magnet</p></td></tr><tr><td><p>B. iron</p></td><td><p>easily demagnetized</p></td><td><p>electro-magnet</p></td></tr><tr><td><p>C. steel</p></td><td><p>not easily demagnetized</p></td><td><p>electro-magnet</p></td></tr><tr><td><p>D. steel</p></td><td><p>easily demagnetized</p></td><td><p>permanent magnet</p></td></tr></tbody></table></div></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,9,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.7','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>In which device is a permanent magnet used?</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. An electric bell &nbsp;  &nbsp; C. A plotting compass</p><p> &nbsp;  &nbsp; B.  An electromagnet &nbsp; D. A relay</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; C.</strong></p></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.8','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><em><strong>(a) Explain why a greater repulsion is occurred when a N-pole of bar magnet is brought towards the two far ends of the two iron nails for the given figure.</strong></em> </p><p><strong> &nbsp; </strong><em><strong>(b) Suggest what would be observed when a S-pole of another bar magnet is brought towards the two far ends of the two iron-nails in Figure. Explain by an appropriate Figure.</strong></em> </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>(a) By induced magnetism, the two iron nails have N-poles at their far ends and give repulsion. These ends are repelled again by N-pole of the magnet which is brought towards the two far ends. So, it will have greater repulsion. </p><p><strong> &nbsp; </strong>(b) &nbsp; The attractive force between S-pole of a bar magnet and N-pole of the far ends of the two iron nails will occur less repulsion.</p></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','No.9','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>What are the main differences in the magnetic properties of soft iron and steel? How would you demonstrate them, experimentally? For each substance, name an instrument (or) piece of apparatus in which it is used because of its magnetic properties.</strong></em> </p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The main differences in the magnetic properties of soft iron and steel</p><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>The magnetic properties of iron</strong></p></td><td><p><strong>The magnetic properties of steel</strong></p></td></tr><tr><td><p>- &nbsp; can be easily magnetised and demagnetised</p></td><td><p>- &nbsp; is hard to magnetise and demagnetise than iron</p></td></tr><tr><td><p>- &nbsp; can be magnetised by a weak magnetic field</p></td><td><p>- &nbsp; requires a strong magnetic field to magnetise</p></td></tr><tr><td><p>- &nbsp; retains its magnetism temporarily</p></td><td><p>- &nbsp; retains its magnetism permanently</p></td></tr></tbody></table></div><p> &nbsp;  &nbsp; <strong>Experimental determination </strong></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>Since steel is harder to get magnetized than soft iron, less steel pins hang from the magnet.</p><p> &nbsp;  &nbsp; If the topmost pin is gently removed from the magnet, almost all soft iron pins collapse but steel pins may not collapse. Because steel can retain its induced magnetism for considerably long time.</p><p>\\(⇒\\)<strong> &nbsp; </strong><strong>Steel</strong> (permanent magnet) is used in electric metre, loudspeaker, plotting compass.</p><p>\\(⇒\\)<strong> &nbsp; Soft iron</strong> (temporary magnet) is used in the cores of transformers, electric bell.</p></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','No.10','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong><em><strong>Describe briefly, with the help of simple diagrams, if necessary,</strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (a) how would</strong></em><em><strong> </strong></em><em><strong>you magnetise a steel rod PQ using a bar magnet so that P is a     </strong></em><em><strong> &nbsp; </strong></em><em><strong>S-pole; </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (b) how an electric current can be used to make P a S-pole; </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (c) how would you check that the end P was a S-pole after operations (a) and (b); </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (d) an electrical method to demagnetise PQ.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>(a) Stoke the steel rod PQ with N-pole of a permanent magnet several times in the same direction along its length as shown in figure. The magnet must be lifted high above the bar between successive strokes. The end P of the steel rod where the strokes finish has the opposite polarity (S-pole) to that of the stroking magnet in contact with it.</p><p><strong> &nbsp; </strong>(b) &nbsp; Place the steel rod PQ inside a solenoid and a direct current is passed through the solenoid as shown in figure. The solenoid produces a magnetic field that magnetises the steel rod permanently (permanent magnet). When viewing from the end P, the current must be flowing clockwise in the solenoid wire.</p><p> &nbsp; (c) &nbsp; Bring the S-pole of a bar magnet near the end P, if repulsion occurred it was S-pole. </p><p> &nbsp; (d) &nbsp; Place the magnetised steel rod PQ inside a solenoid placed along east-west direction and connect with a low voltage ac supply as shown in figure. Draw the steel rod slowly away from the solenoid while the current is still flowing.</p></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','No.11','10','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong><em><strong>Give brief explanations of the following: </strong></em></p><p><em><strong> &nbsp; (a)</strong></em><em><strong> &nbsp; A piece of soft iron is attracted by a magnet </strong></em></p><p><em><strong> &nbsp; (b) A small bar magnet placed on top of a cork floating on water, does not move towards the north. </strong></em></p><p><em><strong> &nbsp; (c) Two steel needles hanging from the lower end of a vertical bar magnet do not hang vertically in Figure.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>(a) &nbsp; A piece of soft iron is attracted by a magnet due to induced magnetism.</p><p><strong> &nbsp; </strong>(b) &nbsp; A small bar magnet placed on top of a cork floating on water, does not move towards the north because the magnetic force exerted by the earth&#x27;s magnetic field on two poles of the bar magnet are equal and opposite. Therefore, these two forces cancel out and net force is zero. </p><p> &nbsp; (c) &nbsp; Two steel needles hanging from the lower end of a vertical bar magnet do not hang vertically because the two far ends of the needles have both N-poles due to magnetic induction and repel each other. </p></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','Rev.1','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>1</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Under what condition does the thermionic emission occur?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Thermionic emission occurs when a large amount of external energy in the form of heat is supplied to the free electrons in the metals.</p></div></details></div></article>"}'::jsonb,1,true),
(10,'calculations','Rev.2','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>2</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What is vacuum diode?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Vacuum diode is the simplest form of vacuum tube. It consists of two electrodes, a cathode and an anode (or) plate.</p></div></details></div></article>"}'::jsonb,2,true),
(10,'calculations','Rev.3','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>3</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Discuss the essential differences among Thomson&#x27;s model, Rutherford&#x27;s model and Bohr&#x27;s model of an atom.</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong>In Thomson’s mode</strong>l, an atom might be a spherical volume of positive charge with electrons embedded inside it like currant in a bun (or) plums in a pudding.</p><p><strong> &nbsp; </strong><strong>In Rutherford’s model</strong>, the atom must be largely empty space with all of its positive charges and most of its mass concentrated in a small region. This concentrated volume at the centre of the atom is called the nucleus. Negatively charged electrons are moving around the tiny nucleus.</p><p><strong> &nbsp; In Bohr’s model, </strong>electrons move in circular orbits around the nucleus. Only certain orbits are allowed in this model. The electron is never found between the allowed orbits. However, it can jump from one orbit to another. Bohr assumed that the atom does not emit energy in the form of radiation when the electron is in an allowed orbit. Hence the total energy of the atom remains constant.</p></div></details></div></article>"}'::jsonb,3,true),
(10,'calculations','Rev.4','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>4</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Is it possible for the atom of an element to have one electron, one proton and no neutron? If so, name the element. </strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Yes, it is possible, this element is hydrogen, (\\({}_{1}^{1}{H}\\)).</p></div></details></div></article>"}'::jsonb,4,true),
(10,'calculations','Rev.5','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>5</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>Which force holds the electrons and nucleus of an atom to form an atom?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>Coulomb’s force holds the electrons and nucleus of an atom to form an atom. </p></div></details></div></article>"}'::jsonb,5,true),
(10,'calculations','No.12','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.12</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.12.</strong><strong> &nbsp; </strong><em><strong>Which subatomic particle has a negative charge?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>- electron.</p></div></details></div></article>"}'::jsonb,6,true),
(10,'calculations','No.13','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.13</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.13.</strong><strong> &nbsp; </strong><em><strong>Which subatomic particle has a positive charge?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>- proton.</p></div></details></div></article>"}'::jsonb,7,true),
(10,'calculations','No.14','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.14</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.14.</strong><strong> &nbsp; </strong><em><strong>Which subatomic particle is a neutral?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>-<strong> </strong>neutron.</p></div></details></div></article>"}'::jsonb,8,true),
(10,'calculations','No.16','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.16</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.16.</strong><strong> &nbsp; </strong><em><strong>An atom contains electrons, protons, and neutrons. Which of these particles </strong></em></p><p><em><strong> &nbsp; </strong></em><em><strong> &nbsp; (a) are outside the nucleus (b) are uncharged (c) have a negative charge (d) are nucleons (e) are much lighter than the others?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) electrons, &nbsp;  (b) neutrons, (c) electrons, (d) protons and neutrons, (e) electrons.</p></div></details></div></article>"}'::jsonb,9,true),
(10,'calculations','No.17','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.17</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.17.</strong><strong> &nbsp; </strong><em><strong>An aluminium atom has an atomic number of 13 and a mass number of 27. How many (a) protons (b) electrons (c) neutrons does it have?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>(a) 13 protons. &nbsp; (b) 13 electrons,  &nbsp; (c) 14 neutrons.</p></div></details></div></article>"}'::jsonb,10,true),
(10,'calculations','No.18','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.18</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.18.</strong><strong> &nbsp; </strong><em><strong>Chlorine is a mixture of two isotopes, with mass numbers 35 and 37. What is the difference between the two types of atoms?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Two atoms have different number of neutrons (or) different masses.</p></div></details></div></article>"}'::jsonb,11,true),
(10,'calculations','Rev.6','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>6</strong><strong>.</strong><strong> &nbsp; </strong>Express the numerical value of the Plank constant h in terms of eV s.</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>1 eV = 1.6 × \\({10}^{-19}\\) J</p></td></tr><tr><td></td><td><p>Planck constant, h </p></td><td><p>= 6.626 × \\({10}^{-34}\\) J s</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= 6.626 × \\({10}^{-34}\\) J s \\(×\\frac{1 eV}{1.6 × {10}^{-19} J}\\)</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= <strong>4.142 </strong>\\(× {10}^{-15}\\)<strong> eV s</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,12,true),
(10,'calculations','Eg.1','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>If the wavelength of visible light is 0.5 μm, find the energy of the visible light.</p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(1eV = 1.6 \\(× {10}^{-19}\\)J, &nbsp; h = 6.626 \\(× {10}^{-34}\\) J s)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>\\(λ\\) = 0.5 μm = 0.5 × \\({10}^{-6}\\) m= 5 × \\({10}^{-7}\\) m</p></td></tr><tr><td></td><td colspan=\"5\"><p>1 eV = 1.6 × \\({10}^{-19}\\) J, &nbsp;  &nbsp; h = 6.626 \\(× {10}^{-34}\\) J s, &nbsp; c = 3 × \\({10}^{8}\\) m s<sup>-1</sup></p></td></tr><tr><td></td><td><p>E</p></td><td><p>= h f</p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= h \\(\\frac{c}{λ}\\)</p></td><td><p>E</p></td><td><p>= 4 × \\({10}^{-19}\\) J × \\(\\frac{1 eV}{1.6 × {10}^{-19} J}\\)</p></td><td></td></tr><tr><td></td><td></td><td><p><figure><img src=\"cal-media/g11-g10-image4.png\" alt=\"Diagram from the supplied lesson document\" loading=\"lazy\"></figure>= \\(\\frac{6.626 × {10}^{-34} ×3 × {10}^{8}}{5 × {10}^{-7}}\\)</p></td><td></td><td><p>= <strong>2.5 eV</strong></p></td><td></td></tr><tr><td></td><td></td><td><p>= <strong>4 × </strong>\\({10}^{-19}\\)<strong> J</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,13,true),
(10,'calculations','Eg.2','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Eg.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Eg.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>The energy of a certain incident ray is 4.14 eV. What is the frequency of this incident ray?</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>1 eV = 1.6 × \\({10}^{-19}\\) J, &nbsp;  &nbsp; h = 6.626 \\(× {10}^{-34}\\) J s</p></td></tr><tr><td></td><td colspan=\"5\"><p>E = 4.14 eV = 4.14 eV × \\(\\frac{1.6 × {10}^{-19} J}{1 eV}\\) = <strong>4.14 ×1.6 × </strong>\\({10}^{-19}\\)<strong> J</strong></p></td></tr><tr><td></td><td><p>E</p></td><td><p>= h f</p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>f</p></td><td><p>= \\(\\frac{E}{h}\\) </p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{4.14 ×1.6 × {10}^{-19}}{6.626 × {10}^{-34}}\\) = <strong>1 × </strong>\\({10}^{15}\\)<strong> Hz</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,14,true),
(10,'calculations','No.11','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.11</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.11.</strong><strong> &nbsp; </strong>What is the frequency of a photon whose energy is 66.3 eV? </p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>(1eV = 1.6 \\(× {10}^{-19}\\)J, &nbsp; h = 6.625 \\(× {10}^{-34}\\) Js)</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><div class=\"calculation-table-wrap\"><table class=\"calculation-table\"><tbody><tr><td><p><strong>Ans:</strong></p></td><td colspan=\"5\"><p>1 eV = 1.6 × \\({10}^{-19}\\) J, &nbsp;  &nbsp; h = 6.625 \\(× {10}^{-34}\\) J s</p></td></tr><tr><td></td><td colspan=\"5\"><p>E = 66.3 eV = 66.3 eV × \\(\\frac{1.6 × {10}^{-19} J}{1 eV}\\) = <strong>66.3 ×1.6 × </strong>\\({10}^{-19}\\)<strong> J</strong></p></td></tr><tr><td></td><td><p>E</p></td><td><p>= h f</p></td><td></td><td></td><td></td></tr><tr><td></td><td><p>f</p></td><td><p>= \\(\\frac{E}{h}\\) </p></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td><p>= \\(\\frac{66.3 ×1.6 × {10}^{-19}}{6.626 × {10}^{-34}}\\) = <strong>1.601 × </strong>\\({10}^{16}\\)<strong> Hz</strong></p></td><td></td><td></td><td></td></tr></tbody></table></div></div></details></div></article>"}'::jsonb,15,true),
(10,'calculations','No.15','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.15</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.15.</strong><strong> &nbsp; </strong><em><strong>What is thermal radiation? How does it differ from other form of electromagnetic radiation?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; </strong>Thermal radiation is also known as heat radiation, is the electromagnetic waves of wavelength 1 to 100 \\(μ\\)m, emitted from all matter that has a temperature greater than absolute zero (0 K). It differs in wavelength from other form of electromagnetic radiations. </p></div></details></div></article>"}'::jsonb,16,true),
(10,'calculations','Rev.7','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>Rev.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>Rev.</strong><strong>7</strong><strong>.</strong><strong> &nbsp; </strong><em><strong>What is the light year?</strong></em></p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong>The light year (<em>ly</em>) is the distance travelled by light in a vacuum in one year.</p></div></details></div></article>"}'::jsonb,17,true),
(10,'calculations','No.1','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.1</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.1.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The main force responsible for the formation of the universe is:</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. gravity &nbsp;  &nbsp; B. frictional force &nbsp; C. magnetic force &nbsp; D. electrical force</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; A.</strong></p></div></details></div></article>"}'::jsonb,18,true),
(10,'calculations','No.2','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.2</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.2.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The approximate age of the universe is:</strong></em></p><p><strong> </strong><strong> &nbsp; </strong><strong> &nbsp; </strong>A. 1 billion years old and 14 days </p><p> &nbsp;  &nbsp; B. 14 billion years old </p><p> &nbsp;  &nbsp; C. 140 billion years old </p><p> &nbsp;  &nbsp; D. 13.7 billion years old</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; D.</strong></p></div></details></div></article>"}'::jsonb,19,true),
(10,'calculations','No.3','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.3</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.3.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>The first objects to form in the solar system were</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. atoms &nbsp;  &nbsp; B. stars &nbsp;  &nbsp; C. comets &nbsp;  &nbsp; D. planets</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; A.</strong></p></div></details></div></article>"}'::jsonb,20,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(10,'calculations','No.4','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.4</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.4.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following correctly lists the structures in space from smallest to largest?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. Stars, Galaxy, Universe, solar system </p><p> &nbsp;  &nbsp; B. Stars, solar system, Galaxy, Universe </p><p> &nbsp;  &nbsp; C. Stars, solar system, Universe, Galaxy </p><p> &nbsp;  &nbsp; D. Stars, Universe, Solar system, Galaxy</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,21,true),
(10,'calculations','No.5','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.5</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.5.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Our galaxy, the Milky Way, has a pinwheel shape, what type of galaxy is it?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. elliptical &nbsp;  &nbsp; B. fun &nbsp;  &nbsp;  &nbsp; C. irregular &nbsp;  &nbsp; D. spiral</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; D.</strong></p></div></details></div></article>"}'::jsonb,22,true),
(10,'calculations','No.6','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.6</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.6.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following is the best estimate of the number of stars in a typical galaxy?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. hundreds  &nbsp;  &nbsp; B. thousands  &nbsp;  &nbsp; C. millions  &nbsp;  &nbsp; D. billions</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; D.</strong></p></div></details></div></article>"}'::jsonb,23,true),
(10,'calculations','No.7','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.7</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.7.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following is the best estimate of the number of galaxies in the universe?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. hundreds  &nbsp;  &nbsp; B. thousands  &nbsp;  &nbsp; C. millions  &nbsp;  &nbsp; D. billions</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; D.</strong></p></div></details></div></article>"}'::jsonb,24,true),
(10,'calculations','No.8','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.8</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.8.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>A light year measures</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. the distance it takes light to travel in one year </p><p> &nbsp;  &nbsp; B. the distance between stars </p><p> &nbsp;  &nbsp; C. the speed of light </p><p> &nbsp;  &nbsp; D. the wavelength of visible light</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; A.</strong></p></div></details></div></article>"}'::jsonb,25,true),
(10,'calculations','No.9','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.9</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.9.</strong><strong> &nbsp; </strong><strong> &nbsp; </strong><em><strong>Which of the following is the smallest?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. the earth  &nbsp;  &nbsp; B. the universe  &nbsp; C. a galaxy  &nbsp;  &nbsp; D. the sun</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; A.</strong></p></div></details></div></article>"}'::jsonb,26,true),
(10,'calculations','No.10','11','{"html":"<article class=\"problem-card\"><div class=\"problem-number\"><span>No.10</span></div><div class=\"problem-content\"><div class=\"problem-question\"><strong>Q:</strong> <p><strong>No.10.</strong><strong> &nbsp; </strong><em><strong>Which of the following is the largest?</strong></em></p><p><strong> &nbsp; </strong><strong> &nbsp; </strong>A. the earth  &nbsp;  &nbsp; B. the universe  &nbsp; C. a galaxy  &nbsp;  &nbsp; D. the sun</p></div><hr><details><summary><strong>Ans:</strong> အဖြေနှင့် တွက်နည်းကြည့်ရန် နှိပ်ပါ</summary><div class=\"problem-answer\"><p><strong>Ans:</strong><strong> &nbsp; </strong><strong> &nbsp; B.</strong></p></div></details></div></article>"}'::jsonb,27,true);
